INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可分", "is_correct": true, "explanation": "可分是整体可以被分成几部分，与“可以分成三步做”相符。"}, {"text": "统一", "is_correct": false, "explanation": "语义：“统一”指整体不分，与“分成三步做”矛盾。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种、不能细分，与“分成三步”矛盾。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物质，不能用来形容任务。"}], "explanations": {"可分": "可分是整体可以被分成几部分，与“可以分成三步做”相符。", "统一": "语义：“统一”指整体不分，与“分成三步做”矛盾。", "单一": "语义：“单一”指只有一种、不能细分，与“分成三步”矛盾。", "坚硬": "搭配：“坚硬”形容物质，不能用来形容任务。"}, "sentence_index": 0, "correct_answer": "可分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两种颜色是可分的，一眼就能看清。", "explanation": "这里应该用〈可分辨〉。可分指整体能被分成几部分；辨认颜色要用〈可分辨〉。"}, {"text": "这两类动物的特征是可分的，很容易看出差别。", "explanation": "这里应该用〈可区分〉。可分指整体能被分成几部分；看出两类动物的差别要用〈可区分〉。"}, {"text": "这两位作者的笔迹是可分的，一看就认得出是谁写的。", "explanation": "这里应该用〈可辨认〉。可分指整体能被分成几部分；认出笔迹是谁的要用〈可辨认〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可分", "is_correct": true, "explanation": "可分是整体可以被分成几部分，与“可以分给两个孩子”相符。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能用来形容土地。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：“高耸”形容山、楼等高而直立，用于平整的土地不通。"}, {"text": "密闭", "is_correct": false, "explanation": "语义：“密闭”指封闭不通，与“分给两个孩子”矛盾。"}], "explanations": {"可分": "可分是整体可以被分成几部分，与“可以分给两个孩子”相符。", "清澈": "搭配：“清澈”形容水或眼神，不能用来形容土地。", "高耸": "搭配：“高耸”形容山、楼等高而直立，用于平整的土地不通。", "密闭": "语义：“密闭”指封闭不通，与“分给两个孩子”矛盾。"}, "sentence_index": 6, "correct_answer": "可分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两张照片是可分的，一眼就能看出谁是谁。", "explanation": "这里应该用〈可辨别〉。可分指整体能被分成几部分；看出照片里谁是谁要用〈可辨别〉。"}, {"text": "这个路牌是可分的，远远就能认出来。", "explanation": "这里应该用〈可识别〉。可分指整体能被分成几部分；远处认出路牌要用〈可识别〉。"}, {"text": "这种味道是可分的，一闻就能分辨。", "explanation": "这里应该用〈可分辨〉。可分指整体能被分成几部分；辨别气味要用〈可分辨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份方案是可分地，可以分阶段实施。", "corrected_sentence": "这份方案是可分的，可以分阶段实施。", "error_description": "错误形式是“可分地”，正确形式是“可分的”。“可分”作谓语形容词时后面应用“的”，“地”只修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子是可分地，中间能隔开。", "corrected_sentence": "这间屋子是可分的，中间能隔开。", "error_description": "错误形式是“可分地”，正确形式是“可分的”。“可分”作谓语形容词时后面应用“的”；“地”只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内在", "is_correct": true, "explanation": "内在与外在为反义，指内部、看不见的。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "漫长", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "迟缓", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}], "correct_answer": "内在", "explanations": {"内在": "内在与外在为反义，指内部、看不见的。", "陡峭": "与“外在”没有反义关系，不能作其反义词。", "漫长": "与“外在”没有反义关系，不能作其反义词。", "迟缓": "与“外在”没有反义关系，不能作其反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内在", "is_correct": true, "explanation": "内在与外在为反义，指内部、看不见的。"}, {"text": "清脆", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "嘹亮", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}, {"text": "寒冷", "is_correct": false, "explanation": "与“外在”没有反义关系，不能作其反义词。"}], "correct_answer": "内在", "explanations": {"内在": "内在与外在为反义，指内部、看不见的。", "清脆": "与“外在”没有反义关系，不能作其反义词。", "嘹亮": "与“外在”没有反义关系，不能作其反义词。", "寒冷": "与“外在”没有反义关系，不能作其反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "外在是在外面的，能看得见的。", "primary_collocate": null, "pronunciation": "wài zài", "ipa": "wai˥˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "他很看重自己的外在形象。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在美很快会变，内在美更长久。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外在的样子很冷淡，心里却很热。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要只看外在的样子。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在的打扮可以改变，性格很难改。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，外在的整洁很重要。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店外在的样子很旧，里面却很漂亮。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很在意外在的美。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在的变化大家都看得见。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的外在形象会给人好印象。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外在美", "label": "复合"}], "register": "中性", "sense_fingerprint": "表面可见的，外表的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '829b3cd6-c5a4-42fd-b8c9-9e04b05f9127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外在", "is_correct": true, "explanation": "“外在”指看得见的外表，与“形象”搭配，表示外表形象。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容坡度，不能修饰“形象”。"}, {"text": "漫长", "is_correct": false, "explanation": "搭配：“漫长”形容时间或距离，不能修饰“形象”。"}, {"text": "迟缓", "is_correct": false, "explanation": "语义：“迟缓”形容动作速度，与“形象”的语义不合。"}], "explanations": {"外在": "“外在”指看得见的外表，与“形象”搭配，表示外表形象。", "陡峭": "搭配：“陡峭”形容坡度，不能修饰“形象”。", "漫长": "搭配：“漫长”形容时间或距离，不能修饰“形象”。", "迟缓": "语义：“迟缓”形容动作速度，与“形象”的语义不合。"}, "sentence_index": 0, "correct_answer": "外在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的外在运算很快。", "explanation": "这里应该用〈性能〉。“外在”指看得见的外表，运算速度属于内部性能，不能说“外在运算”。"}, {"text": "这篇文章的外在很有深度。", "explanation": "这里应该用〈内容〉。“外在”指外表，文章的深度属于内容。"}, {"text": "这次考试的外在成绩很好。", "explanation": "这里应该用〈分数〉。“外在”指可见的外表，成绩属于结果，不是外表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外在", "is_correct": true, "explanation": "“外在”指店面的外表，与“里面”相对，符合语境。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来描述样子。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音，与“样子”的语义不合。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”形容味道或睡眠，不能用来描述店面的样子。"}], "explanations": {"外在": "“外在”指店面的外表，与“里面”相对，符合语境。", "清脆": "语义：“清脆”形容声音，不能用来描述样子。", "嘹亮": "语义：“嘹亮”形容声音，与“样子”的语义不合。", "香甜": "搭配：“香甜”形容味道或睡眠，不能用来描述店面的样子。"}, "sentence_index": 6, "correct_answer": "外在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "好的外在学问会给人好印象。", "explanation": "这里应该用〈内在〉。“外在”指看得见的外表，学问是人内在的修养，不能说“外在学问”。"}, {"text": "这次演讲的外在很有感染力。", "explanation": "这里应该用〈内容〉。感染力来自内容，不属于外在的外表。"}, {"text": "他的外在心情很好。", "explanation": "这里应该用〈内心〉。“外在”指看得见的外表，心情属于内心的感受，不能说“外在心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很在意自己的外在了打扮。", "corrected_sentence": "他很在意自己的外在打扮。", "error_description": "错误：“外在”是修饰“打扮”的形容词，后面不能加“了”。正确：“外在打扮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆车外在的样子很外在新。", "corrected_sentence": "这辆车外在的样子很新。", "error_description": "错误：“外在”只修饰名词，不能修饰形容词“新”，多出的“外在”应删去。正确：“这辆车外在的样子很新。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
