INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "存在于事物外部的；非本身固有的。", "primary_collocate": null, "pronunciation": "wài zài", "ipa": "wai˥˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "成功不只靠外在条件。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在的压力有时会变成动力。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题的外在原因很多。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的变化受外在环境影响。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿接受外在的评价。", "target_word": "外在", "complexity_tier": "T3", "furigana": "tā bù yuàn jiē shòu wài zài de píng jià.", "sentence_source": "generated"}, {"text": "内在的想法比外在的条件更重要。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外在因素和内在原因都要考虑。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败主要是外在原因。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要让外在的变化影响你的心情。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司遇到了外在的困难。", "target_word": "外在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外在因素", "label": "复合"}], "register": "中性", "sense_fingerprint": "来自事物外部的，非自身固有的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '829b3cd6-c5a4-42fd-b8c9-9e04b05f9127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外在", "is_correct": true, "explanation": "“外在”指事物外部的条件，与“不只靠”的语境相合。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外表，不能修饰“条件”。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面喧闹，与“成功靠条件”的语义不搭。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”指排列有序，不能用来说明成功的条件。"}], "explanations": {"外在": "“外在”指事物外部的条件，与“不只靠”的语境相合。", "漂亮": "体貌：“漂亮”形容外表，不能修饰“条件”。", "热闹": "语义：“热闹”指场面喧闹，与“成功靠条件”的语义不搭。", "整齐": "语义：“整齐”指排列有序，不能用来说明成功的条件。"}, "sentence_index": 0, "correct_answer": "外在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的外在硬度很高。", "explanation": "这里应该用〈内在〉。“外在”指外部的、非固有的，硬度是石头自身固有的属性，不能说“外在硬度”。"}, {"text": "他的外在本领很强。", "explanation": "这里应该用〈能力〉。“外在”指非固有的外部因素，本领是人自身固有的能力，不能说“外在本领”。"}, {"text": "他的外在心事很重。", "explanation": "这里应该用〈心里〉。“外在”指外部的、看得见的，心事藏在心里，不能说“外在心事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外在", "is_correct": true, "explanation": "“外在”修饰“因素”，指外部的、非固有的因素，与“内在原因”相对。"}, {"text": "鲜艳", "is_correct": false, "explanation": "体貌：“鲜艳”形容颜色，不能修饰“因素”。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”形容人的品格，不能用来形容因素。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容质地，不能修饰“因素”。"}], "explanations": {"外在": "“外在”修饰“因素”，指外部的、非固有的因素，与“内在原因”相对。", "鲜艳": "体貌：“鲜艳”形容颜色，不能修饰“因素”。", "慷慨": "语义：“慷慨”形容人的品格，不能用来形容因素。", "粗糙": "搭配：“粗糙”形容质地，不能修饰“因素”。"}, "sentence_index": 6, "correct_answer": "外在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这头牛的外在力气很大。", "explanation": "这里应该用〈体力〉。“外在”指非固有的外部因素，力气是牛自身的体力，不能说“外在力气”。"}, {"text": "这篇文章的外在很有深度。", "explanation": "这里应该用〈内容〉。“外在”指非固有的外部因素，文章的深度属于内容，不属于外在。"}, {"text": "这首歌的外在很动听。", "explanation": "这里应该用〈旋律〉。“外在”指事物外部的、非固有的，歌曲好听与否取决于旋律，不能用“外在”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的外在条件比我外在很多。", "corrected_sentence": "他的外在条件比我好很多。", "error_description": "词性误用：“外在”是属性词，只修饰名词，不能作“比”字句的谓语，此处应用“好”。正确：“他的外在条件比我好很多。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛遇到了外在地困难。", "corrected_sentence": "这次比赛遇到了外在的困难。", "error_description": "的/地误用：“外在”修饰名词“困难”，应用“的”，不能用“地”。正确：“外在的困难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小环境", "is_correct": true, "explanation": "小环境指我们身边局部、个人周围的情况，与广阔的大环境相对。"}, {"text": "历史", "is_correct": false, "explanation": "历史指过去发生的事情，与大环境没有相对关系。"}, {"text": "内心", "is_correct": false, "explanation": "内心指人的心里，与大环境没有相对关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气指一时的冷暖晴雨，与大环境不是相对的词。"}], "correct_answer": "小环境", "explanations": {"小环境": "小环境指我们身边局部、个人周围的情况，与广阔的大环境相对。", "历史": "历史指过去发生的事情，与大环境没有相对关系。", "内心": "内心指人的心里，与大环境没有相对关系。", "天气": "天气指一时的冷暖晴雨，与大环境不是相对的词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小环境", "is_correct": true, "explanation": "小环境指我们身边局部、个人周围的情况，与广阔的大环境相对。"}, {"text": "工资", "is_correct": false, "explanation": "工资指劳动报酬，与大环境没有相对关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是房屋的构件，与大环境没有相对关系。"}, {"text": "数学", "is_correct": false, "explanation": "数学是一门学科，与大环境没有相对关系。"}], "correct_answer": "小环境", "explanations": {"小环境": "小环境指我们身边局部、个人周围的情况，与广阔的大环境相对。", "工资": "工资指劳动报酬，与大环境没有相对关系。", "窗户": "窗户是房屋的构件，与大环境没有相对关系。", "数学": "数学是一门学科，与大环境没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大环境是我们周围很大的一片情况。", "primary_collocate": null, "pronunciation": "dà huán jìng", "ipa": "ta˥˩ xuan˧˥ tɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "现在的大环境对学生来说不太好。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年大环境不好，生意不容易做。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们很难改变大环境，只能改变自己。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大环境好了，大家的生活也会更好。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说工作难找，是因为大环境。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这样的大环境里，大家都很努力。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大环境不太好，所以我们要多存一点钱。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他换了工作，也是考虑到大环境才决定的。", "target_word": "大环境", "complexity_tier": "T3", "furigana": "dà huán jìng", "sentence_source": "generated"}, {"text": "小公司在大环境不好时，很容易遇到问题。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大环境变好以后，这个城市的生意又多起来了。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小环境", "label": "复合（相对的词）"}], "register": "中性", "sense_fingerprint": "大环境：我们周围整体的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed0c4cfe-367f-4222-8eac-27cac2d37f6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大环境", "is_correct": true, "explanation": "大环境指整体的社会与经济情况，说它“对学生来说不太好”符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，与“对学生来说不太好”的整体情况无关。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”只用来形容人的外貌，不能用来说整体情况。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：年纪指人的岁数，不能用来表示学生所处的整体情况。"}], "explanations": {"大环境": "大环境指整体的社会与经济情况，说它“对学生来说不太好”符合语境。", "身高": "语义：身高指身体的高矮，与“对学生来说不太好”的整体情况无关。", "长相": "体貌：“长相”只用来形容人的外貌，不能用来说整体情况。", "年纪": "语义：年纪指人的岁数，不能用来表示学生所处的整体情况。"}, "sentence_index": 0, "correct_answer": "大环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的大环境很好。", "explanation": "这里应该用〈味道〉。大环境指社会整体条件，不是菜的口味，不能用来评价一道菜。"}, {"text": "他的大环境很高。", "explanation": "这里应该用〈个子〉。大环境不是人的身体，没有高矮，不能这样描述一个人。"}, {"text": "这首歌的大环境很好听。", "explanation": "这里应该用〈旋律〉。大环境指社会整体条件，不是歌曲的旋律，不能用来评价歌好不好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大环境", "is_correct": true, "explanation": "大环境指整体的社会与经济形势，“不太好”说明经济环境不佳，所以要多存钱。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指一时的冷暖晴雨，与“要多存一点钱”的经济原因无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般说“大”或“小”，不说“好”或“不好”。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是文字的样式，不能作为影响存钱的整体条件。"}], "explanations": {"大环境": "大环境指整体的社会与经济形势，“不太好”说明经济环境不佳，所以要多存钱。", "天气": "语义：天气指一时的冷暖晴雨，与“要多存一点钱”的经济原因无关。", "年龄": "搭配：“年龄”一般说“大”或“小”，不说“好”或“不好”。", "字体": "语义：字体是文字的样式，不能作为影响存钱的整体条件。"}, "sentence_index": 6, "correct_answer": "大环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上的大环境很鲜艳。", "explanation": "这里应该用〈颜色〉。大环境指社会整体条件，不能用来形容墙面的颜色。"}, {"text": "电视的大环境很大。", "explanation": "这里应该用〈音量〉。大环境指整体背景情况，不能用来形容电视声音的大小。"}, {"text": "他的大环境很胖。", "explanation": "这里应该用〈体型〉。大环境不是人的身体，不能用“很胖”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张大环境对学生的影响越来越大。", "corrected_sentence": "这个大环境对学生的影响越来越大。", "error_description": "量词错误：“大环境”应搭配量词“个”，说“这个大环境”；“张”用于平面的东西，不能用于大环境这样抽象的情况。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年大环境的对店铺很不利，很多人都不敢开店了。", "corrected_sentence": "这几年大环境对店铺很不利，很多人都不敢开店了。", "error_description": "“大环境”后多加了“的”，“大环境的对店铺很不利”不成句，应去掉“的”，说“大环境对店铺很不利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小环境", "is_correct": true, "explanation": "小环境指身边局部、个人周围的条件，与广阔的大环境相对。"}, {"text": "内心", "is_correct": false, "explanation": "内心指人的心里，与大环境没有相对关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气指一时的冷暖晴雨，与大环境不是相对的词。"}, {"text": "历史", "is_correct": false, "explanation": "历史指过去发生的事情，与大环境没有相对关系。"}], "correct_answer": "小环境", "explanations": {"小环境": "小环境指身边局部、个人周围的条件，与广阔的大环境相对。", "内心": "内心指人的心里，与大环境没有相对关系。", "天气": "天气指一时的冷暖晴雨，与大环境不是相对的词。", "历史": "历史指过去发生的事情，与大环境没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小环境", "is_correct": true, "explanation": "小环境指身边局部、个人周围的条件，与广阔的大环境相对。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是房屋的构件，与大环境没有相对关系。"}, {"text": "性格", "is_correct": false, "explanation": "性格指人的脾气特点，与大环境没有相对关系。"}, {"text": "工资", "is_correct": false, "explanation": "工资指劳动报酬，与大环境没有相对关系。"}], "correct_answer": "小环境", "explanations": {"小环境": "小环境指身边局部、个人周围的条件，与广阔的大环境相对。", "窗户": "窗户是房屋的构件，与大环境没有相对关系。", "性格": "性格指人的脾气特点，与大环境没有相对关系。", "工资": "工资指劳动报酬，与大环境没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对某个人或事物产生影响的广阔社会背景或整体条件。", "primary_collocate": null, "pronunciation": "dà huán jìng", "ipa": "ta˥˩ xuan˧˥ tɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "大环境不好，很多公司都在减少人员。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在现在的大环境下，找工作不容易。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成功，离不开当时好的大环境。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大环境变了，我们的生活方式也要变。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受大环境的影响，今年的工资没有涨。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济大环境不好的时候，人们花钱会更小心。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司再努力，也很难改变整个行业的大环境。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的大环境能给年轻人更多的机会。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然大环境很难，但是他没有放弃过。", "target_word": "大环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大环境对每个人都有影响，不只是公司。", "target_word": "大环境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小环境", "label": "复合（相对的词）"}], "register": "中性", "sense_fingerprint": "大环境：影响个人或行业的整体社会背景与条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed0c4cfe-367f-4222-8eac-27cac2d37f6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大环境", "is_correct": true, "explanation": "大环境指影响各行各业的整体社会与经济背景，与“很多公司都在减少人员”的宏观原因相符。"}, {"text": "小环境", "is_correct": false, "explanation": "语义：小环境指身边局部的环境，不能概括很多公司都在减员的整体局面。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指人的外貌，不能用来形容整个社会环境。"}, {"text": "身体", "is_correct": false, "explanation": "语义：“身体”指人的健康状况，与公司减少人员的原因无关。"}], "explanations": {"大环境": "大环境指影响各行各业的整体社会与经济背景，与“很多公司都在减少人员”的宏观原因相符。", "小环境": "语义：小环境指身边局部的环境，不能概括很多公司都在减员的整体局面。", "长相": "体貌：“长相”指人的外貌，不能用来形容整个社会环境。", "身体": "语义：“身体”指人的健康状况，与公司减少人员的原因无关。"}, "sentence_index": 0, "correct_answer": "大环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议室里的大环境很轻松。", "explanation": "这里应该用〈气氛〉。大环境指影响行业或个人的整体社会条件，不能用来形容会议室里的轻松氛围。"}, {"text": "这个房间的大环境很大。", "explanation": "这里应该用〈空间〉。“空间”指房间的大小，大环境指社会整体背景，不能用来说房间有多大。"}, {"text": "这只杯子的大环境很精致。", "explanation": "这里应该用〈做工〉。大环境指影响行业或个人的社会整体条件，不是杯子的做工，不能用来评价杯子精不精致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大环境", "is_correct": true, "explanation": "大环境指行业所处的整体社会与经济条件，是“改变”的对象，这里说公司难以改变它。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“改变”的对象不能是“年龄”，年龄不会因公司努力而改变。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物身体的重量，不能指整个行业的条件。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别是人的特征，行业没有性别，也不能被改变。"}], "explanations": {"大环境": "大环境指行业所处的整体社会与经济条件，是“改变”的对象，这里说公司难以改变它。", "年龄": "搭配：“改变”的对象不能是“年龄”，年龄不会因公司努力而改变。", "体重": "语义：体重指人或动物身体的重量，不能指整个行业的条件。", "性别": "语义：性别是人的特征，行业没有性别，也不能被改变。"}, "sentence_index": 6, "correct_answer": "大环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司里的大环境很高。", "explanation": "这里应该用〈地位〉。大环境指影响整体的社会或经济条件，不是人在组织中的位置，不能用“很高”来形容。"}, {"text": "他的大环境很苗条。", "explanation": "这里应该用〈身材〉。大环境不是人，没有身材，不能用“很苗条”来形容。"}, {"text": "这块蛋糕的大环境很甜。", "explanation": "这里应该用〈味道〉。大环境指社会整体条件，不是蛋糕的味道，不能用来说蛋糕甜不甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只大环境对年轻人很不利。", "corrected_sentence": "这个大环境对年轻人很不利。", "error_description": "量词错误：“大环境”是抽象的社会背景，应搭配量词“个”，说“这个大环境”；“只”用于动物或成对物品中的一只，不能用于大环境。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年大环境的对小公司很不利，很多店都关门了。", "corrected_sentence": "这几年大环境对小公司很不利，很多店都关门了。", "error_description": "“大环境”后多加了“的”，“大环境的对小公司很不利”不成句，应去掉“的”，说“大环境对小公司很不利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
