INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94135, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94135, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "射击是用枪或弓把东西打出去，打中远处的目标。", "primary_collocate": null, "pronunciation": "shè jī", "ipa": "ʂɤ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "他举起枪，向远处的靶子射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥喜欢射击，每周都去练习。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员站好后，对准十米外的靶心射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么拿枪射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他射击了三次，都打中了靶心。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次射击就打中了靶子。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先看准目标，再慢慢射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟闭上一只眼睛，对着气球射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始了，选手们开始射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他趴在地上，向五十米外的靶子射击。", "target_word": "射击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "射击了", "label": "体标：了"}, {"form": "射击过", "label": "体标：过"}, {"form": "射击着", "label": "体标：着"}, {"form": "射击场", "label": "复合词"}, {"form": "射击手", "label": "复合词"}, {"form": "射擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "射击：用枪或弓瞄准并打中远处的靶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee3e7df-b1b0-4578-906e-2115242cea45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94135, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "射击", "is_correct": true, "explanation": "射击是用枪或弓把东西打出去，打中远处的目标。"}, {"text": "设计", "is_correct": false, "explanation": "shè jì 与 shè jī 的第二音节声调不同（第四声与第一声），意思是设计。"}, {"text": "涉及", "is_correct": false, "explanation": "jí 与 jī 声调不同（第二声与第一声），意思是涉及。"}, {"text": "舍己", "is_correct": false, "explanation": "shě jǐ 与 shè jī 的两个音节都只差声调（第三声对第四声、第三声对第一声），意思是牺牲自己。"}], "explanations": {"射击": "射击是用枪或弓把东西打出去，打中远处的目标。", "设计": "shè jì 与 shè jī 的第二音节声调不同（第四声与第一声），意思是设计。", "涉及": "jí 与 jī 声调不同（第二声与第一声），意思是涉及。", "舍己": "shě jǐ 与 shè jī 的两个音节都只差声调（第三声对第四声、第三声对第一声），意思是牺牲自己。"}, "sentence_index": null, "correct_answer": "射击"}, "level_3": {"options": [{"text": "射击", "is_correct": true, "explanation": "射击是用枪或弓瞄准并打中目标，与“向远处的靶子”相符。"}, {"text": "投掷", "is_correct": false, "explanation": "语义：“投掷”指扔出去，与“举起枪”的动作不符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“靶子”作宾语。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是景物或作品，不能说欣赏靶子。"}], "explanations": {"射击": "射击是用枪或弓瞄准并打中目标，与“向远处的靶子”相符。", "投掷": "语义：“投掷”指扔出去，与“举起枪”的动作不符。", "散步": "配价：“散步”是不及物动词，不能带“靶子”作宾语。", "欣赏": "搭配：“欣赏”的对象是景物或作品，不能说欣赏靶子。"}, "sentence_index": 0, "correct_answer": "射击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抬脚射击，把球踢进了球门。", "explanation": "这里应该用〈射门〉。足球把球踢进球门要说射门；射击只指用枪弓发射。"}, {"text": "水从管子里射击出来，溅了一地。", "explanation": "这里应该用〈喷射〉。液体从管口喷出要说喷射；射击只指用武器发射。"}, {"text": "他射击了一段视频。", "explanation": "这里应该用〈拍摄〉。录制影像要说拍摄；射击只指用武器打出弹药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "射击", "is_correct": true, "explanation": "射击是用武器打中目标，与“看准目标”后再动作相符。"}, {"text": "冲刺", "is_correct": false, "explanation": "语义：“冲刺”指快速向前冲，与“慢慢”矛盾。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”的对象多是资源、潜力，不能说挖掘目标。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指不再坚持，与“看准目标”的意思相反。"}], "explanations": {"射击": "射击是用武器打中目标，与“看准目标”后再动作相符。", "冲刺": "语义：“冲刺”指快速向前冲，与“慢慢”矛盾。", "挖掘": "搭配：“挖掘”的对象多是资源、潜力，不能说挖掘目标。", "放弃": "语义：“放弃”指不再坚持，与“看准目标”的意思相反。"}, "sentence_index": 6, "correct_answer": "射击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力射击一块石头，打中了树。", "explanation": "这里应该用〈投掷〉。把石块扔出去要说投掷；射击只指用枪炮弓发射。"}, {"text": "阳光从窗户射击进来，照亮了地板。", "explanation": "这里应该用〈照射〉。光线照到物体上要说照射；射击只指用武器发射。"}, {"text": "树的影子射击在地上，一动不动。", "explanation": "这里应该用〈投射〉。影子落在地面上叫投射；射击只用于发射弹药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把远处的靶子射击。", "corrected_sentence": "他对着远处的靶子射击。", "error_description": "错误形式是“把远处的靶子射击”，正确形式是“对着远处的靶子射击”。“射击”不能用“把”字句处置靶子，目标应用“对着”或“朝”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵给远处的目标射击。", "corrected_sentence": "士兵向远处的目标射击。", "error_description": "错误形式是“给远处的目标射击”，正确形式是“向远处的目标射击”。引出射击目标应用“向”或“朝”，不用“给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
