INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94139, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "屋是人住的房子，或房子里的一间。", "primary_collocate": null, "pronunciation": "wū", "ipa": "u˥", "syllable_count": 1, "sentences": [{"text": "这间屋很小，但是很干净。", "target_word": "屋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人住在这间屋。", "target_word": "屋", "complexity_tier": "T3", "furigana": "wū", "sentence_source": "generated"}, {"text": "天黑了，我们快进屋吧。", "target_word": "屋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山下有一间旧屋。", "target_word": "屋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的屋里有很多花。", "target_word": "屋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面很冷，请到屋里坐。", "target_word": "屋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在屋里看书。", "target_word": "屋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这间屋是我新租的。", "target_word": "屋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人在河边盖了一间屋。", "target_word": "屋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的屋在二楼，朝南。", "target_word": "屋", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "屋子", "label": "复合词"}, {"form": "房屋", "label": "复合词"}, {"form": "屋顶", "label": "复合词"}], "register": "通用", "sense_fingerprint": "人住的房子或其中的一个房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e60ece-b0ef-49ed-9e2f-beaff451da86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94139, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "屋", "is_correct": true, "explanation": "正确：屋（wū，第一声）指人住的房子或房间。"}, {"text": "五", "is_correct": false, "explanation": "五（wǔ，第三声）与 wū（第一声）声调不同，意思是数字“五”。"}, {"text": "物", "is_correct": false, "explanation": "物（wù，第四声）与 wū（第一声）声调不同，意思是东西、事物。"}, {"text": "无", "is_correct": false, "explanation": "无（wú，第二声）与 wū（第一声）声调不同，意思是没有。"}, {"text": "误", "is_correct": false, "explanation": "误（wù，第四声）与 wū（第一声）声调不同，意思是错误。"}], "explanations": {"屋": "正确：屋（wū，第一声）指人住的房子或房间。", "五": "五（wǔ，第三声）与 wū（第一声）声调不同，意思是数字“五”。", "物": "物（wù，第四声）与 wū（第一声）声调不同，意思是东西、事物。", "无": "无（wú，第二声）与 wū（第一声）声调不同，意思是没有。", "误": "误（wù，第四声）与 wū（第一声）声调不同，意思是错误。"}, "sentence_index": null, "correct_answer": "屋"}, "level_3": {"options": [{"text": "屋", "is_correct": true, "explanation": "正确：“屋”是房子或房间，与“这间……很小，很干净”相符。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词“间”用于房屋，不用于动物，“这间猫”不成立。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”不是可以住的空间，“很小，很干净”的“间”指房间，句子不通。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：量词“间”不用于鱼类，“这间鱼”不成立。"}], "explanations": {"屋": "正确：“屋”是房子或房间，与“这间……很小，很干净”相符。", "猫": "搭配：量词“间”用于房屋，不用于动物，“这间猫”不成立。", "饭": "语义：“饭”不是可以住的空间，“很小，很干净”的“间”指房间，句子不通。", "鱼": "搭配：量词“间”不用于鱼类，“这间鱼”不成立。"}, "sentence_index": 0, "correct_answer": "屋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只屋。", "explanation": "这里应该用〈间〉。“只”用于动物等，房屋常用“间、座、所”。"}, {"text": "他借了一张屋。", "explanation": "这里应该用〈间〉。“张”多用于桌子、纸张等，不用于“屋”。"}, {"text": "山下有一本屋。", "explanation": "这里应该用〈间〉。“本”用于书籍，不用于“屋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94139, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "屋", "is_correct": true, "explanation": "正确：屋（wū，第一声）指人住的房子或房间。"}, {"text": "午", "is_correct": false, "explanation": "午（wǔ，第三声）与 wū（第一声）声调不同，意思是中午。"}, {"text": "舞", "is_correct": false, "explanation": "舞（wǔ，第三声）与 wū（第一声）声调不同，意思是跳舞。"}, {"text": "武", "is_correct": false, "explanation": "武（wǔ，第三声）与 wū（第一声）声调不同，意思是武力、军事。"}, {"text": "雾", "is_correct": false, "explanation": "雾（wù，第四声）与 wū（第一声）声调不同，意思是雾气。"}], "explanations": {"屋": "正确：屋（wū，第一声）指人住的房子或房间。", "午": "午（wǔ，第三声）与 wū（第一声）声调不同，意思是中午。", "舞": "舞（wǔ，第三声）与 wū（第一声）声调不同，意思是跳舞。", "武": "武（wǔ，第三声）与 wū（第一声）声调不同，意思是武力、军事。", "雾": "雾（wù，第四声）与 wū（第一声）声调不同，意思是雾气。"}, "sentence_index": null, "correct_answer": "屋"}, "level_3": {"options": [{"text": "屋", "is_correct": true, "explanation": "正确：“在……里看书”要接能容纳人的房间，“屋”与之相符。"}, {"text": "墙", "is_correct": false, "explanation": "语义：“墙”不是可以看书的空间，“爸爸在墙里看书”荒谬。"}, {"text": "窗", "is_correct": false, "explanation": "搭配：“在……里”要接能容纳人的空间，“窗”不能这样用，应说“在窗前”。"}, {"text": "碗", "is_correct": false, "explanation": "语义：“碗”是盛饭的器具，人不能在碗里看书。"}], "explanations": {"屋": "正确：“在……里看书”要接能容纳人的房间，“屋”与之相符。", "墙": "语义：“墙”不是可以看书的空间，“爸爸在墙里看书”荒谬。", "窗": "搭配：“在……里”要接能容纳人的空间，“窗”不能这样用，应说“在窗前”。", "碗": "语义：“碗”是盛饭的器具，人不能在碗里看书。"}, "sentence_index": 6, "correct_answer": "屋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去屋买东西。", "explanation": "这里应该用〈商店〉。“屋”指房子或房间，不能作买东西的地方，买东西应去〈商店〉。"}, {"text": "我把屋撕碎了。", "explanation": "这里应该用〈纸〉作宾语。“屋”是建筑，不能被撕碎，“撕碎”的对象应是纸之类的物品。"}, {"text": "屋吃饭了。", "explanation": "这里应该用〈人〉作主语。“屋”是房子，不会吃饭，不能作“吃”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只屋是我小时候住的。", "corrected_sentence": "那间屋是我小时候住的。", "error_description": "错误：“只”；正确：“间”。“屋”的量词用“间”，用“只”是把动物量词误用于房屋。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在一台屋里看电视。", "corrected_sentence": "我在一间屋里看电视。", "error_description": "错误：“一台屋”；正确：“一间屋”。“屋”用量词“间”，“台”多用于机器、电视等，不用于房屋。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
