INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94151, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94151, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把握是抓住机会，不让它溜走。", "primary_collocate": null, "pronunciation": "bǎ wò", "ipa": "pa˨˩ wo˥˩", "syllable_count": 2, "sentences": [{"text": "这次机会很难得，你一定要把握。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人应该把握每一个学习的机会。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把握住了这个难得的机会，成功了。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好时机不多，你要学会把握。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很会把握机会，所以进步得很快。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王没能把握好这次面试的机会，有点难过。", "target_word": "把握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在等机会，今天终于把握住了。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机会来了，就要马上把握，不要等。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把握这个好机会，好好准备明天的比赛。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说过，人生中的好机会，要自己去把握。", "target_word": "把握", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把握了", "label": "体标（了）"}, {"form": "把握住", "label": "结果补语"}, {"form": "把握好", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "把握机会：抓住时机，不错过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed0c4cfe-367f-4222-8eac-27cac2d37f6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "把握", "is_correct": true, "explanation": "正确。“一定要把握”即抓住这难得的机会，与前句“机会很难得”前后一致。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“机会很难得”和“一定要”的劝告语气相反，句意自相矛盾。"}, {"text": "错过", "is_correct": false, "explanation": "语义：“错过”是让机会溜走，与“一定要”的要求相反。"}, {"text": "摒弃", "is_correct": false, "explanation": "语域：“摒弃”偏书面，含舍弃的意味，与口语劝告的语境不合。"}], "explanations": {"把握": "正确。“一定要把握”即抓住这难得的机会，与前句“机会很难得”前后一致。", "放弃": "语义：“放弃”与“机会很难得”和“一定要”的劝告语气相反，句意自相矛盾。", "错过": "语义：“错过”是让机会溜走，与“一定要”的要求相反。", "摒弃": "语域：“摒弃”偏书面，含舍弃的意味，与口语劝告的语境不合。"}, "sentence_index": 0, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们终于把握了最后一班车。", "explanation": "这里应该用〈赶上〉。“赶上”表示及时搭上车；此义的“把握”只用于机会、时机等抽象的事情，不能用于班车。"}, {"text": "他把握住了那个小偷，不让他跑掉。", "explanation": "这里应该用〈抓住〉。“抓住”用于人或具体的东西；此义的“把握”只用于机会和时机，不能用于抓人。"}, {"text": "他很快就把握了那个名字。", "explanation": "这里应该用〈记住〉。“记住”用于名字、内容等；此义的“把握”只用于机会和时机，不能用于记住名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拦", "is_correct": false, "explanation": "语义：“拦住”是阻止，与“一直在等机会”的语境矛盾。"}, {"text": "把握", "is_correct": true, "explanation": "正确。“终于把握住了”表示抓住了等待已久的机会，前后一致。"}, {"text": "挡", "is_correct": false, "explanation": "语义：“挡住”表示阻挡，与“等机会”之后“终于”抓住的语境相反。"}, {"text": "推", "is_correct": false, "explanation": "搭配：“推”与“机会”不搭配，不能说推住机会。"}], "explanations": {"拦": "语义：“拦住”是阻止，与“一直在等机会”的语境矛盾。", "把握": "正确。“终于把握住了”表示抓住了等待已久的机会，前后一致。", "挡": "语义：“挡住”表示阻挡，与“等机会”之后“终于”抓住的语境相反。", "推": "搭配：“推”与“机会”不搭配，不能说推住机会。"}, "sentence_index": 6, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把握着手中的笔，不肯放下。", "explanation": "这里应该用〈攥〉。“攥”指用手紧紧抓着具体的东西；此义的“把握”只用于机会、时机等抽象的事情，不能用于手中的笔。"}, {"text": "他把握了这次的生日，请大家吃饭。", "explanation": "这里应该用〈攀〉。“攀”用于爬树、爬山；此义的“把握”不能用于树木。"}, {"text": "他把握了那棵大树，爬了上去。", "explanation": "这里应该用〈攀〉。“攀”用于爬树、爬山，“把握”不能用于树木。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快就把握了住那次机会。", "corrected_sentence": "他很快就把握住了那次机会。", "error_description": "“把握住”是结果补语结构，“住”要紧接动词，应说“把握住了”，不能说“把握了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没把握住了那次机会。", "corrected_sentence": "他没把握住那次机会。", "error_description": "“没”表示否定时不能与“了”同用，应说“没把握住”，不能说“没把握住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
