INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "紧紧抓住，不放过；掌握。", "primary_collocate": null, "pronunciation": "bǎ wò", "ipa": "pa˨˩ wo˥˩", "syllable_count": 2, "sentences": [{"text": "读文章时，要把握重点。", "target_word": "把握", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "说话要把握好分寸。", "target_word": "把握", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师帮我们把握学习的方向。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要把握好市场的变化。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会把握说话的时间和节奏。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章不长，但我没能把握住主要意思。", "target_word": "把握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写作文要把握主题，不能离题。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把握着事情的大方向，细节让别人做。", "target_word": "把握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生需要准确把握病人的情况。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要写好故事，先要把握人物的性格。", "target_word": "把握", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "把握住", "label": "结果补语"}, {"form": "把握好", "label": "结果补语"}, {"form": "把握着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "把握重点、方向、分寸：牢牢抓住并掌握", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed0c4cfe-367f-4222-8eac-27cac2d37f6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽略", "is_correct": false, "explanation": "语义：“忽略重点”与“读文章时要……”的要求相反，句意不通。"}, {"text": "把握", "is_correct": true, "explanation": "正确。“读文章时要把握重点”即抓住并掌握要点，语义通顺。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃重点”与读文章的要求相悖，句意不通。"}, {"text": "摒弃", "is_correct": false, "explanation": "语域：“摒弃”偏书面，含舍弃的意味，与日常读文章的口语提醒不合。"}], "explanations": {"忽略": "语义：“忽略重点”与“读文章时要……”的要求相反，句意不通。", "把握": "正确。“读文章时要把握重点”即抓住并掌握要点，语义通顺。", "放弃": "语义：“放弃重点”与读文章的要求相悖，句意不通。", "摒弃": "语域：“摒弃”偏书面，含舍弃的意味，与日常读文章的口语提醒不合。"}, "sentence_index": 0, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要把握好这次的晚饭。", "explanation": "这里应该用〈做〉。“做好晚饭”是常见说法，“把握”不能用于做饭。"}, {"text": "他很会把握做饭的油烟。", "explanation": "这里应该用〈排〉。“排油烟”是常见说法，“把握”不能用于油烟。"}, {"text": "我们一定要把握住这扇窗户。", "explanation": "这里应该用〈关〉。“关”用于门窗，“把握”不能用于窗户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏离", "is_correct": false, "explanation": "语义：“偏离主题”就是离题，与“不能离题”的要求矛盾。"}, {"text": "把握", "is_correct": true, "explanation": "正确。“写作文要把握主题”即掌握并围绕主题写作，与“不能离题”相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记主题”与“不能离题”的要求矛盾，句意不通。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除主题”与“要把握主题”的要求相反，句意不通。"}], "explanations": {"偏离": "语义：“偏离主题”就是离题，与“不能离题”的要求矛盾。", "把握": "正确。“写作文要把握主题”即掌握并围绕主题写作，与“不能离题”相符。", "忘记": "语义：“忘记主题”与“不能离题”的要求矛盾，句意不通。", "删除": "语义：“删除主题”与“要把握主题”的要求相反，句意不通。"}, "sentence_index": 6, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把握了那件新衣服。", "explanation": "这里应该用〈穿〉。“穿”用于衣服，“把握”不能用于衣物。"}, {"text": "工人们正在把握这座楼的玻璃。", "explanation": "这里应该用〈装〉。“装玻璃”是常见说法，“把握”不能用于安装玻璃。"}, {"text": "他把握了一盒牛奶。", "explanation": "这里应该用〈喝〉。“喝”用于牛奶等饮品，“把握”不能用于牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对市场的变化把握的很准确。", "corrected_sentence": "他对市场的变化把握得很准确。", "error_description": "“把握”后的程度补语要用“得”，不能用“的”，应说“把握得很准确”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没把握住了文章的重点。", "corrected_sentence": "他没把握住文章的重点。", "error_description": "“没”表示否定时不能与“了”同用，应说“没把握住”，不能说“没把握住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提交是把东西交给别人去看或去处理。", "primary_collocate": null, "pronunciation": "tí jiāo", "ipa": "tʰi³⁵ tɕjɑʊ⁵⁵", "syllable_count": 2, "sentences": [{"text": "我把照片提交给老师了。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请明天把表格提交给我。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一份很好的报告提交给了领导。", "target_word": "提交", "complexity_tier": "T3", "furigana": "tā bǎ yí fèn hěn hǎo de bào gào tí jiāo gěi le lǐng dǎo.", "sentence_source": "generated"}, {"text": "他们把意见提交给经理。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把你的想法写下来提交给我。", "target_word": "提交", "complexity_tier": "T3", "furigana": "nǐ kě yǐ bǎ nǐ de xiǎng fǎ xiě xià lái tí jiāo gěi wǒ.", "sentence_source": "generated"}, {"text": "我想提交一个新的计划。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把自己的看法提交给了小组。", "target_word": "提交", "complexity_tier": "T3", "furigana": "xiǎo wáng bǎ zì jǐ de kàn fǎ tí jiāo gěi le xiǎo zǔ.", "sentence_source": "generated"}, {"text": "大家把方案提交给公司，等着回复。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提交过很多次意见。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我会提交给大家讨论。", "target_word": "提交", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提交了", "label": "体标"}, {"form": "提交过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，把意见、想法、方案等交给别人看或处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '829b3cd6-c5a4-42fd-b8c9-9e04b05f9127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提交", "is_correct": true, "explanation": "“提交”指把照片交给老师，与“把……给老师”的交付结构相符。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉照片，不能交给老师，与句意不合。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”是毁掉照片，与“给老师”的交付意思相反。"}, {"text": "撤回", "is_correct": false, "explanation": "搭配：“撤回”是收回已交出的东西，与“给老师”的交付方向相反，不能这样搭配。"}], "explanations": {"提交": "“提交”指把照片交给老师，与“把……给老师”的交付结构相符。", "删除": "语义：“删除”是去掉照片，不能交给老师，与句意不合。", "撕碎": "语义：“撕碎”是毁掉照片，与“给老师”的交付意思相反。", "撤回": "搭配：“撤回”是收回已交出的东西，与“给老师”的交付方向相反，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "提交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们提交了礼物。", "explanation": "这里应该用〈交换〉。“提交”指把文件、意见交给有关方面处理，不能用于互相交换礼物。"}, {"text": "公司提交了免费午餐。", "explanation": "这里应该用〈提供〉。“提交”指交给有关方面处理，给员工的免费午餐应该用“提供”。"}, {"text": "我把朋友提交给了老师。", "explanation": "这里应该用〈推荐〉。“提交”的对象是文件、意见等东西，不能是人，推荐人要用“推荐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提交", "is_correct": true, "explanation": "“提交”指把看法交给小组，与“把……给了小组”的结构相符。"}, {"text": "保密", "is_correct": false, "explanation": "搭配：“保密”不能带“把……给了小组”的交付结构，句子不通。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”是藏起来，与把看法交给小组的意思相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽别人，与把看法交给小组的意思完全不符。"}], "explanations": {"提交": "“提交”指把看法交给小组，与“把……给了小组”的结构相符。", "保密": "搭配：“保密”不能带“把……给了小组”的交付结构，句子不通。", "隐藏": "语义：“隐藏”是藏起来，与把看法交给小组的意思相反。", "嘲笑": "语义：“嘲笑”是讥讽别人，与把看法交给小组的意思完全不符。"}, "sentence_index": 6, "correct_answer": "提交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校提交了这位老师。", "explanation": "这里应该用〈提拔〉。“提拔”指把人调到更高职位，“提交”只能用于文件、意见等。"}, {"text": "他在会上提交了专家。", "explanation": "这里应该用〈提问〉。“提问”是向人发问，“提交”指把东西交给有关方面，不能用来指向人。"}, {"text": "这次培训提交了我们的效率。", "explanation": "这里应该用〈提高〉。效率是可以提高的水平，不能说提交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把论文提交了教授。", "corrected_sentence": "他把论文提交给了教授。", "error_description": "错误形式：“他把论文提交了教授”，漏掉了引出接收者的“给”。正确形式：“他把论文提交给了教授”，“提交”后要用“给”引出接收的人，句子才通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她明天会提交过报告。", "corrected_sentence": "她明天会提交报告。", "error_description": "错误形式：“她明天会提交过报告”，“过”表示已经发生的经历，不能与“明天”这种将来的时间搭配。正确形式：“她明天会提交报告”，去掉“过”，将来的动作只用“会”表示。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
