INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94165, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "有些人是说一群人里的一部分人，不是全部。", "primary_collocate": null, "pronunciation": "yǒu xiē rén", "ipa": "joʊ̯˨˩˦ ɕjɛ˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "来参加会议的人里，有些人是老师。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友里有些人住在北京。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里有些人在看书，别的人在聊天。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人已经吃完饭了，我们再等一下。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些学生中，有些人学了三年汉语。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有些人在跳舞，很热闹。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人说今天会下雨，我不太相信。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家有些人喜欢喝茶。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人把手机放在桌子上。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有些人是从外国来的。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指一群人里的一部分，不是全部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5b7ecc2-1826-4293-b41b-b692521b4ccb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94165, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有些人", "is_correct": true, "explanation": "正确：“有些人”指参会者中的一部分，与“人里”的部分范围相符，符合语境。"}, {"text": "各位", "is_correct": false, "explanation": "语域：“各位”是对听众的称呼，不用来指会议中的第三方。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，不能用于陈述句表示一部分人。"}, {"text": "众人", "is_correct": false, "explanation": "语义：“众人”指全体群众，与“人里”所限定的一部分范围相矛盾。"}], "explanations": {"有些人": "正确：“有些人”指参会者中的一部分，与“人里”的部分范围相符，符合语境。", "各位": "语域：“各位”是对听众的称呼，不用来指会议中的第三方。", "谁": "语义：“谁”是疑问代词，不能用于陈述句表示一部分人。", "众人": "语义：“众人”指全体群众，与“人里”所限定的一部分范围相矛盾。"}, "sentence_index": 0, "correct_answer": "有些人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有些人全部吃完饭了，我们再等一下。", "explanation": "搭配：“有些人”表示一部分，与“全部”矛盾；说全体要用“所有人”。"}, {"text": "这些杯子里有些人是空的。", "explanation": "对象：“有些人”只指人；杯子是物，说其中一部分要用“有的”。"}, {"text": "有些人每个人都吃完饭了，我们再等一下。", "explanation": "搭配：“每个人”指全体，与“有些人”表示的一部分矛盾；说全体要用“所有人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94165, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有些人", "is_correct": true, "explanation": "正确：“有些人”表示一部分人，与后句“我不太相信”相符，符合语境。"}, {"text": "哪些人", "is_correct": false, "explanation": "语义：“哪些人”是疑问代词，这里是陈述句，不能用来表示一部分人。"}, {"text": "哪位", "is_correct": false, "explanation": "语域：“哪位”是礼貌的疑问称呼，不能用于陈述句。"}, {"text": "什么人", "is_correct": false, "explanation": "语义：“什么人”是疑问代词，不能用来表示“一部分人”。"}], "explanations": {"有些人": "正确：“有些人”表示一部分人，与后句“我不太相信”相符，符合语境。", "哪些人": "语义：“哪些人”是疑问代词，这里是陈述句，不能用来表示一部分人。", "哪位": "语域：“哪位”是礼貌的疑问称呼，不能用于陈述句。", "什么人": "语义：“什么人”是疑问代词，不能用来表示“一部分人”。"}, "sentence_index": 6, "correct_answer": "有些人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班有些人都会说汉语。", "explanation": "搭配：“都”表示全部，与“有些人”表示一部分矛盾；说全体要用“大家”。"}, {"text": "我们班有些人是班上的全部学生。", "explanation": "搭配：“全部学生”指全体，与“有些人”表示的一部分矛盾；说全体要用“全体”。"}, {"text": "我们班有些人一个也没有来。", "explanation": "搭配：“一个也没有”表示全无，与“有些人”的部分意思矛盾；说没有人来要用“没有人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94165, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有些的人在家看书，有些人在外面玩。", "corrected_sentence": "有些人在家看书，有些人在外面玩。", "error_description": "多了“的”：“有些人”是一个整体，“有些”后面不能直接加“的”，应为“有些人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
