INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94166, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指人群中的一部分人，不是全体。", "primary_collocate": null, "pronunciation": "yǒu xiē rén", "ipa": "joʊ̯˨˩˦ ɕjɛ˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "有些人喜欢早上跑步，有些人喜欢晚上跑步。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里有些人今天没有来上课。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人觉得这家店的饭很好吃。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有些人会说日语。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人不喜欢吃辣的东西。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐的时候，有些人喜欢安静。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人坐地铁上班，有些人开车上班。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有些人在等公共汽车。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人每天都要喝一杯咖啡。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的会，有些人没有参加。", "target_word": "有些人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指人群中的一部分人而非全体，常用于对比说明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5b7ecc2-1826-4293-b41b-b692521b4ccb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有些人", "is_correct": true, "explanation": "正确：前一分句的“有些人”指一部分人，与后句的“有些人”相对，符合语境。"}, {"text": "所有人", "is_correct": false, "explanation": "语义：“所有人”指全体，与后句“有些人”指一部分的说法相矛盾。"}, {"text": "每个人", "is_correct": false, "explanation": "语义：“每个人”指全体成员，与后句“有些人”指一部分的对比相矛盾。"}, {"text": "各位", "is_correct": false, "explanation": "语域：“各位”是对听众的称呼，不用来叙述第三方的做法。"}], "explanations": {"有些人": "正确：前一分句的“有些人”指一部分人，与后句的“有些人”相对，符合语境。", "所有人": "语义：“所有人”指全体，与后句“有些人”指一部分的说法相矛盾。", "每个人": "语义：“每个人”指全体成员，与后句“有些人”指一部分的对比相矛盾。", "各位": "语域：“各位”是对听众的称呼，不用来叙述第三方的做法。"}, "sentence_index": 0, "correct_answer": "有些人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有些人都会说汉语。", "explanation": "搭配：“都”表示全部，与“有些人”表示的一部分矛盾；说全体要用“大家”。"}, {"text": "这些书里，有些人是红色的。", "explanation": "对象：“有些人”只指人，“书”是事物，指事物的一部分应用“有些”。"}, {"text": "我们班有些人全都是从外国来的。", "explanation": "搭配：“有些人”表示一部分，与“全都”矛盾；说全体要用“大家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有些人", "is_correct": true, "explanation": "正确：“有些人”指一部分人，与后句“有些人开车上班”形成对比，符合语境。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指全体，与后句“有些人开车上班”的部分对比相矛盾。"}, {"text": "人人", "is_correct": false, "explanation": "语义：“人人”指每一个人，与后句“有些人”的部分意义相矛盾。"}, {"text": "诸位", "is_correct": false, "explanation": "语域：“诸位”是对听众的称呼，不用来叙述第三方的上班方式。"}], "explanations": {"有些人": "正确：“有些人”指一部分人，与后句“有些人开车上班”形成对比，符合语境。", "大家": "语义：“大家”指全体，与后句“有些人开车上班”的部分对比相矛盾。", "人人": "语义：“人人”指每一个人，与后句“有些人”的部分意义相矛盾。", "诸位": "语域：“诸位”是对听众的称呼，不用来叙述第三方的上班方式。"}, "sentence_index": 6, "correct_answer": "有些人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "有些人全是我们班的同学。", "explanation": "搭配：“全是”指全部，与“有些人”表示的一部分矛盾；说全体要用“所有人”。"}, {"text": "班里有些人就是全班的成员。", "explanation": "搭配：“全班的成员”指全体，与“有些人”的部分意思矛盾；说全体要用“全体成员”。"}, {"text": "我们班有些人一个也没有来。", "explanation": "搭配：“一个也没有”表示全无，与“有些人”的部分意思矛盾；说没有人来要用“没有人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有些人的觉得冷，有些人觉得热。", "corrected_sentence": "有些人觉得冷，有些人觉得热。", "error_description": "多了“的”：“有些人”作主语时，后面直接接动词“觉得”，不能加“的”，应为“有些人觉得冷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有些人们在家工作，有些人在公司工作。", "corrected_sentence": "有些人在家工作，有些人在公司工作。", "error_description": "多了“们”：“有些人”已经表示复数，不能再加“们”，应为“有些人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
