INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94169, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "毁灭是把东西全部弄坏，什么也不剩。", "primary_collocate": null, "pronunciation": "huǐ miè", "ipa": "xuei˨˩ mie˥˩", "syllable_count": 2, "sentences": [{"text": "一场大火毁灭了整片森林。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震毁灭了这个小村子，什么也没留下。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争毁灭了很多城市和家园。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想毁灭所有的证据，不让警察发现。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大水毁灭了农民一年的粮食。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风毁灭了海边所有的房子，只剩下几棵树。", "target_word": "毁灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧信都烧了，想毁灭所有的记录。", "target_word": "毁灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雪崩毁灭了山下的几个小房子。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山曾经毁灭过一座古老的城市。", "target_word": "毁灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水毁灭了他们的家，他们只好搬走。", "target_word": "毁灭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "毁灭了", "label": "体标（了）"}, {"form": "毁灭过", "label": "体标（过）"}, {"form": "毁灭性", "label": "复合"}], "register": "书面语", "sense_fingerprint": "毁灭实物：把房屋、森林、证据等全部弄坏，什么也不剩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed0c4cfe-367f-4222-8eac-27cac2d37f6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94169, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毁灭", "is_correct": true, "explanation": "毁灭指把东西全部弄坏、什么也不剩，这里说大火把整片森林烧光。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”的对象应是问题或话题，不能是“森林”这样的具体事物。"}, {"text": "保护", "is_correct": false, "explanation": "语义：大火会烧毁森林，不能说它“保护”了森林。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植的主体应是人，大火不会种植森林。"}], "explanations": {"毁灭": "毁灭指把东西全部弄坏、什么也不剩，这里说大火把整片森林烧光。", "讨论": "配价：“讨论”的对象应是问题或话题，不能是“森林”这样的具体事物。", "保护": "语义：大火会烧毁森林，不能说它“保护”了森林。", "种植": "语义：种植的主体应是人，大火不会种植森林。"}, "sentence_index": 0, "correct_answer": "毁灭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心毁灭了杯子的一个把手。", "explanation": "这里应该用〈损坏〉。毁灭指全部弄坏、什么也不剩，只坏了一个把手应说“损坏”。"}, {"text": "这次小误会暂时毁灭了我们的友谊，后来我们又和好了。", "explanation": "这里应该用〈伤害〉。此义的“毁灭”指把具体东西彻底弄坏、什么也不剩，不能用于暂时的、事后能和好的伤害。"}, {"text": "他不小心把作业本毁灭了几页，还能继续用。", "explanation": "这里应该用〈弄坏〉。毁灭指全部弄坏、什么也不剩，只坏了几页、本子还能用，应说“弄坏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毁灭", "is_correct": true, "explanation": "毁灭指彻底消灭，这里说他想把所有的记录全部弄没，与“烧了旧信”的做法一致。"}, {"text": "保存", "is_correct": false, "explanation": "语义：“保存”是留下、不丢失，与“烧了旧信”及想毁掉记录的意图相反。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”用于课文、诗词等内容，不说“背诵记录”。"}, {"text": "惩罚", "is_correct": false, "explanation": "配价：“惩罚”的对象是人或错误行为，不能以“记录”为宾语。"}], "explanations": {"毁灭": "毁灭指彻底消灭，这里说他想把所有的记录全部弄没，与“烧了旧信”的做法一致。", "保存": "语义：“保存”是留下、不丢失，与“烧了旧信”及想毁掉记录的意图相反。", "背诵": "搭配：“背诵”用于课文、诗词等内容，不说“背诵记录”。", "惩罚": "配价：“惩罚”的对象是人或错误行为，不能以“记录”为宾语。"}, "sentence_index": 6, "correct_answer": "毁灭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大火毁灭了整个仓库，仓库里的一箱书却完好无损。", "explanation": "这里应该用〈烧坏〉。毁灭指全部弄坏、什么也不剩，后文说一箱书完好无损，前后矛盾，实际只是部分烧坏。"}, {"text": "他把旧玩具毁灭了，又送给了弟弟。", "explanation": "这里应该用〈扔掉〉。毁灭指彻底弄坏、什么也不剩，后文又送给弟弟，说明东西还在，不能用“毁灭”。"}, {"text": "这个小玩笑毁灭了大家的好心情。", "explanation": "这里应该用〈影响〉。毁灭指彻底弄坏，多用于具体事物，不能用来形容一个小玩笑让心情变差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暴雨把村里的庄稼毁灭。", "corrected_sentence": "暴雨把村里的庄稼毁灭了。", "error_description": "“把”字句中动词后要带“了”或其他补语，只说“毁灭”不完整，应改为“暴雨把村里的庄稼毁灭了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场火灾毁灭很彻底，仓库什么也没剩下。", "corrected_sentence": "这场火灾毁灭得很彻底，仓库什么也没剩下。", "error_description": "程度补语要用“得”连接，“毁灭”后应说“毁灭得很彻底”，不能省略“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94170, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "创造", "is_correct": true, "explanation": "创造指无中生有地造出新事物，与“毁灭”彻底消灭相对。"}, {"text": "散步", "is_correct": false, "explanation": "散步是慢慢走路，与毁灭没有相对关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看指用眼睛看，与毁灭没有相对关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭指进食，与毁灭没有相对关系。"}], "correct_answer": "创造", "explanations": {"创造": "创造指无中生有地造出新事物，与“毁灭”彻底消灭相对。", "散步": "散步是慢慢走路，与毁灭没有相对关系。", "观看": "观看指用眼睛看，与毁灭没有相对关系。", "吃饭": "吃饭指进食，与毁灭没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
