INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94181, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "烂是东西坏了，软软的，不能吃或不能用了。", "primary_collocate": null, "pronunciation": "làn", "ipa": "lan˥˩", "syllable_count": 1, "sentences": [{"text": "这根香蕉已经烂了，扔掉吧。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个梨已经烂了，别吃了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天水果不放冰箱，很快就烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买的橘子，有两个是烂的。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一个烂苹果。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜放了一个星期，全烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板烂了，不能再用了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把烂掉的西瓜倒进了垃圾桶。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些草莓都烂了，真可惜。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆烂了，味道很难闻。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烂了", "label": "体标"}, {"form": "烂掉", "label": "复合"}, {"form": "腐烂", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西变坏变软，不能吃不能用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94181, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烂", "is_correct": true, "explanation": "烂（làn，第四声）：东西坏了变软，即本词的词义。"}, {"text": "蓝", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是蓝色。"}, {"text": "懒", "is_correct": false, "explanation": "lǎn（第三声）与 làn（第四声）声调不同，意思是懒惰。"}, {"text": "浪", "is_correct": false, "explanation": "làng 与 làn 韵母不同（ang／an），意思是波浪。"}, {"text": "拦", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是阻拦。"}], "explanations": {"烂": "烂（làn，第四声）：东西坏了变软，即本词的词义。", "蓝": "lán（第二声）与 làn（第四声）声调不同，意思是蓝色。", "懒": "lǎn（第三声）与 làn（第四声）声调不同，意思是懒惰。", "浪": "làng 与 làn 韵母不同（ang／an），意思是波浪。", "拦": "lán（第二声）与 làn（第四声）声调不同，意思是阻拦。"}, "sentence_index": null, "correct_answer": "烂"}, "level_3": {"options": [{"text": "烂", "is_correct": true, "explanation": "正确：香蕉坏了变软，不能吃，所以扔掉。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：香蕉新鲜就不会被扔掉，与“扔掉吧”矛盾。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：好吃的香蕉不会被扔掉，与“扔掉吧”矛盾。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”说洁净，不能用来说香蕉的状态变化。"}], "explanations": {"烂": "正确：香蕉坏了变软，不能吃，所以扔掉。", "新鲜": "语义：香蕉新鲜就不会被扔掉，与“扔掉吧”矛盾。", "好吃": "语义：好吃的香蕉不会被扔掉，与“扔掉吧”矛盾。", "干净": "搭配：“干净”说洁净，不能用来说香蕉的状态变化。"}, "sentence_index": 0, "correct_answer": "烂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天太热，冰棍很快就烂了。", "explanation": "这里应该用〈融化〉。烂指东西腐败变软，冰棍受热变成水要用融化。"}, {"text": "那件红衣服洗了几次，颜色就烂了。", "explanation": "这里应该用〈褪〉。烂指东西腐败变软，颜色逐渐变淡要用褪。"}, {"text": "那勺糖放进水里，很快就烂光了。", "explanation": "这里应该用〈溶解〉。烂指腐败变软，糖在水中化开要用溶解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94181, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "烂", "is_correct": true, "explanation": "烂（làn，第四声）：东西坏了变软，即本词的词义。"}, {"text": "难", "is_correct": false, "explanation": "nàn（第四声）与 làn 声母不同（n／l），意思是灾难。"}, {"text": "缆", "is_correct": false, "explanation": "lǎn（第三声）与 làn（第四声）声调不同，意思是缆绳。"}, {"text": "栏", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是栏杆。"}, {"text": "兰", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是兰花。"}], "explanations": {"烂": "烂（làn，第四声）：东西坏了变软，即本词的词义。", "难": "nàn（第四声）与 làn 声母不同（n／l），意思是灾难。", "缆": "lǎn（第三声）与 làn（第四声）声调不同，意思是缆绳。", "栏": "lán（第二声）与 làn（第四声）声调不同，意思是栏杆。", "兰": "lán（第二声）与 làn（第四声）声调不同，意思是兰花。"}, "sentence_index": null, "correct_answer": "烂"}, "level_3": {"options": [{"text": "烂", "is_correct": true, "explanation": "正确：木板坏了变软，所以不能再用。"}, {"text": "完整", "is_correct": false, "explanation": "语义：木板完整就能用，与“不能再用了”矛盾。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”的木板不会说不能再用，与后半句矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”说光线或颜色，不能用来形容木板的状态。"}], "explanations": {"烂": "正确：木板坏了变软，所以不能再用。", "完整": "语义：木板完整就能用，与“不能再用了”矛盾。", "新": "语义：“新”的木板不会说不能再用，与后半句矛盾。", "亮": "搭配：“亮”说光线或颜色，不能用来形容木板的状态。"}, "sentence_index": 6, "correct_answer": "烂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "香水瓶没盖好，香水很快就烂光了。", "explanation": "这里应该用〈挥发〉。烂指东西腐败变软，香水的液体成分飘散要用挥发。"}, {"text": "天气太冷，水很快就烂成了冰。", "explanation": "这里应该用〈凝固〉。烂指东西腐败，水遇冷变成固体要用凝固。"}, {"text": "湖水被太阳晒了一天，慢慢烂掉了。", "explanation": "这里应该用〈蒸发〉。烂指东西腐败，湖水受热变成水汽要用蒸发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v