INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94182, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "因腐败或煮炖而变得松软；破碎，不整齐。", "primary_collocate": null, "pronunciation": "làn", "ipa": "lan˥˩", "syllable_count": 1, "sentences": [{"text": "西红柿放太久，都烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鞋很烂，鞋底都破了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书太旧，纸都烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉炖得很烂，老人也能吃。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了一夜，路上的叶子都烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件衣服又脏又烂，别穿了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的木头都烂了，不能用了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把烂菜叶扔进了垃圾桶。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板泡在水里，已经烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面条煮得太烂，我不想吃。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烂了", "label": "体标"}, {"form": "腐烂", "label": "复合"}, {"form": "破烂", "label": "复合"}], "register": "中性", "sense_fingerprint": "腐败或煮炖松软；破碎不整齐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94182, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烂", "is_correct": true, "explanation": "烂（làn，第四声）：因腐败而变软，即本词的词义。"}, {"text": "蓝", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是蓝色。"}, {"text": "懒", "is_correct": false, "explanation": "lǎn（第三声）与 làn（第四声）声调不同，意思是懒惰。"}, {"text": "浪", "is_correct": false, "explanation": "làng 与 làn 韵母不同（ang／an），意思是波浪。"}, {"text": "拦", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是阻拦。"}], "explanations": {"烂": "烂（làn，第四声）：因腐败而变软，即本词的词义。", "蓝": "lán（第二声）与 làn（第四声）声调不同，意思是蓝色。", "懒": "lǎn（第三声）与 làn（第四声）声调不同，意思是懒惰。", "浪": "làng 与 làn 韵母不同（ang／an），意思是波浪。", "拦": "lán（第二声）与 làn（第四声）声调不同，意思是阻拦。"}, "sentence_index": null, "correct_answer": "烂"}, "level_3": {"options": [{"text": "烂", "is_correct": true, "explanation": "正确：西红柿放久后腐败变软，符合语境。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：放太久与“新鲜”矛盾，西红柿不会因放久而变新鲜。"}, {"text": "干净", "is_correct": false, "explanation": "语义：西红柿放久不会变得“干净”，与语境不符。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”说光线或颜色，不能用来形容西红柿的状态。"}], "explanations": {"烂": "正确：西红柿放久后腐败变软，符合语境。", "新鲜": "语义：放太久与“新鲜”矛盾，西红柿不会因放久而变新鲜。", "干净": "语义：西红柿放久不会变得“干净”，与语境不符。", "亮": "搭配：“亮”说光线或颜色，不能用来形容西红柿的状态。"}, "sentence_index": 0, "correct_answer": "烂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天太热，冰箱里的冰都烂了。", "explanation": "这里应该用〈融化〉。烂指东西因腐败而变软，冰受热变成水要用融化。"}, {"text": "这瓶白酒没盖紧，一夜之间就烂光了。", "explanation": "这里应该用〈挥发〉。烂指东西腐败变软，酒精从液体飘散到空气中要用挥发。"}, {"text": "这块蛋糕很烂，口感又松又软。", "explanation": "这里应该用〈松软〉。烂多指东西腐败变软，或食物煮炖到很软；形容口感松软的蛋糕要用松软，不用烂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
