INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94185, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "当成是把一个东西当作另一个东西来用或来看。", "primary_collocate": null, "pronunciation": "dāng chéng", "ipa": "taŋ˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他把旧箱子当成桌子用。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常把这个杯子当成笔筒。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把沙发当成了小床。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把手机当成闹钟，每天早上用它叫醒自己。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把客厅当成教室，在家上网课。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把雨伞当成剑，在院子里玩。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书当成枕头，在草地上睡着了。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这张旧报纸当成画纸给孩子们用。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把车库当成了工作室。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太冷，我把大衣当成毯子盖着。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当成了", "label": "体标"}, {"form": "當成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把某物当作另一种东西来使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5b7ecc2-1826-4293-b41b-b692521b4ccb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94185, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当成", "is_correct": true, "explanation": "正确：“当成”表示把旧箱子当作桌子来用，与后面的“用”相呼应。"}, {"text": "堆成", "is_correct": false, "explanation": "搭配：“堆成”指堆积成某种形状，不能说把箱子堆成桌子来用。"}, {"text": "拍成", "is_correct": false, "explanation": "搭配：“拍成”指拍摄或制作成影视作品，不能说把箱子拍成桌子来用。"}, {"text": "写成", "is_correct": false, "explanation": "搭配：“写成”指写作成文字或作品，不能说把箱子写成桌子来用。"}], "explanations": {"当成": "正确：“当成”表示把旧箱子当作桌子来用，与后面的“用”相呼应。", "堆成": "搭配：“堆成”指堆积成某种形状，不能说把箱子堆成桌子来用。", "拍成": "搭配：“拍成”指拍摄或制作成影视作品，不能说把箱子拍成桌子来用。", "写成": "搭配：“写成”指写作成文字或作品，不能说把箱子写成桌子来用。"}, "sentence_index": 0, "correct_answer": "当成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆水放进冰箱，很快就当成了冰。", "explanation": "这里应该用〈变成〉。“当成”表示把甲当作乙来用或看待，不能说事物本身变成另一种东西；水结成冰要用〈变成〉。"}, {"text": "妈妈把面粉当成了煮熟。", "explanation": "这里应该用〈做成〉。“当成”后要接名词，不能接动作结果“煮熟”；把面粉做成面条要用〈做成〉。"}, {"text": "妈妈把蛋糕当成了切开。", "explanation": "这里应该用〈切成〉。“当成”后要接名词，不能接动作结果“切开”；把蛋糕切成小块要用〈切成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94185, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当成", "is_correct": true, "explanation": "正确：“当成”表示把书当作枕头来用，与“枕头”相呼应。"}, {"text": "写成", "is_correct": false, "explanation": "搭配：“写成”指写作成文字或作品，不能说把书写成枕头来用。"}, {"text": "抄成", "is_correct": false, "explanation": "语义：“抄成”指誊抄成某种文字，不能说把书抄成枕头来用。"}, {"text": "裁成", "is_correct": false, "explanation": "搭配：“裁”多用于布料、纸张，书一般不被裁来做枕头。"}], "explanations": {"当成": "正确：“当成”表示把书当作枕头来用，与“枕头”相呼应。", "写成": "搭配：“写成”指写作成文字或作品，不能说把书写成枕头来用。", "抄成": "语义：“抄成”指誊抄成某种文字，不能说把书抄成枕头来用。", "裁成": "搭配：“裁”多用于布料、纸张，书一般不被裁来做枕头。"}, "sentence_index": 6, "correct_answer": "当成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把面包当成了磨碎。", "explanation": "这里应该用〈磨成〉。“当成”后要接名词，不能接动作结果“磨碎”；把面包磨成面粉要用〈磨成〉。"}, {"text": "工人把钢铁当成了建好。", "explanation": "这里应该用〈建成〉。“当成”后要接名词，不能接动作结果“建好”；用钢铁建成桥要用〈建成〉。"}, {"text": "他把头发当成了染好。", "explanation": "这里应该用〈染成〉。“当成”后要接名词，不能接动作结果“染好”；把头发染成黄色要用〈染成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94185, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把把旧轮胎当成花盆，种了几棵花。", "corrected_sentence": "他把旧轮胎当成花盆，种了几棵花。", "error_description": "多余成分：“把”只用一次，“他把把旧轮胎”重复了介词“把”，应为“他把旧轮胎当成花盆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94185, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他旧书当成柴火烧掉了。", "corrected_sentence": "他把旧书当成柴火烧掉了。", "error_description": "错误：缺少“把”，“旧书”不能直接放在“当成”前作宾语。应为“把旧书当成柴火”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
