INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文章作者的自称。", "primary_collocate": null, "pronunciation": "bǐ zhě", "ipa": "pi˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "笔者认为这个办法很好。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者在北京住了五年。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者去年访问过这个村子。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者想借这篇文章谈谈看法。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据笔者了解，这家店很有名。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者的朋友是一位医生。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者已经把结果写在下面了。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本文中，笔者介绍三种方法。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者小时候常去那条河边。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者希望读者喜欢这篇文章。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "作者称呼自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笔者", "is_correct": true, "explanation": "正确。笔者是文章作者的自称，这里表示作者自己的看法。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有思考能力，不能对「这个办法好不好」作出判断。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会有看法，不能作「认为」的主语。"}, {"text": "猫", "is_correct": false, "explanation": "配价：「认为」要求能做判断的人作主语，猫不能对办法表达看法。"}], "explanations": {"笔者": "正确。笔者是文章作者的自称，这里表示作者自己的看法。", "石头": "语义：石头没有思考能力，不能对「这个办法好不好」作出判断。", "窗户": "语义：窗户不会有看法，不能作「认为」的主语。", "猫": "配价：「认为」要求能做判断的人作主语，猫不能对办法表达看法。"}, "sentence_index": 0, "correct_answer": "笔者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的笔者是鲁迅。", "explanation": "这里应该用〈作者〉。笔者只用于作者称呼自己，不能指别人写的文章的作者。"}, {"text": "我是一只笔者。", "explanation": "量词用错：笔者指写文章的人，是人，应该用「位」，不能用「只」。"}, {"text": "你是笔者吗？", "explanation": "这里应该用〈读者〉。笔者只用于作者自称，不能拿来称呼对方；称呼读文章的人要用「读者」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笔者", "is_correct": true, "explanation": "正确。笔者指写文章的人，这里是作者说明自己已把结果写在下面。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能书写，也不能把结果写在下面。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水不会书写，不能作「写」的施事。"}, {"text": "老虎", "is_correct": false, "explanation": "配价：「写」需要能用笔书写的施事，老虎不能完成这个动作。"}], "explanations": {"笔者": "正确。笔者指写文章的人，这里是作者说明自己已把结果写在下面。", "桌子": "语义：桌子不能书写，也不能把结果写在下面。", "河水": "语义：河水不会书写，不能作「写」的施事。", "老虎": "配价：「写」需要能用笔书写的施事，老虎不能完成这个动作。"}, "sentence_index": 6, "correct_answer": "笔者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真记了很多笔者。", "explanation": "这里应该用〈笔记〉。笔者指写文章的人，不能指记下的内容；记下的文字要说「笔记」。"}, {"text": "他用这支笔者写完了作业。", "explanation": "这里应该用〈钢笔〉。笔者指写文章的人，不能指书写工具；书写工具要说「钢笔」。"}, {"text": "我们班来了一本笔者。", "explanation": "量词用错：笔者指人，不能用「本」来数，应该用「位」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台笔者在报纸上发表了一篇文章。", "corrected_sentence": "这位笔者在报纸上发表了一篇文章。", "error_description": "量词错误：笔者指人，不能用「台」（「台」多用于机器、设备）。应改用「位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是很笔者的新书。", "corrected_sentence": "这是笔者的新书。", "error_description": "副词错误：「很」不能修饰名词「笔者」，应去掉「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
