INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "犯了罪的人，特别是被依法判刑的人。", "primary_collocate": null, "pronunciation": "zuì fàn", "ipa": "tsuei˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "法院判了这名罪犯十年。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罪犯要在监狱里关十年。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判罪犯三年，他在监狱里很后悔。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这名罪犯已经受到了法律的处罚。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罪犯出狱后，找到了一份工作。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监狱里的罪犯每天都要工作。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官问罪犯：“你知道自己错了吗？”", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写着，这个罪犯今天上法庭。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罪犯的家人来监狱看他。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前是罪犯，现在重新开始生活了。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "依法判刑的犯罪者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee3e7df-b1b0-4578-906e-2115242cea45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罪犯", "is_correct": true, "explanation": "法院判刑十年的对象是犯罪并被定罪的人，“罪犯”符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“名”只用于人，房子应用“座”或“栋”，而且房子不能被判刑。"}, {"text": "水", "is_correct": false, "explanation": "语义：“判十年”的对象必须是人，水不能被法院判刑。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“判”的受事只能是人，“窗户”不能作为判刑的对象。"}], "explanations": {"罪犯": "法院判刑十年的对象是犯罪并被定罪的人，“罪犯”符合句意。", "房子": "搭配：量词“名”只用于人，房子应用“座”或“栋”，而且房子不能被判刑。", "水": "语义：“判十年”的对象必须是人，水不能被法院判刑。", "窗户": "配价：“判”的受事只能是人，“窗户”不能作为判刑的对象。"}, "sentence_index": 0, "correct_answer": "罪犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我班上的罪犯，成绩很好。", "explanation": "这里应该用〈学生〉。罪犯指犯了罪的人，不能用来指在班里学习的人。"}, {"text": "这次的罪犯很严重，法院判了他十年。", "explanation": "这里应该用〈罪行〉。罪犯指人，不能用来说犯罪行为有多严重。"}, {"text": "这位罪犯每天在法庭上判案，大家都很信任他。", "explanation": "这里应该用〈法官〉。罪犯是犯了罪的人，不能担任在法庭上判案的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罪犯", "is_correct": true, "explanation": "问话的对象是能听懂问题、能回答的人，“罪犯”符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“问”的对象要能回答问题，椅子不能作受问者。"}, {"text": "树", "is_correct": false, "explanation": "语义：树听不懂问题，也不会回答“你知道自己错了吗”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能作受问者，法官的问话只能对人说。"}], "explanations": {"罪犯": "问话的对象是能听懂问题、能回答的人，“罪犯”符合句意。", "椅子": "配价：“问”的对象要能回答问题，椅子不能作受问者。", "树": "语义：树听不懂问题，也不会回答“你知道自己错了吗”。", "桌子": "语义：桌子不能作受问者，法官的问话只能对人说。"}, "sentence_index": 6, "correct_answer": "罪犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的职业是罪犯。", "explanation": "这里应该用〈工作〉。罪犯指犯了罪的人，是身份而不是一种工作，不能用来说职业。"}, {"text": "我家的罪犯很热心，经常帮我。", "explanation": "这里应该用〈邻居〉。罪犯指犯了罪的人，不能用来称呼住在隔壁、经常帮助我的人。"}, {"text": "他被小偷打伤了，他是这件事的罪犯。", "explanation": "这里应该用〈受害者〉。罪犯指作案的人，被小偷打伤的人应称为〈受害者〉，不是罪犯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个罪犯把法院判了十年。", "corrected_sentence": "那个罪犯被法院判了十年。", "error_description": "被字句错误：错误形式是“把法院判了十年”，正确形式是“被法院判了十年”。“罪犯”是被判的人，应作主语；“法院”是施事，要用“被”引出，“把”不能引出施事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法官那个罪犯判了十年。", "corrected_sentence": "法官把那个罪犯判了十年。", "error_description": "漏掉“把”：错误形式是“法官那个罪犯判了十年”，正确形式是“法官把那个罪犯判了十年”。把字句中受事要由“把”引出并放在动词前；漏掉“把”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
