INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由机关或团体发给的证明资格、成绩或身份的文件。", "primary_collocate": null, "pronunciation": "zhèng shū", "ipa": "tʂəŋ˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "这张证书是学校发给我的。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考试通过了，拿到了证书。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带好你的证书来办公室。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把证书交给了他。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本证书上有校长的名字。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把证书放在书包里。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一张英语考试的证书。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证书丢了，你要去办公室重新办。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，大家都拿到了证书。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司要看你的证书和成绩单。", "target_word": "证书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "本", "label": "量词"}, {"form": "證書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机关或团体发的证明资格成绩身份的文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1cc6afb-d9ef-4bf0-9c1b-33171e53fc3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证书", "is_correct": true, "explanation": "证书 zhèngshū：机关或团体发给的证明资格、成绩或身份的文件。"}, {"text": "整数", "is_correct": false, "explanation": "整数 zhěngshù：zhěng（第三声）与 zhèng（第四声）声调不同，shù（第四声）与 shū（第一声）声调也不同，意思是整数。"}, {"text": "正数", "is_correct": false, "explanation": "正数 zhèngshù：只有第二个音节 shù（第四声）与 shū（第一声）声调不同，意思是正数。"}, {"text": "证实", "is_correct": false, "explanation": "证实 zhèngshí：shí（第二声）与 shū（第一声）韵母和声调都不同，意思是证实。"}, {"text": "正式", "is_correct": false, "explanation": "正式 zhèngshì：shì（第四声）与 shū（第一声）韵母和声调都不同，意思是正式。"}], "explanations": {"证书": "证书 zhèngshū：机关或团体发给的证明资格、成绩或身份的文件。", "整数": "整数 zhěngshù：zhěng（第三声）与 zhèng（第四声）声调不同，shù（第四声）与 shū（第一声）声调也不同，意思是整数。", "正数": "正数 zhèngshù：只有第二个音节 shù（第四声）与 shū（第一声）声调不同，意思是正数。", "证实": "证实 zhèngshí：shí（第二声）与 shū（第一声）韵母和声调都不同，意思是证实。", "正式": "正式 zhèngshì：shì（第四声）与 shū（第一声）韵母和声调都不同，意思是正式。"}, "sentence_index": null, "correct_answer": "证书"}, "level_3": {"options": [{"text": "证书", "is_correct": true, "explanation": "正确。证书是机关或团体发给的证明文件，与「学校发给我的」相符。"}, {"text": "信用卡", "is_correct": false, "explanation": "搭配：「发给」的物品多是证件、成绩或奖品，信用卡由银行发放，学校不会发给学生。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票由邮政部门发行，与「学校发给我的」不符。"}, {"text": "名片", "is_correct": false, "explanation": "配价：「学校发给我」要求发放者是学校，名片由个人或公司印制，不能由学校发给。"}], "explanations": {"证书": "正确。证书是机关或团体发给的证明文件，与「学校发给我的」相符。", "信用卡": "搭配：「发给」的物品多是证件、成绩或奖品，信用卡由银行发放，学校不会发给学生。", "邮票": "语义：邮票由邮政部门发行，与「学校发给我的」不符。", "名片": "配价：「学校发给我」要求发放者是学校，名片由个人或公司印制，不能由学校发给。"}, "sentence_index": 0, "correct_answer": "证书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她去医院看病，忘了带证书。", "explanation": "这里应该用〈医保卡〉。看病要核验身份和医保信息，证书不能代替。"}, {"text": "这段录像是案件的重要证书。", "explanation": "这里应该用〈证据〉。证书是证明资格、成绩或身份的文件，不能用来证明事情的经过，证明事实要用证据。"}, {"text": "他需要一份收入证书。", "explanation": "这里应该用〈收入证明〉。证书用于资格或成绩，证明收入状况要用证明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94208, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "证书", "is_correct": true, "explanation": "证书 zhèngshū：机关或团体发给的证明资格、成绩或身份的文件。"}, {"text": "赠书", "is_correct": false, "explanation": "赠书 zèngshū：zèng（第四声）与 zhèng 只有声母不同（z 与 zh），意思是赠送书籍。"}, {"text": "圣书", "is_correct": false, "explanation": "圣书 shèngshū：shèng（第四声）与 zhèng 只有声母不同（sh 与 zh），意思是圣典，如《圣经》。"}, {"text": "正事", "is_correct": false, "explanation": "正事 zhèngshì：只有第二个音节 shì（第四声）与 shū（第一声）韵母和声调不同，意思是正经事。"}], "explanations": {"证书": "证书 zhèngshū：机关或团体发给的证明资格、成绩或身份的文件。", "赠书": "赠书 zèngshū：zèng（第四声）与 zhèng 只有声母不同（z 与 zh），意思是赠送书籍。", "圣书": "圣书 shèngshū：shèng（第四声）与 zhèng 只有声母不同（sh 与 zh），意思是圣典，如《圣经》。", "正事": "正事 zhèngshì：只有第二个音节 shì（第四声）与 shū（第一声）韵母和声调不同，意思是正经事。"}, "sentence_index": null, "correct_answer": "证书"}, "level_3": {"options": [{"text": "证书", "is_correct": true, "explanation": "正确。「英语考试的」修饰的是证书，「一张……证书」搭配自然，语境相符。"}, {"text": "电影票", "is_correct": false, "explanation": "语义：英语考试与电影票无关，「英语考试的电影票」说不通。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：「英语考试的」多修饰证书、成绩单、试卷等，地图不搭配。"}, {"text": "床单", "is_correct": false, "explanation": "语义：床单是卧具，与英语考试没有关系，句子不通。"}], "explanations": {"证书": "正确。「英语考试的」修饰的是证书，「一张……证书」搭配自然，语境相符。", "电影票": "语义：英语考试与电影票无关，「英语考试的电影票」说不通。", "地图": "搭配：「英语考试的」多修饰证书、成绩单、试卷等，地图不搭配。", "床单": "语义：床单是卧具，与英语考试没有关系，句子不通。"}, "sentence_index": 6, "correct_answer": "证书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想办一张银行卡，忘了带证书，只好改天再来。", "explanation": "这里应该用〈身份证〉。办银行卡要核验身份，证书不能代替身份证件。"}, {"text": "这家餐厅门口挂着证书，写着今天的营业时间。", "explanation": "这里应该用〈告示〉或〈招牌〉。证书是证明资格、成绩或身份的文件，不用来发布营业信息。"}, {"text": "这张发票是报销的证书。", "explanation": "这里应该用〈凭证〉或〈发票〉。证书证明资格、成绩或身份，报销的依据是发票这类凭证，不能用证书代替。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在比赛中拿到了一只英语证书。", "corrected_sentence": "他在比赛中拿到了一张英语证书。", "error_description": "量词错误：「只」用于动物或成对物品中的一个，证书是纸质文件，应把「只」改为「张」（或「本」），写作「一张英语证书」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年就拿到过这只证书。", "corrected_sentence": "他去年就拿到过这张证书。", "error_description": "量词错误：「只」用于动物或成对物品中的一个，证书是纸质文件，应把「只」改为「张」，写作「拿到过这张证书」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94209, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走进", "is_correct": true, "explanation": "反义：走进是从外面到里面，与「走出」的方向相反。"}, {"text": "停留", "is_correct": false, "explanation": "无关：停留是不动，与走出饭店没有反义关系。"}, {"text": "坐下", "is_correct": false, "explanation": "无关：坐下是姿势的改变，与走出饭店的方向无关。"}, {"text": "躺下", "is_correct": false, "explanation": "无关：躺下是姿势，与离开饭店不构成反义。"}], "correct_answer": "走进", "explanations": {"走进": "反义：走进是从外面到里面，与「走出」的方向相反。", "停留": "无关：停留是不动，与走出饭店没有反义关系。", "坐下": "无关：坐下是姿势的改变，与走出饭店的方向无关。", "躺下": "无关：躺下是姿势，与离开饭店不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94209, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走进", "is_correct": true, "explanation": "反义：走进是从外面到里面，与「走出房间」的方向相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：睡觉是一种动作，与走出房间没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：吃饭是日常活动，与走出房间不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：唱歌与离开房间的动作之间没有反义关系。"}], "correct_answer": "走进", "explanations": {"走进": "反义：走进是从外面到里面，与「走出房间」的方向相反。", "睡觉": "无关：睡觉是一种动作，与走出房间没有反义关系。", "吃饭": "无关：吃饭是日常活动，与走出房间不构成反义。", "唱歌": "无关：唱歌与离开房间的动作之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94209, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走出是从里面走到外面去。", "primary_collocate": null, "pronunciation": "zǒu chū", "ipa": "tsoʊ˨˩˦ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他走出家门，开始跑步。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走出办公室，叫了我的名字。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚走出商店，就下雨了。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们走出饭店，上了车。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走出电梯，看见了朋友。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你走出大门，再往右走。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫走出盒子，看了看我。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理走出会议室，很高兴。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家走出教室，排好队。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书包放下，走出了房间。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走出来", "label": "复合趋向"}, {"form": "走出去", "label": "复合趋向"}], "register": "中性", "sense_fingerprint": "从里面走到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走出", "is_correct": true, "explanation": "正确。走出指从家里走到外面，与「开始跑步」衔接自然。"}, {"text": "拿出", "is_correct": false, "explanation": "配价：「拿出」要求有被拿的东西作宾语，「他拿出家门」不成立。"}, {"text": "扔出", "is_correct": false, "explanation": "配价：「扔出」要求有被扔的对象，「他扔出家门」不成立。"}, {"text": "唱出", "is_correct": false, "explanation": "搭配：「唱」与「家门」的离开动作不搭配，不能表示走出家门。"}], "explanations": {"走出": "正确。走出指从家里走到外面，与「开始跑步」衔接自然。", "拿出": "配价：「拿出」要求有被拿的东西作宾语，「他拿出家门」不成立。", "扔出": "配价：「扔出」要求有被扔的对象，「他扔出家门」不成立。", "唱出": "搭配：「唱」与「家门」的离开动作不搭配，不能表示走出家门。"}, "sentence_index": 0, "correct_answer": "走出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "烟从烟囱走出来了。", "explanation": "这里应该用〈冒出〉。烟没有行走的动作，「走出」要求能自主移动的主语；烟从烟囱里出来应说「冒出」。"}, {"text": "他终于走出了这个消息。", "explanation": "这里应该用〈消化〉。走出表示离开或摆脱，不能接「消息」这类抽象对象；接受并理解一个消息要用「消化」。"}, {"text": "这场雨已经走出了一个小时。", "explanation": "这里应该用〈下〉。雨不会行走，走出也不能表示时间；雨持续一段时间要说「下了一个小时」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走出", "is_correct": true, "explanation": "正确。走出指小猫从盒子里出来，与后面「看了看我」的语境吻合。"}, {"text": "翻出", "is_correct": false, "explanation": "搭配：「翻」是翻动，不能表示小猫从盒子里出来。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：「吃掉」是吞食，盒子不能被小猫吃掉后再看人，句意不通。"}, {"text": "咬出", "is_correct": false, "explanation": "搭配：「咬」与「盒子」不搭配，不能表示小猫离开盒子。"}], "explanations": {"走出": "正确。走出指小猫从盒子里出来，与后面「看了看我」的语境吻合。", "翻出": "搭配：「翻」是翻动，不能表示小猫从盒子里出来。", "吃掉": "语义：「吃掉」是吞食，盒子不能被小猫吃掉后再看人，句意不通。", "咬出": "搭配：「咬」与「盒子」不搭配，不能表示小猫离开盒子。"}, "sentence_index": 6, "correct_answer": "走出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题他很快走出了。", "explanation": "这里应该用〈解出〉。走出表示离开或摆脱，不能用于题目，解题要用「解出」。"}, {"text": "泪水从他的眼睛里走出来了。", "explanation": "这里应该用〈流出〉。泪水是液体，不能自己行走，应说「流出」。"}, {"text": "他走出了这个班的同学。", "explanation": "这里应该用〈离开〉。走出不能接人作宾语，离开一个人要用「离开」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他走出去大楼。", "corrected_sentence": "他走出了大楼。", "error_description": "补语错误：「去」误加在「走出」之后，又直接带处所宾语，应说「走出了大楼」，用「了」表示完成，不能说「走出去大楼」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫终于走出来盒子。", "corrected_sentence": "小猫终于走出了盒子。", "error_description": "补语错误：「来」误替代「了」，「走出」带宾语「盒子」时要说「走出了盒子」，不能说「走出来盒子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
