INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94210, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陷入", "is_correct": true, "explanation": "反义：陷入是落入某种困境之中，与「走出困难」的状态相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：睡觉是一种动作，与摆脱困难没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：吃饭是日常活动，与走出困难不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：唱歌与摆脱困难的状态之间没有反义关系。"}], "correct_answer": "陷入", "explanations": {"陷入": "反义：陷入是落入某种困境之中，与「走出困难」的状态相反。", "睡觉": "无关：睡觉是一种动作，与摆脱困难没有反义关系。", "吃饭": "无关：吃饭是日常活动，与走出困难不构成反义。", "唱歌": "无关：唱歌与摆脱困难的状态之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从内部步行到外部；离开某个范围。", "primary_collocate": null, "pronunciation": "zǒu chū", "ipa": "tsoʊ˨˩˦ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他慢慢走出了教室。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗走出门，抬头看见了太阳。", "target_word": "走出", "complexity_tier": "T3", "furigana": "xiǎo gǒu zǒu chū mén, tái tóu kàn jiàn le tài yáng.", "sentence_source": "generated"}, {"text": "我们走出车站，天已经黑了。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走出房间，关上了门。", "target_word": "走出", "complexity_tier": "T3", "furigana": "tā zǒu chū fáng jiān, guān shàng le mén.", "sentence_source": "generated"}, {"text": "走出这座山，就是一个小镇。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于走出了难过的日子。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们走出学校，跑向妈妈。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人走出医院，笑着说话。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你走出这个房间。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要走出困难，向前看。", "target_word": "走出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走出来", "label": "复合趋向"}, {"form": "走出去", "label": "复合趋向"}], "register": "中性", "sense_fingerprint": "步行离开某处或某种状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走出", "is_correct": true, "explanation": "正确。走出指从教室里走到外面，与「慢慢」搭配自然。"}, {"text": "飞出", "is_correct": false, "explanation": "语义：人不会飞，「飞出」与「他」的动作不相符。"}, {"text": "跳出", "is_correct": false, "explanation": "搭配：「跳」动作快，与「慢慢」搭配不当。"}, {"text": "扔出", "is_correct": false, "explanation": "配价：「扔出」要求有被扔的东西作宾语，「他慢慢扔出了教室」不成立。"}], "explanations": {"走出": "正确。走出指从教室里走到外面，与「慢慢」搭配自然。", "飞出": "语义：人不会飞，「飞出」与「他」的动作不相符。", "跳出": "搭配：「跳」动作快，与「慢慢」搭配不当。", "扔出": "配价：「扔出」要求有被扔的东西作宾语，「他慢慢扔出了教室」不成立。"}, "sentence_index": 0, "correct_answer": "走出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "香味从厨房走出来了。", "explanation": "这里应该用〈飘出〉。香味是气体，没有行走的动作，应说「飘出」。"}, {"text": "他终于走出了绳子。", "explanation": "这里应该用〈挣脱〉。走出要接表示地点或范围的词，不能接「绳子」这类束缚物。"}, {"text": "这件事已经走出了一个星期。", "explanation": "这里应该用〈度过〉。走出表示离开或摆脱，不能表示一段时间；经历一段时间要说「度过」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走出", "is_correct": true, "explanation": "正确。走出指从学校里走到外面，与「跑向妈妈」的动作衔接自然。"}, {"text": "翻出", "is_correct": false, "explanation": "搭配：「翻」是翻动，不能表示孩子从学校里出来。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：「吃掉」是吞食，学校不能被孩子吃掉，与句意不符。"}, {"text": "唱出", "is_correct": false, "explanation": "搭配：「唱」与「学校」的离开动作不搭配，不能表示走出学校。"}], "explanations": {"走出": "正确。走出指从学校里走到外面，与「跑向妈妈」的动作衔接自然。", "翻出": "搭配：「翻」是翻动，不能表示孩子从学校里出来。", "吃掉": "语义：「吃掉」是吞食，学校不能被孩子吃掉，与句意不符。", "唱出": "搭配：「唱」与「学校」的离开动作不搭配，不能表示走出学校。"}, "sentence_index": 6, "correct_answer": "走出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要走出朋友，向前看。", "explanation": "这里应该用〈离开〉。走出不能接人作宾语，离开一个人要用「离开」。"}, {"text": "这道题我已经走出了十分钟。", "explanation": "这里应该用〈花〉。走出表示离开或摆脱，不能表示时间；花费时间要说「花」。"}, {"text": "这块石头要走出困难，向前看。", "explanation": "这里应该用〈克服〉。走出困难指人从困境中脱身，石头不会主动行走；战胜困难要用「克服」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于从走出了房间。", "corrected_sentence": "他终于走出了房间。", "error_description": "多余的介词：「走出」本身已表示从里面到外面，前面不能再加「从」，应说「他终于走出了房间」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于走出着困境。", "corrected_sentence": "我们终于走出了困境。", "error_description": "体标错误：「终于」表示动作已经完成，「走出」后应用「了」，不能用表示持续的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
