INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "起点是开始的地方。", "primary_collocate": null, "pronunciation": "qǐ diǎn", "ipa": "tɕʰi˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "跑步比赛的起点在学校门口。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁一号线的起点是这个车站。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从公园的起点开始走。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的起点在哪里？", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在起点，等老师说开始。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起点离我家很近，走路五分钟。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们骑自行车从起点出发。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的起点和终点都在同一个地方。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在地图上找一下起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起点的旁边有一家小商店。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "起点站", "label": "复合"}, {"form": "起點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "路线或比赛开始的具体地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5b7ecc2-1826-4293-b41b-b692521b4ccb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "正确：“起点”指比赛开始的具体地点，“比赛的起点在学校门口”符合语境。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是上课的场所，不能用来指比赛的地点。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时刻，不能说“在学校门口”，与具体地点的语境不符。"}, {"text": "名次", "is_correct": false, "explanation": "搭配：“名次”指比赛的结果，不能说“名次在学校门口”。"}], "explanations": {"起点": "正确：“起点”指比赛开始的具体地点，“比赛的起点在学校门口”符合语境。", "教室": "语义：“教室”是上课的场所，不能用来指比赛的地点。", "时间": "语义：“时间”指时刻，不能说“在学校门口”，与具体地点的语境不符。", "名次": "搭配：“名次”指比赛的结果，不能说“名次在学校门口”。"}, "sentence_index": 0, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的起点是友谊。", "explanation": "义项：“起点”指具体的地点，不指抽象的事物；说抽象的开始要用“开端”。"}, {"text": "比赛的起点是三点。", "explanation": "义项：“起点”指具体的地点，不指时刻；说比赛开始的时间要用“开始”。"}, {"text": "这条路有一只起点。", "explanation": "量词：“起点”应该用量词“个”，“只”不能用于“起点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "正确：“起点”指出发的具体地点，“从起点出发”符合语境。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“答案”是抽象的结果，不能作为骑车出发的地点。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是骑自行车出发的地点，与具体的出发点不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不是地点，不能说“从天气出发”。"}], "explanations": {"起点": "正确：“起点”指出发的具体地点，“从起点出发”符合语境。", "答案": "搭配：“答案”是抽象的结果，不能作为骑车出发的地点。", "天空": "语义：“天空”不是骑自行车出发的地点，与具体的出发点不符。", "天气": "搭配：“天气”不是地点，不能说“从天气出发”。"}, "sentence_index": 6, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校的起点旁边有一家小商店。", "explanation": "替换：“入口”指进入的地方，“起点”指出发的地方，学校的进口应说“入口”。"}, {"text": "这条路的起点是三个朋友。", "explanation": "义项：“起点”指地点，不指人；说人群要用“人们”。"}, {"text": "这条路有一位起点。", "explanation": "量词：“起点”应该用量词“个”，“位”用于人，不能用于“起点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的一只起点在山上。", "corrected_sentence": "这条河的起点在山上。", "error_description": "多了量词短语：“起点”前面不能加“一只”，应直接说“这条河的起点在山上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在起点们集合，然后出发。", "corrected_sentence": "他们在起点集合，然后出发。", "error_description": "错误：“们”只用于指人的名词或代词，不能加在“起点”后面。正确：“他们在起点集合，然后出发。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "终点", "is_correct": true, "explanation": "正确：“终点”与“起点”构成反义，指事情结束或行程结束的地方。"}, {"text": "花园", "is_correct": false, "explanation": "无关：“花园”是具体场所，与“起点”的开始义不构成反义。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”是具体物件，与“起点”没有反义关系。"}, {"text": "答案", "is_correct": false, "explanation": "无关：“答案”是抽象名词，与“起点”没有反义关系。"}], "correct_answer": "终点", "explanations": {"终点": "正确：“终点”与“起点”构成反义，指事情结束或行程结束的地方。", "花园": "无关：“花园”是具体场所，与“起点”的开始义不构成反义。", "窗户": "无关：“窗户”是具体物件，与“起点”没有反义关系。", "答案": "无关：“答案”是抽象名词，与“起点”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "终点", "is_correct": true, "explanation": "正确：“终点”与“起点”构成反义，指行程或事情结束的地方。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是具体家具，与“起点”没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "无关：“天空”是自然景物，与“起点”没有反义关系。"}, {"text": "数字", "is_correct": false, "explanation": "无关：“数字”是抽象名词，与“起点”没有反义关系。"}], "correct_answer": "终点", "explanations": {"终点": "正确：“终点”与“起点”构成反义，指行程或事情结束的地方。", "桌子": "无关：“桌子”是具体家具，与“起点”没有反义关系。", "天空": "无关：“天空”是自然景物，与“起点”没有反义关系。", "数字": "无关：“数字”是抽象名词，与“起点”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情、事业或过程开始的阶段或时间。", "primary_collocate": null, "pronunciation": "qǐ diǎn", "ipa": "tɕʰi˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次工作是他事业的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高中毕业不是结束，是新生活的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的习惯是成功的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的起点不一样，不要和别人比。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小店是他做生意的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从零开始也可以是一个好的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好拼音是学汉语的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次见面是我们友谊的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起点低没关系，只要努力就能进步。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败也是他重新开始的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "起点站", "label": "复合"}, {"form": "起點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事业、学习等抽象过程的开始阶段或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5b7ecc2-1826-4293-b41b-b692521b4ccb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "正确：“起点”指事情开始的地方或时间，“事业的起点”符合语境。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”是场所，不能用来指事业的开始阶段，与“起点”的抽象义不符。"}, {"text": "错误", "is_correct": false, "explanation": "语义：“错误”指失误，不能用来指事业的开始阶段。"}, {"text": "口号", "is_correct": false, "explanation": "语义：“口号”是宣传用的话，不能说成事业的开始阶段。"}], "explanations": {"起点": "正确：“起点”指事情开始的地方或时间，“事业的起点”符合语境。", "地点": "语义：“地点”是场所，不能用来指事业的开始阶段，与“起点”的抽象义不符。", "错误": "语义：“错误”指失误，不能用来指事业的开始阶段。", "口号": "语义：“口号”是宣传用的话，不能说成事业的开始阶段。"}, "sentence_index": 0, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们到了比赛的起点，可是比赛已经结束了。", "explanation": "义项：“起点”指开始的地方，比赛已经结束时应说“终点”；“起点”不能指结束的地方。"}, {"text": "这次比赛的起点是冠军。", "explanation": "义项：“起点”指开始的地方或时间，不指结果；说比赛的结果要用“结果”或“成绩”。"}, {"text": "这次工作是他事业的一只起点。", "explanation": "量词：“起点”应该用量词“个”，“只”用于动物或成对的东西，不能用于“起点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "正确：“起点”指开始的阶段，“学汉语的起点”符合语境。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：“停车场”是具体场所，不能用来指学习的开始。"}, {"text": "车库", "is_correct": false, "explanation": "语义：“车库”是存放车辆的场所，与“学汉语”的抽象义不符。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”多用于商品，不能说“学汉语的包装”。"}], "explanations": {"起点": "正确：“起点”指开始的阶段，“学汉语的起点”符合语境。", "停车场": "语义：“停车场”是具体场所，不能用来指学习的开始。", "车库": "语义：“车库”是存放车辆的场所，与“学汉语”的抽象义不符。", "包装": "搭配：“包装”多用于商品，不能说“学汉语的包装”。"}, "sentence_index": 6, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行的起点很长。", "explanation": "义项：“起点”指地点或时间，不能用“长”来形容；说长短要用“路程”或“时间”。"}, {"text": "旅行的起点是三天。", "explanation": "义项：“起点”指开始的地方或时间，不是持续的时长；“三天”是时长。"}, {"text": "这次旅行的起点很聪明。", "explanation": "义项：“起点”指地点或时间，不能用来形容人的性格，应说“机敏”的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找到了一只新的起点。", "corrected_sentence": "他找到了一个新的起点。", "error_description": "量词错误：“起点”应该用量词“个”，“只”用于动物或成对的东西，不能用于“起点”，应为“一个新的起点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这次经历当作一个的新起点。", "corrected_sentence": "他把这次经历当作一个新的起点。", "error_description": "语序错误：“新的”是修饰“起点”的定语，应为“一个新的起点”；“的新”颠倒了“新”和“的”的位置，不能成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
