INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "接在这一次之后的那一次。", "primary_collocate": null, "pronunciation": "xià yí cì", "ipa": "ɕja˥˩ i˧˥ tsʰɨ˥˩", "syllable_count": 3, "sentences": [{"text": "这一次是我，下一次轮到你。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次检查很好，下一次在三月。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这次没买，下一次再买吧。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这次输了，下一次要把比分赢回来。", "target_word": "下一次", "complexity_tier": "T3", "furigana": "wǒmen zhè cì shū le, xià yí cì yào bǎ bǐfēn yíng huí lái", "sentence_source": "generated"}, {"text": "第一次很难，下一次会容易一些。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下一次上课要带课本。", "target_word": "下一次", "complexity_tier": "T3", "furigana": "lǎoshī shuō, xià yí cì shàng kè yào dài kèběn", "sentence_source": "generated"}, {"text": "这次先看到这里，下一次继续。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上一次他迟到了，下一次不能再迟到。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这次做错了，下一次要小心。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一次开会，请大家准时到。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "这一次之后紧接着的那一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下一次", "is_correct": true, "explanation": "正确：“下一次”表示这次之后的那一次，符合“轮到你”的语境。"}, {"text": "地方", "is_correct": false, "explanation": "语义：“地方”不能轮到人，句子不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能作为“轮到”的主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能“轮到”人，与语境不符。"}], "explanations": {"下一次": "正确：“下一次”表示这次之后的那一次，符合“轮到你”的语境。", "地方": "语义：“地方”不能轮到人，句子不通。", "作业": "搭配：“作业”不能作为“轮到”的主语。", "天气": "语义：天气不能“轮到”人，与语境不符。"}, "sentence_index": 0, "correct_answer": "下一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下一次，我们在三年前就认识了。", "explanation": "这里应该用〈上一次〉。下一次指将来的一次，不能用来说三年前已经发生的事。"}, {"text": "下一次他还很年轻，每天骑车上学。", "explanation": "这里应该用〈那时候〉。下一次指将来的一次，不能用来描述过去的年龄和习惯。"}, {"text": "下一次，我的爷爷已经去世十年了。", "explanation": "这里应该用〈以前〉。下一次指将来的一次，不能用来说已经过去十年的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下一次", "is_correct": true, "explanation": "正确：“下一次”表示接着的那一次，符合“继续”的语境。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“继续”的主体是人或动作，钢琴不能作“继续”的主语。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能“继续”，与“先看到这里”的语境不通。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不能“继续”，与语境不符。"}], "explanations": {"下一次": "正确：“下一次”表示接着的那一次，符合“继续”的语境。", "钢琴": "搭配：“继续”的主体是人或动作，钢琴不能作“继续”的主语。", "花园": "语义：花园不能“继续”，与“先看到这里”的语境不通。", "镜子": "语义：镜子不能“继续”，与语境不符。"}, "sentence_index": 6, "correct_answer": "下一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下一次，大家已经在这里等了一个小时。", "explanation": "这里应该用〈过去〉。下一次指将来的一次，不能用来说已经等了很久的事。"}, {"text": "下一次，老师上星期就在这里讲过话。", "explanation": "这里应该用〈上次〉。下一次指将来的一次，不能用来说上星期已经发生的事。"}, {"text": "下一次我很胖，不喜欢运动。", "explanation": "这里应该用〈小时候〉。下一次指将来，不能用来描述过去的特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下一次的我们再去看看吧。", "corrected_sentence": "下一次我们再去看看吧。", "error_description": "“下一次”后加“的”后变成修饰“我们”的定语，句子不通；应去掉“的”，说“下一次我们再去看看吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下一次的我们再换个地方吧。", "corrected_sentence": "下一次我们再换个地方吧。", "error_description": "“的”放在“下一次”之后会把时间词变成定语，句子不通，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不外是说不会超出这些，就只是这样。", "primary_collocate": null, "pronunciation": "bù wài", "ipa": "pu˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "他每天的生活不外吃饭、睡觉和工作。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到的原因不外是起晚了或者路上堵车。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的游戏不外跑步、跳绳和踢球。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的爱好不外看书和听音乐。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末的活动不外逛街或者看电影。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家问的问题不外这几个。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话不外是想让我们早点回家。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天不外是热和湿。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们聊天，说的不外是孩子和身体。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜不外那几样，价格都不贵。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示范围有限，后面列举的内容就是全部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5b7ecc2-1826-4293-b41b-b692521b4ccb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“每天”的习惯矛盾，句子读来不通。"}, {"text": "不外", "is_correct": true, "explanation": "正确：“不外”表示范围有限，后面的“吃饭、睡觉和工作”就是生活的全部内容。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与“每天”的习惯性动作不相容。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有与之相对的内容，无法衔接。"}], "explanations": {"偶尔": "语义：“偶尔”表示不常发生，与“每天”的习惯矛盾，句子读来不通。", "不外": "正确：“不外”表示范围有限，后面的“吃饭、睡觉和工作”就是生活的全部内容。", "已经": "体貌：“已经”表示动作已经完成，与“每天”的习惯性动作不相容。", "却": "语义：“却”表示转折，句中没有与之相对的内容，无法衔接。"}, "sentence_index": 0, "correct_answer": "不外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说要来，不外没来。", "explanation": "这里应该用〈却〉。不外是表示范围有限的副词，不表示转折；“他说要来，却没来”表示与预期相反，要用〈却〉。"}, {"text": "他很不外高兴。", "explanation": "用法：“不外”表示范围有限，不修饰形容词表示程度；“他很高兴”才自然，应去掉“不外”。"}, {"text": "这道题很难，不外我会做。", "explanation": "这里应该用〈可是〉。不外是副词，表示范围有限，不表示转折；“这道题很难，可是我会做”才是转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间上刚发生，与“说的话”的内容判断不符，读来不通。"}, {"text": "不外", "is_correct": true, "explanation": "正确：“不外”表示说话的内容只限于此，“想让我们早点回家”就是他话里的全部意思。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”多修饰突然发生的事，不修饰“说的话”这样的内容判断。"}, {"text": "随即", "is_correct": false, "explanation": "语义：“随即”表示紧接着发生，与“说的话”的内容判断不符。"}], "explanations": {"刚刚": "语义：“刚刚”表示时间上刚发生，与“说的话”的内容判断不符，读来不通。", "不外": "正确：“不外”表示说话的内容只限于此，“想让我们早点回家”就是他话里的全部意思。", "忽然": "搭配：“忽然”多修饰突然发生的事，不修饰“说的话”这样的内容判断。", "随即": "语义：“随即”表示紧接着发生，与“说的话”的内容判断不符。"}, "sentence_index": 6, "correct_answer": "不外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他五点不外回到家。", "explanation": "这里应该用〈才〉。不外表示范围或结论，不表示时间的晚或早；“五点才回到家”表示时间偏晚，要用〈才〉。"}, {"text": "他不外会唱歌，还会跳舞。", "explanation": "这里应该用〈不但〉。不外表示只限于此，与“还”搭配会自相矛盾；“不但会唱歌，还会跳舞”才是递进。"}, {"text": "他不外变得更忙了。", "explanation": "这里应该用〈反而〉。不外表示只限于此，不表示出乎意料的转变；“反而变得更忙了”表示相反的结果，要用〈反而〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的工作不外写报告和开会。", "corrected_sentence": "他的工作不外是写报告和开会。", "error_description": "缺少“是”：“不外”表示范围有限时须与“是”构成固定格式“不外是……”，此处漏掉“是”，应为“他的工作不外是写报告和开会。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩只不外是中等偏下。", "corrected_sentence": "他的成绩不外是中等偏下。", "error_description": "错误：多用了“只”，与“不外”重复表示“只是”。正确：“不外是”，去掉“只”。“不外”本身已经表示范围有限，不必再加“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
