INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94237, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "偶像是你特别喜欢、很想学他的人。", "primary_collocate": null, "pronunciation": "ǒu xiàng", "ipa": "ou˨˩˦ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我的偶像是一位年轻的足球运动员。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就把妈妈当成偶像。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是很多男孩子的偶像。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学他，因为他是我的偶像。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的偶像每天五点起床跑步，他也这样做。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有自己的偶像？", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的偶像是我的数学老师，他很有耐心。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟每天模仿自己的偶像说话，想变得和他一样。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见到偶像的那天，她高兴得说不出话。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要向偶像学习，每天多练习一小时。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "偶像歌手", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己特别喜欢并想学习的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5b7ecc2-1826-4293-b41b-b692521b4ccb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94237, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶像", "is_correct": true, "explanation": "正确：“偶像”指自己特别喜欢、想学习的人，与“一位年轻的足球运动员”相符。"}, {"text": "对象", "is_correct": false, "explanation": "语义：“对象”口语中指恋爱对象，与“喜欢并想学习”的语义不符。"}, {"text": "神像", "is_correct": false, "explanation": "语义：“神像”指供奉的塑像，不能指一位活生生的运动员。"}, {"text": "教具", "is_correct": false, "explanation": "搭配：“教具”指教学用具，不能与“一位运动员”同指。"}], "explanations": {"偶像": "正确：“偶像”指自己特别喜欢、想学习的人，与“一位年轻的足球运动员”相符。", "对象": "语义：“对象”口语中指恋爱对象，与“喜欢并想学习”的语义不符。", "神像": "语义：“神像”指供奉的塑像，不能指一位活生生的运动员。", "教具": "搭配：“教具”指教学用具，不能与“一位运动员”同指。"}, "sentence_index": 0, "correct_answer": "偶像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹每天用一个偶像当闹钟。", "explanation": "这里应该用〈闹钟〉。“偶像”指人，不能当闹钟用。"}, {"text": "这辆跑车是我的偶像。", "explanation": "这里应该用〈梦想〉。“偶像”指值得学习、受人仰慕的人，不指物品；一辆车表示想拥有的目标，应用〈梦想〉。"}, {"text": "他在食堂用一个偶像打饭。", "explanation": "这里应该用〈饭勺〉。“偶像”指人，不能用来盛饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶像", "is_correct": true, "explanation": "正确：“偶像”指自己想学习的人，与“我的数学老师”可以同指。"}, {"text": "同桌", "is_correct": false, "explanation": "语义：“同桌”指同坐一张桌子的同学，与“老师”身份不符。"}, {"text": "家长", "is_correct": false, "explanation": "语义：“家长”指孩子的父母，与“老师”身份不符。"}, {"text": "球鞋", "is_correct": false, "explanation": "搭配：“球鞋”是物品，不能与“我的数学老师”同指。"}], "explanations": {"偶像": "正确：“偶像”指自己想学习的人，与“我的数学老师”可以同指。", "同桌": "语义：“同桌”指同坐一张桌子的同学，与“老师”身份不符。", "家长": "语义：“家长”指孩子的父母，与“老师”身份不符。", "球鞋": "搭配：“球鞋”是物品，不能与“我的数学老师”同指。"}, "sentence_index": 6, "correct_answer": "偶像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天用一个偶像喝水。", "explanation": "这里应该用〈水杯〉。“偶像”指崇拜的人，不能用来喝水。"}, {"text": "这份计划是我们的偶像，大家都要学习它。", "explanation": "这里应该用〈范本〉。“偶像”指受崇拜的人物，不指计划；值得借鉴的计划应称为〈范本〉。"}, {"text": "他每天用一套偶像喝茶。", "explanation": "这里应该用〈茶具〉。“偶像”指人，不能作为喝茶的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一只偶像是老师，他教我怎样做人。", "corrected_sentence": "我的一位偶像是老师，他教我怎样做人。", "error_description": "错误：“偶像”指人，量词应用“位”，“只”不能用来修饰人。应为“一位偶像”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她偶像是一位画家，她也想学画画。", "corrected_sentence": "她的偶像是一位画家，她也想学画画。", "error_description": "错误：漏掉“的”。“她的偶像”是定语结构，应有“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
