INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受人崇拜和仰慕的人物。", "primary_collocate": null, "pronunciation": "ǒu xiàng", "ipa": "ou˨˩˦ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这位歌手是年轻人的偶像。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是全国观众心中的偶像。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位电影明星成了无数人崇拜的偶像。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位偶像在中国很有名。", "target_word": "偶像", "complexity_tier": "T3", "furigana": "nà wèi ǒu xiàng zài Zhōng guó hěn yǒu míng", "sentence_source": "generated"}, {"text": "他从小是大家的偶像，现在还是。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶像出现的时候，许多粉丝在门口等着。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员是国家的偶像。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对很多球迷来说，他就是偶像。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶像的一句话，可以影响很多年轻人。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想只做偶像，还想做一个好演员。", "target_word": "偶像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "偶像歌手", "label": "复合"}], "register": "中性", "sense_fingerprint": "受大众崇拜和仰慕的人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5b7ecc2-1826-4293-b41b-b692521b4ccb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶像", "is_correct": true, "explanation": "正确：“偶像”指受大众崇拜的人物，与“年轻人的”相符。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”指仇恨的对象，与“偶像”的崇拜义相反。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“病人”指就医的人，不能说“年轻人的病人”来表示被崇拜。"}, {"text": "保姆", "is_correct": false, "explanation": "语义：“保姆”指照顾家务的人，与受崇拜的人物义不符。"}], "explanations": {"偶像": "正确：“偶像”指受大众崇拜的人物，与“年轻人的”相符。", "仇人": "语义：“仇人”指仇恨的对象，与“偶像”的崇拜义相反。", "病人": "搭配：“病人”指就医的人，不能说“年轻人的病人”来表示被崇拜。", "保姆": "语义：“保姆”指照顾家务的人，与受崇拜的人物义不符。"}, "sentence_index": 0, "correct_answer": "偶像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的偶像是一瓶矿泉水。", "explanation": "这里应该用〈饮料〉。“偶像”指受崇拜的人物，不指一瓶水。"}, {"text": "这盏台灯是全国的偶像，大家都想要一盏。", "explanation": "这里应该用〈名牌〉。“偶像”指受崇拜的人物，不指台灯等物品；指有名的产品，应用〈名牌〉。"}, {"text": "这家店的偶像很有名。", "explanation": "这里应该用〈招牌〉。“偶像”指受崇拜的人物，不指店铺的标志。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶像", "is_correct": true, "explanation": "正确：“偶像”指受国家大众崇拜的人物，与“国家的”相符。"}, {"text": "邻居", "is_correct": false, "explanation": "搭配：“邻居”指住得近的人，不能说“国家的邻居”。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”指驾驶车辆的人，与受崇拜人物的义项不符。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“账单”是书面凭证，不能与“国家的”和人物搭配。"}], "explanations": {"偶像": "正确：“偶像”指受国家大众崇拜的人物，与“国家的”相符。", "邻居": "搭配：“邻居”指住得近的人，不能说“国家的邻居”。", "司机": "语义：“司机”指驾驶车辆的人，与受崇拜人物的义项不符。", "账单": "搭配：“账单”是书面凭证，不能与“国家的”和人物搭配。"}, "sentence_index": 6, "correct_answer": "偶像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这句偶像影响了很多年轻人。", "explanation": "这里应该用〈标语〉。“偶像”指受崇拜的人，不指一句话。"}, {"text": "这面偶像象征着国家。", "explanation": "这里应该用〈旗帜〉。“偶像”指人物，不指旗子。"}, {"text": "这张偶像很贵，很多人买不到。", "explanation": "这里应该用〈门票〉。“偶像”指人物，不能作为可以购买的票证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是年轻人心中的一只偶像。", "corrected_sentence": "他是年轻人心中的一位偶像。", "error_description": "错误：“偶像”指受崇拜的人，量词应用“位”，“只”不能修饰人。应为“一位偶像”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位演员一直是女孩们偶像。", "corrected_sentence": "这位演员一直是女孩们的偶像。", "error_description": "错误：漏掉“的”。“女孩们的偶像”是定语结构，应有“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b547b8e-09a3-40ce-a101-547a027b9e40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
