INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公司内部为讨论、决定事务而召开的会议。", "primary_collocate": null, "pronunciation": "gōng sī huì yì", "ipa": "kʊŋ˥ sɹ̩˥ xueɪ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "明天上午九点有公司会议。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会议上，经理讲了新计划。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的公司会议开了两个小时。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没参加这次公司会议。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会议决定下个月换新办公室。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为公司会议，我今天不能早回家。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会议讨论了明年的工作计划。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会议每个星期一早上开。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同事们在公司会议上提出了很多问题。", "target_word": "公司会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司会议结束后，大家回到自己的座位。", "target_word": "公司会议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "场", "label": "量词"}], "register": "中性", "sense_fingerprint": "公司内部为讨论、决定事务而召开的会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5159ab8-5210-402a-9e8c-41ff5dea1a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公司会议", "is_correct": true, "explanation": "正确：“公司会议”是公司内部讨论事务的会，明天上午九点举行很自然。"}, {"text": "夜市", "is_correct": false, "explanation": "语义：夜市是晚上营业的集市，上午九点不会开。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜是深夜，与“上午九点”矛盾。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只描述人的体型，不能作为上午发生的事件。"}], "explanations": {"公司会议": "正确：“公司会议”是公司内部讨论事务的会，明天上午九点举行很自然。", "夜市": "语义：夜市是晚上营业的集市，上午九点不会开。", "午夜": "语义：午夜是深夜，与“上午九点”矛盾。", "身材": "体貌：“身材”只描述人的体型，不能作为上午发生的事件。"}, "sentence_index": 0, "correct_answer": "公司会议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司会议上，老师表扬了小明。", "explanation": "这里应该用〈家长会〉。公司会议讨论的是公司事务，表扬学生要在家长会上进行。"}, {"text": "新人在公司会议上交换了戒指。", "explanation": "这里应该用〈婚礼〉。公司会议是讨论、决定事务的会，交换戒指要在婚礼上进行。"}, {"text": "同学们在公司会议上玩游戏。", "explanation": "这里应该用〈同学聚会〉。公司会议是讨论工作的会，玩游戏要在同学聚会上进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公司会议", "is_correct": true, "explanation": "正确：只有“公司会议”这样由人参加的会议，才能讨论工作计划，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“讨论”需要有人作主语，“天气”不能讨论工作计划。"}, {"text": "毕业典礼", "is_correct": false, "explanation": "语义：毕业典礼是庆祝毕业的仪式，不会用来讨论工作计划。"}, {"text": "球赛", "is_correct": false, "explanation": "语义：球赛是体育比赛，不用来讨论明年的工作计划。"}], "explanations": {"公司会议": "正确：只有“公司会议”这样由人参加的会议，才能讨论工作计划，符合句意。", "天气": "配价：“讨论”需要有人作主语，“天气”不能讨论工作计划。", "毕业典礼": "语义：毕业典礼是庆祝毕业的仪式，不会用来讨论工作计划。", "球赛": "语义：球赛是体育比赛，不用来讨论明年的工作计划。"}, "sentence_index": 6, "correct_answer": "公司会议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动员在公司会议上跑完了百米。", "explanation": "这里应该用〈运动会〉。公司会议是讨论、决定事务的会，跑百米要在运动会上进行。"}, {"text": "学生们在公司会议上参加了期末考试。", "explanation": "这里应该用〈考试〉。公司会议只用来讨论、决定事务，参加期末考试不是它的用途。"}, {"text": "游客在公司会议上参观了故宫。", "explanation": "这里应该用〈旅游〉。公司会议是讨论、决定事务的会，参观故宫是旅游的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每周一开一只公司会议讨论销售情况。", "corrected_sentence": "我们每周一开一次公司会议讨论销售情况。", "error_description": "量词错误：会议应用量词“次”，不能用“只”（“只”多用于动物等物体），应说“开一次公司会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的公司会议们都开得很短。", "corrected_sentence": "这个月的公司会议都开得很短。", "error_description": "词缀错误：“们”只能加在指人的名词后面，不能加在“公司会议”后面，应说“公司会议都开得很短”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
