INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94245, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "南北是南边和北边。", "primary_collocate": null, "pronunciation": "nán běi", "ipa": "nan˧˥ pei̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "院子的南北两侧都种着树。", "target_word": "南北", "complexity_tier": "T3", "furigana": "yuàn zi de nán běi liǎng cè dōu zhòng zhe shù.", "sentence_source": "generated"}, {"text": "这块地的南北两端都立着界碑。", "target_word": "南北", "complexity_tier": "T3", "furigana": "zhè kuài dì de nán běi liǎng duān dōu lì zhe jiè bēi.", "sentence_source": "generated"}, {"text": "房子的南北两面都有窗户。", "target_word": "南北", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河的南北两边都是田。", "target_word": "南北", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座楼的南北两面墙都是玻璃。", "target_word": "南北", "complexity_tier": "T3", "furigana": "zhè zuò lóu de nán běi liǎng miàn qiáng dōu shì bō li.", "sentence_source": "generated"}, {"text": "公园南北都有大门。", "target_word": "南北", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在地图上标出了城的南北两门。", "target_word": "南北", "complexity_tier": "T3", "furigana": "tā zài dì tú shàng biāo chū le chéng de nán běi liǎng mén.", "sentence_source": "generated"}, {"text": "河水从北向南流，南北两岸都有人家。", "target_word": "南北", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桥的南北两头都有人看着。", "target_word": "南北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥连着河的南北两岸。", "target_word": "南北", "complexity_tier": "T3", "furigana": "zhè zuò qiáo lián zhe hé de nán běi liǎng àn.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "南边和北边的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fdbd29-1997-4230-a16c-4778c9f154ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大小", "is_correct": false, "explanation": "语义：大小指尺寸，不是方位，不能说“院子的大小两侧”。"}, {"text": "南北", "is_correct": true, "explanation": "正确：南北指南边和北边，作为“两侧”的范围，与句意相符。"}, {"text": "高低", "is_correct": false, "explanation": "语义：高低描述高度，不能表示院子的两个方位侧面。"}, {"text": "男女", "is_correct": false, "explanation": "搭配：男女是人的性别，不是方位，不能与“两侧”搭配。"}], "explanations": {"大小": "语义：大小指尺寸，不是方位，不能说“院子的大小两侧”。", "南北": "正确：南北指南边和北边，作为“两侧”的范围，与句意相符。", "高低": "语义：高低描述高度，不能表示院子的两个方位侧面。", "男女": "搭配：男女是人的性别，不是方位，不能与“两侧”搭配。"}, "sentence_index": 0, "correct_answer": "南北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋子的南北有一扇窗，光线很好。", "explanation": "这里应该用〈南面〉。南北指两侧，只有南面一扇窗时不能用“南北”。"}, {"text": "他家的南北有一条小路。", "explanation": "这里应该用〈北面〉。南北表示两侧同时存在，此处只指北面的一条路。"}, {"text": "这座楼的南北有一个花园。", "explanation": "这里应该用〈北面〉或〈东面〉等指单独一侧的方位词。南北指两侧同时存在，不能用来指只在一侧的花园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黑白", "is_correct": false, "explanation": "语义：黑白指颜色，不表示方位，不能说“城的黑白两门”。"}, {"text": "冷热", "is_correct": false, "explanation": "语义：冷热描述温度，与城门的方位无关，不能修饰“两门”。"}, {"text": "南北", "is_correct": true, "explanation": "正确：南北指城的南门和北门，作为“两门”的方位限定，与句意相符。"}, {"text": "公私", "is_correct": false, "explanation": "搭配：公私指公家与个人，不是方位，不能与“两门”搭配。"}], "explanations": {"黑白": "语义：黑白指颜色，不表示方位，不能说“城的黑白两门”。", "冷热": "语义：冷热描述温度，与城门的方位无关，不能修饰“两门”。", "南北": "正确：南北指城的南门和北门，作为“两门”的方位限定，与句意相符。", "公私": "搭配：公私指公家与个人，不是方位，不能与“两门”搭配。"}, "sentence_index": 6, "correct_answer": "南北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天买了两本南北，很有意思。", "explanation": "这里应该用〈书〉。南北指南边和北边，不能指书籍。"}, {"text": "妈妈做的这个南北很好吃，大家都爱吃。", "explanation": "这里应该用〈菜〉。南北指南边和北边，不能指食物。"}, {"text": "他每天晚上都要学习南北，很辛苦。", "explanation": "这里应该用〈数学〉。南北指南边和北边，不能作为学科名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋子的很南北两面都开着窗。", "corrected_sentence": "屋子的南北两面都开着窗。", "error_description": "修饰错误：“南北”是名词，不能被程度副词“很”修饰，应说“屋子的南北两面都开着窗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座楼的南北们两侧都挂着灯笼。", "corrected_sentence": "这座楼的南北两侧都挂着灯笼。", "error_description": "词形错误：“南北”是方位词，后面不能加“们”，应说“南北两侧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
