INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "史上是说从有记录以来，到现在为止。", "primary_collocate": null, "pronunciation": "shǐ shàng", "ipa": "ʂɨ˨˩˦ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这是史上最冷的一个冬天。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的夏天是史上最热的。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的制作费是史上最高的。", "target_word": "史上", "complexity_tier": "T3", "furigana": "zhè bù diàn yǐng de zhì zuò fèi shì shǐ shàng zuì gāo de", "sentence_source": "generated"}, {"text": "他是史上跑得最快的人。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "史上最长的桥在中国。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的雨是这座城市史上最大的。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖出了史上最多的蛋糕。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的人数是史上最多的一次。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "史上最难的考试，我们都通过了。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子是学校史上最小的冠军。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从有记录以来到现在为止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "史上", "is_correct": true, "explanation": "“史上”表示有记录以来的历史，与“最冷”的最高级搭配，适合这句话的纪录语境。"}, {"text": "上午", "is_correct": false, "explanation": "语义：“上午”是一天中的时段，不能与“冬天”构成“最冷的冬天”的比较范围。"}, {"text": "书店", "is_correct": false, "explanation": "语义：“书店”是场所，不能作为冬天温度比较的对象。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“手机”不能与“最冷的一个冬天”搭配，此处语义不通。"}], "explanations": {"史上": "“史上”表示有记录以来的历史，与“最冷”的最高级搭配，适合这句话的纪录语境。", "上午": "语义：“上午”是一天中的时段，不能与“冬天”构成“最冷的冬天”的比较范围。", "书店": "语义：“书店”是场所，不能作为冬天温度比较的对象。", "手机": "搭配：“手机”不能与“最冷的一个冬天”搭配，此处语义不通。"}, "sentence_index": 0, "correct_answer": "史上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我史上第一次去北京，特别兴奋。", "explanation": "这里应该用〈人生〉。史上指有记录以来的世界或社会历史，讲个人经历应说“人生”或“一生中”。"}, {"text": "我史上最喜欢的颜色是蓝色。", "explanation": "这里应该用〈一直〉。史上指整个历史，表示个人长期的喜好应说“一直”。"}, {"text": "我史上吃过最辣的菜是在四川。", "explanation": "这里应该用〈一生中〉。史上不用于个人经历，讲自己吃过的东西应说“一生中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "史上", "is_correct": true, "explanation": "“史上”表示有史以来的纪录，与“最多”的最高级搭配，说明这家店的销量纪录。"}, {"text": "书店", "is_correct": false, "explanation": "语义：“书店”是场所，不能作为“卖出蛋糕”的范围。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“钥匙”不能与“卖出……最多的蛋糕”搭配，此处语义不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是学习用品，与蛋糕的销售无关，不能作为销量的比较范围。"}], "explanations": {"史上": "“史上”表示有史以来的纪录，与“最多”的最高级搭配，说明这家店的销量纪录。", "书店": "语义：“书店”是场所，不能作为“卖出蛋糕”的范围。", "钥匙": "搭配：“钥匙”不能与“卖出……最多的蛋糕”搭配，此处语义不通。", "课本": "语义：“课本”是学习用品，与蛋糕的销售无关，不能作为销量的比较范围。"}, "sentence_index": 6, "correct_answer": "史上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把伞史上很便宜。", "explanation": "这里应该用〈很便宜〉，不加〈史上〉。史上只用于有史以来的纪录或最高级语境，不能修饰一般的价格程度。"}, {"text": "这次考试史上很简单。", "explanation": "这里应该用〈很简单〉，不加〈史上〉。史上表示有记录的历史范围，不能用来表示一般的难易程度。"}, {"text": "他史上很认真地工作。", "explanation": "这里应该用〈很认真〉，不加〈史上〉。史上不修饰一般的程度，描述工作态度应直接用“很认真”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场雪是史上很大的一场。", "corrected_sentence": "这场雪是史上最大的一场。", "error_description": "搭配错误：“史上”表示有史以来的纪录，需接最高级“最+形容词”，“很”表示一般程度，不能与之搭配，应说“史上最大的一场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次演出是史上很成功的一场。", "corrected_sentence": "这次演出是史上最成功的一场。", "error_description": "搭配错误：“史上”表示有史以来的纪录，需接最高级“最+形容词”，不能接“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
