INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有史以来；历史上。", "primary_collocate": null, "pronunciation": "shǐ shàng", "ipa": "ʂɨ˨˩˦ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "史上第一次有女孩当了校长。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的大雪，史上很少见。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "史上第一位女皇帝是武则天。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市史上有三次大火。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纪录，史上没有人破过。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家史上从没有输过球。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的雨，史上从来没有过。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校史上第一次有人考满分。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是史上第一个得奖的农民。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事史上没有记录，没人知道。", "target_word": "史上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有史以来；历史上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "史上", "is_correct": true, "explanation": "“史上”表示有史以来，与“第一次”搭配，指历史上的首次。"}, {"text": "书店", "is_correct": false, "explanation": "语义：“书店”不能有校长，句中的“女孩当了校长”与场所无关。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”是一餐食物，不能作为“当了校长”的主语。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“手机”不能与“第一次有女孩当了校长”搭配，此处语义不通。"}], "explanations": {"史上": "“史上”表示有史以来，与“第一次”搭配，指历史上的首次。", "书店": "语义：“书店”不能有校长，句中的“女孩当了校长”与场所无关。", "早饭": "语义：“早饭”是一餐食物，不能作为“当了校长”的主语。", "手机": "搭配：“手机”不能与“第一次有女孩当了校长”搭配，此处语义不通。"}, "sentence_index": 0, "correct_answer": "史上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我史上第一次去北京，特别兴奋。", "explanation": "这里应该用〈人生〉。史上指有史以来的历史范围，讲个人经历应说“人生”或“一生中”。"}, {"text": "我史上每天都早起。", "explanation": "这里应该用〈一向〉。史上不用于说个人的长期习惯，表示一贯的做法应说“一向”。"}, {"text": "我史上吃过最辣的菜是在四川。", "explanation": "这里应该用〈一生中〉。史上不用于个人的经历，讲自己吃过的东西应说“一生中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "史上", "is_correct": true, "explanation": "“史上”表示有史以来，与“从来没有过”搭配，说明这种大雨是历史上从未有过的。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”与“雨”没有关系，不能作为“从来没有过”的主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，与“这么大的雨”无法构成比较，句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“钥匙”不能作为“大雨”的比较主语，与句中的语境不搭。"}], "explanations": {"史上": "“史上”表示有史以来，与“从来没有过”搭配，说明这种大雨是历史上从未有过的。", "课本": "语义：“课本”与“雨”没有关系，不能作为“从来没有过”的主语。", "冰箱": "语义：“冰箱”是家电，与“这么大的雨”无法构成比较，句意不通。", "钥匙": "搭配：“钥匙”不能作为“大雨”的比较主语，与句中的语境不搭。"}, "sentence_index": 6, "correct_answer": "史上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他史上明天要出国。", "explanation": "这里应删去〈史上〉。“史上”指有史以来的历史，不能与将来的“明天”连用。"}, {"text": "我的手机史上在桌子上。", "explanation": "这里应删去〈史上〉。“史上”只指历史范围，不能用来描述眼前东西的位置。"}, {"text": "今天的温度史上是二十度。", "explanation": "这里应删去〈史上〉。句子说的是今天的具体温度，不是历史记录，不能用“史上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇史上有了一次大洪水。", "corrected_sentence": "这个小镇史上有过一次大洪水。", "error_description": "体标错误：表示历史上发生过某事要用“有过”，“有了”表示已经获得，不能表示经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟史上的从来没有人见过。", "corrected_sentence": "这种鸟史上从来没有人见过。", "error_description": "“史上”后加“的”后变成定语，句子不通；应去掉“的”，说“这种鸟史上从来没有人见过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
