INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "过一会儿再做，以后。", "primary_collocate": null, "pronunciation": "huí tóu", "ipa": "xuei̯˧˥ tʰou̯˧˥", "syllable_count": 2, "sentences": [{"text": "我现在有点忙，回头给你打电话。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先走吧，回头我再告诉你。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事回头再说吧。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "回头我把照片发给你。", "target_word": "回头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说回头请我们吃饭。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我先去开会，回头见。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "东西先放这儿，回头我来拿。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "回头有空，我们一起去看电影。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在没时间，回头我回你消息。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说回头给我买新书包。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "过一会儿再做，以后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fdbd29-1997-4230-a16c-4778c9f154ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚刚", "is_correct": false, "explanation": "体貌：刚刚表示刚发生，与“现在有点忙”要做的事时间不符。"}, {"text": "回头", "is_correct": true, "explanation": "正确：回头表示过一会儿、以后，与“现在有点忙”形成先后关系，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "语义：从来表示一向如此，不能用于此处一次性的打电话。"}, {"text": "早就", "is_correct": false, "explanation": "语义：早就指很久以前，与“现在有点忙”的时间矛盾。"}], "explanations": {"刚刚": "体貌：刚刚表示刚发生，与“现在有点忙”要做的事时间不符。", "回头": "正确：回头表示过一会儿、以后，与“现在有点忙”形成先后关系，符合句意。", "从来": "语义：从来表示一向如此，不能用于此处一次性的打电话。", "早就": "语义：早就指很久以前，与“现在有点忙”的时间矛盾。"}, "sentence_index": 0, "correct_answer": "回头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把回头放在桌子上。", "explanation": "这里应该用〈书〉。回头是副词或动词，不能作名词指书籍。"}, {"text": "妈妈做的回头很好吃。", "explanation": "这里应该用〈饺子〉。回头是副词或动词，不能指食物。"}, {"text": "我回头了一个秘密。", "explanation": "这里应该用〈发现〉。回头作副词，不能带''秘密''作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "体貌：已经表示动作已完成，与将来要做的安排矛盾。"}, {"text": "回头", "is_correct": true, "explanation": "正确：回头表示以后、过一会儿，与“先放这儿”形成先后关系，符合句意。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：曾经表示过去的经历，不能用于将来的安排。"}, {"text": "又", "is_correct": false, "explanation": "语义：又表示重复，与这里一次性的安排不符。"}], "explanations": {"已经": "体貌：已经表示动作已完成，与将来要做的安排矛盾。", "回头": "正确：回头表示以后、过一会儿，与“先放这儿”形成先后关系，符合句意。", "曾经": "体貌：曾经表示过去的经历，不能用于将来的安排。", "又": "语义：又表示重复，与这里一次性的安排不符。"}, "sentence_index": 6, "correct_answer": "回头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我回头了这家公司，工作很努力。", "explanation": "这里应该用〈进〉。回头不能带''公司''作宾语。"}, {"text": "回头的天气很好，我们去公园吧。", "explanation": "这里应该用〈今天〉。回头是副词，不能用''的''修饰名词''天气''。"}, {"text": "我回头了那本书，看完了。", "explanation": "这里应该用〈读〉。回头不能带''书''作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "回头了我们再一起去吃饭吧。", "corrected_sentence": "回头我们再一起去吃饭吧。", "error_description": "体貌错误：“回头”作副词表示以后，后面不能加“了”，应说“回头我们再一起去吃饭吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很回头我给你打电话。", "corrected_sentence": "回头我给你打电话。", "error_description": "修饰错误：“回头”是副词，不能被程度副词“很”修饰，应说“回头我给你打电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
