INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中宽阔、繁华的主要街道。", "primary_collocate": null, "pronunciation": "dà jiē", "ipa": "ta˥˩ tɕje˥˥", "syllable_count": 2, "sentences": [{"text": "这座城市最繁华的大街在市中心。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日里，大街上挂满了红灯笼。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大街两边有很多高楼和商店。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，大街上到处都是买东西的人。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大街很有名，很多游客来这里。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们逛了一下午大街，买了不少衣服。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大街上的店很大，东西也很贵。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开着车，慢慢走过那条大街。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年的大街上特别热闹。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的主要大街都在东边。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "大街小巷", "label": "复合"}], "register": "中性", "sense_fingerprint": "城市里宽阔繁华的主要街道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee3e7df-b1b0-4578-906e-2115242cea45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大街", "is_correct": true, "explanation": "“最繁华的大街”指城市里宽阔繁华的主要街道，在市中心符合句意。"}, {"text": "河", "is_correct": false, "explanation": "语义：河流一般不用“繁华”来形容，也不说位于市中心的繁华河流。"}, {"text": "山", "is_correct": false, "explanation": "语义：山一般不位于城市中心，也不会用“繁华”来形容。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“繁华”不修饰身体部位，“最繁华的手”不通。"}], "explanations": {"大街": "“最繁华的大街”指城市里宽阔繁华的主要街道，在市中心符合句意。", "河": "语义：河流一般不用“繁华”来形容，也不说位于市中心的繁华河流。", "山": "语义：山一般不位于城市中心，也不会用“繁华”来形容。", "手": "搭配：“繁华”不修饰身体部位，“最繁华的手”不通。"}, "sentence_index": 0, "correct_answer": "大街"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条大街很窄，只能走一个人。", "explanation": "这里应该用〈胡同〉。大街宽阔繁华，不能用来形容狭窄的小路。"}, {"text": "这条大街很大，可以遮住两个人。", "explanation": "这里应该用〈伞〉。大街是道路，不能用来遮挡，遮雨要用〈伞〉。"}, {"text": "这条大街是一所学校，很多学生在里面上课。", "explanation": "这里应该用〈校园〉。大街是道路，不能说它是学校，学习的地方应说〈校园〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大街", "is_correct": true, "explanation": "“大街上”指主要街道，店铺开在街上，符合“店很大，东西很贵”的句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：海上不会有店铺，句子说的是陆地上的街道。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：方位词“上”不能与“房间”搭配，应说“房间里”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包上不可能开店，“书包上的店”不合常理。"}], "explanations": {"大街": "“大街上”指主要街道，店铺开在街上，符合“店很大，东西很贵”的句意。", "大海": "语义：海上不会有店铺，句子说的是陆地上的街道。", "房间": "搭配：方位词“上”不能与“房间”搭配，应说“房间里”。", "书包": "语义：书包上不可能开店，“书包上的店”不合常理。"}, "sentence_index": 6, "correct_answer": "大街"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在大街洗澡，水很热。", "explanation": "这里应该用〈浴室〉。大街是露天的道路，不能用来洗澡，洗澡要去〈浴室〉。"}, {"text": "这条小大街很热闹。", "explanation": "这里应该用〈小街〉。大街指宽阔繁华的主要道路，不能说“小大街”，窄的道路应说〈小街〉。"}, {"text": "我把钥匙放在大街的抽屉里。", "explanation": "这里应该用〈桌子〉。大街是道路，不能有抽屉，放钥匙的抽屉应属于〈桌子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个大街晚上很热闹。", "corrected_sentence": "这条大街晚上很热闹。", "error_description": "量词错误：“大街”是道路，量词应用“条”，不能用“个”。正确说法是“这条大街”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把那个大街修好了。", "corrected_sentence": "工人们把那条大街修好了。", "error_description": "量词错误：“大街”是道路，量词应用“条”，不能用“个”。正确说法是“把那条大街修好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
