INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94257, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "完成时是说一件事已经做完了的一种说法。", "primary_collocate": null, "pronunciation": "wán chéng shí", "ipa": "wan˧˥ ʈʂʰəŋ˧˥ ʂʅ˧˥", "syllable_count": 3, "sentences": [{"text": "想说事情已经做完，就用完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我写作业的时候，常常用完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "完成时让人知道事情做完了。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用完成时说说今天做了什么。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇短文里有很多完成时的句子。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在练习完成时的说法。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用完成时回答这个问题。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不出这句话是不是完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友问我什么是完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业做完以后，我们复习了完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现在完成时", "label": "复合"}, {"form": "过去完成时", "label": "复合"}, {"form": "将来完成时", "label": "复合"}], "register": "书面", "sense_fingerprint": "说明一件事已经做完的语法说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19183218-f415-4446-bb2a-32d0501c4052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完成时", "is_correct": true, "explanation": "正确：“就用完成时”指用完成时这种说法，与句意相符。"}, {"text": "剪刀", "is_correct": false, "explanation": "语义：“剪刀”是剪东西的工具，与“事情做完”的说法无关，句意不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”用来定时响铃，不能用来表达事情做完的说法。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：“用”后接“拖鞋”不成搭配，而且与句中“表达事情做完”的意思不符。"}], "explanations": {"完成时": "正确：“就用完成时”指用完成时这种说法，与句意相符。", "剪刀": "语义：“剪刀”是剪东西的工具，与“事情做完”的说法无关，句意不通。", "闹钟": "语义：“闹钟”用来定时响铃，不能用来表达事情做完的说法。", "拖鞋": "搭配：“用”后接“拖鞋”不成搭配，而且与句中“表达事情做完”的意思不符。"}, "sentence_index": 0, "correct_answer": "完成时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们用完成时描述现在正在发生的事。", "explanation": "这里应该用〈进行时〉。描述正在进行的事要用进行时，完成时只用来说已经做完的事。"}, {"text": "书上讲了一只完成时。", "explanation": "这里应该用〈种〉。“完成时”是时态的类别，要用量词“种”；“只”用于动物等，不能用于时态。"}, {"text": "作文里用完成时写明天要去的地方。", "explanation": "这里应该用〈将来时〉。说明天的计划要用将来时，完成时说的是已经做完的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完成时", "is_correct": true, "explanation": "正确：“请你用完成时回答”指用这种语法说法来回答，句意通顺。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：“香蕉”是水果，不能用来回答问题，句意不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是遮雨的用具，不是回答问题的方式，句意不通。"}, {"text": "拍子", "is_correct": false, "explanation": "搭配：“用拍子回答”不成搭配，“拍子”不是回答问题的手段。"}], "explanations": {"完成时": "正确：“请你用完成时回答”指用这种语法说法来回答，句意通顺。", "香蕉": "语义：“香蕉”是水果，不能用来回答问题，句意不通。", "雨伞": "语义：“雨伞”是遮雨的用具，不是回答问题的方式，句意不通。", "拍子": "搭配：“用拍子回答”不成搭配，“拍子”不是回答问题的手段。"}, "sentence_index": 6, "correct_answer": "完成时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在书上找到一座完成时。", "explanation": "这里应该用〈种〉。“完成时”是时态的类别，要用量词“种”；“座”用于山、楼等，不能用于时态。"}, {"text": "我们学了完成时，就能说清楚还在进行的工作。", "explanation": "这里应该用〈进行时〉。说工作还在进行要用进行时，完成时表示已经做完。"}, {"text": "老师让我们用完成时描述每天都做的事。", "explanation": "这里应该用〈一般现在时〉。描述每天都做的事要用一般现在时，完成时说的是已经做完的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书上一共讲了三朵完成时。", "corrected_sentence": "书上一共讲了三种完成时。", "error_description": "错误：“三朵完成时”，应为“三种完成时”。完成时是时态的类别，应该用量词“种”；“朵”用于花，不能用于时态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "完成时表示事情正在进行，我刚开始学，还不太熟。", "corrected_sentence": "完成时表示事情已经做完，我刚开始学，还不太熟。", "error_description": "错误：“表示事情正在进行”，应为“表示事情已经做完”。完成时强调事情已经做完，不能用来说正在进行的事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
