INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "招是举起手向别人摇一摇，让他过来。", "primary_collocate": null, "pronunciation": "zhāo", "ipa": "ʈʂaʊ̯˥", "syllable_count": 1, "sentences": [{"text": "妈妈站在门口，向我招了招手。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他朝我招招手，让我快点过来。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师招着手说：“大家过来！”", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不敢过来，你对它招招手。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学在对面向我招了招手。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在河对岸招着手，叫我们过去。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朝他招了几下手，他没看见。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察朝司机招了招手，让他过来。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷对孙子招了招手，孙子跑过去了。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你招一招手，他就会过来的。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招招", "label": "重叠"}, {"form": "招了", "label": "体标"}, {"form": "招着", "label": "体标"}, {"form": "招手", "label": "复合"}], "register": "口语", "sense_fingerprint": "举手摇一摇，示意别人走过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19183218-f415-4446-bb2a-32d0501c4052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招”（zhāo，第一声）在这里指举手摇一摇，示意人过来。"}, {"text": "找", "is_correct": false, "explanation": "找（zhǎo，第三声）只改变声调，意思是寻找，不是示意人过来。"}, {"text": "抄", "is_correct": false, "explanation": "抄（chāo）声母由 zh 变为 ch，意思是抄写。"}, {"text": "烧", "is_correct": false, "explanation": "烧（shāo）声母由 zh 变为 sh，意思是燃烧。"}, {"text": "罩", "is_correct": false, "explanation": "罩（zhào，第四声）只改变声调，意思是遮盖。"}, {"text": "糟", "is_correct": false, "explanation": "糟（zāo）声母由 zh 变为 z，意思是糟糕。"}], "explanations": {"招": "正确：“招”（zhāo，第一声）在这里指举手摇一摇，示意人过来。", "找": "找（zhǎo，第三声）只改变声调，意思是寻找，不是示意人过来。", "抄": "抄（chāo）声母由 zh 变为 ch，意思是抄写。", "烧": "烧（shāo）声母由 zh 变为 sh，意思是燃烧。", "罩": "罩（zhào，第四声）只改变声调，意思是遮盖。", "糟": "糟（zāo）声母由 zh 变为 z，意思是糟糕。"}, "sentence_index": null, "correct_answer": "招"}, "level_3": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：这里的“招”表示用手势示意，“招了招手”是固定说法。"}, {"text": "挥", "is_correct": false, "explanation": "搭配：“挥”后面已有“招手”，“挥了招手”不成词，要说“挥了挥手”。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊”是出声叫人，“招手”是打手势，句中说的是手势，不是喊叫。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：“摇”可以说“摇手”，但“摇了招手”不成词，与“招手”搭配不通。"}], "explanations": {"招": "正确：这里的“招”表示用手势示意，“招了招手”是固定说法。", "挥": "搭配：“挥”后面已有“招手”，“挥了招手”不成词，要说“挥了挥手”。", "喊": "语义：“喊”是出声叫人，“招手”是打手势，句中说的是手势，不是喊叫。", "摇": "搭配：“摇”可以说“摇手”，但“摇了招手”不成词，与“招手”搭配不通。"}, "sentence_index": 0, "correct_answer": "招"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈朝我招了招手，让我别过去。", "explanation": "这里应该用〈摆〉。“摆手”表示让人走开，“招手”表示叫人过来，与“别过去”正好相反。"}, {"text": "他向我招手，表示拒绝。", "explanation": "这里应该用〈摇〉。“招手”表示叫人过来，表示拒绝要说“摇手”或“摆手”。"}, {"text": "老师朝我招了招头，让我过来。", "explanation": "这里应该用〈点〉。“招”是用手示意，不能用于头；用头示意要说“点头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招”（zhāo，第一声）在这里指举手摇一摇，示意人过来。"}, {"text": "周", "is_correct": false, "explanation": "周（zhōu，第一声）只改变韵母，意思是星期或周围。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo）声母由 zh 变为 ch，意思是超过。"}, {"text": "照", "is_correct": false, "explanation": "照（zhào，第四声）只改变声调，意思是照射或拍照。"}, {"text": "遭", "is_correct": false, "explanation": "遭（zāo）声母由 zh 变为 z，意思是遭遇。"}], "explanations": {"招": "正确：“招”（zhāo，第一声）在这里指举手摇一摇，示意人过来。", "周": "周（zhōu，第一声）只改变韵母，意思是星期或周围。", "超": "超（chāo）声母由 zh 变为 ch，意思是超过。", "照": "照（zhào，第四声）只改变声调，意思是照射或拍照。", "遭": "遭（zāo）声母由 zh 变为 z，意思是遭遇。"}, "sentence_index": null, "correct_answer": "招"}, "level_3": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：这里的“招”表示用手势示意，“招了几下手”指打过几次手势。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿夹，句中说的是打手势，不是咬人或咬东西。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是用刀分开，“切了几下手”说的不是手势，句意不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”一般用于球或脚能碰到的东西，“踢了几下手”不成搭配。"}], "explanations": {"招": "正确：这里的“招”表示用手势示意，“招了几下手”指打过几次手势。", "咬": "语义：“咬”是用牙齿夹，句中说的是打手势，不是咬人或咬东西。", "切": "语义：“切”是用刀分开，“切了几下手”说的不是手势，句意不通。", "踢": "搭配：“踢”一般用于球或脚能碰到的东西，“踢了几下手”不成搭配。"}, "sentence_index": 6, "correct_answer": "招"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师用手招了招远处的操场，让我们去那里。", "explanation": "这里应该用〈指〉。“招”是对人打手势叫人过来，指地方要用“指”。"}, {"text": "他朝我招了招眼，示意我别说话。", "explanation": "这里应该用〈眨〉。这一义项的“招”只指用手示意，不能用于眼睛；用眼睛示意要说“眨眼”。"}, {"text": "他朝我招了招脚，让我过去。", "explanation": "这里应该用〈抬〉。“招”只用于手，用脚示意要说“抬脚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服务员把我们招了招手。", "corrected_sentence": "服务员朝我们招了招手。", "error_description": "错误：“把我们”，应为“朝我们”。“招手”是打手势叫人，对象要用“朝”引出，不能用“把”把对方当成处置对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在窗口招了着手，叫我们进屋。", "corrected_sentence": "她在窗口招着手，叫我们进屋。", "error_description": "错误：“招了着手”，应为“招着手”。“了”表示完成，“着”表示持续，两者不能叠用；这里是持续的动作，只用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手势叫人来；招引。", "primary_collocate": null, "pronunciation": "zhāo", "ipa": "ʈʂaʊ̯˥", "syllable_count": 1, "sentences": [{"text": "老师在门口招了招手，我就走过去了。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路边招了一辆出租车。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甜甜的花香招来了很多蜜蜂。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户一直开着，会招蚊子进来。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样说话，会招人讨厌的。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着向远处的朋友招招手。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里亮着的灯招来了不少小虫子。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别乱说，小心招来麻烦。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板朝服务员招了招手，要结账。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的香味招了不少客人。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招招", "label": "重叠"}, {"form": "招了", "label": "体标"}, {"form": "招着", "label": "体标"}, {"form": "招来", "label": "复合"}, {"form": "招手", "label": "复合"}], "register": "口语", "sense_fingerprint": "用手势叫人过来，或招引、引来人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19183218-f415-4446-bb2a-32d0501c4052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招”（zhāo，第一声）指用手势叫人过来，或招引。"}, {"text": "找", "is_correct": false, "explanation": "找（zhǎo，第三声）与招只有声调不同，意思是寻找，不是叫人过来。"}, {"text": "照", "is_correct": false, "explanation": "照（zhào，第四声）与招只有声调不同，意思是照射或拍照。"}, {"text": "抄", "is_correct": false, "explanation": "抄（chāo）与招的声母不同：zh 换成 ch，意思是抄写。"}, {"text": "烧", "is_correct": false, "explanation": "烧（shāo）与招的声母不同：zh 换成 sh，意思是燃烧。"}, {"text": "糟", "is_correct": false, "explanation": "糟（zāo）与招的声母不同：zh 换成 z，意思是坏、乱。"}], "explanations": {"招": "正确：“招”（zhāo，第一声）指用手势叫人过来，或招引。", "找": "找（zhǎo，第三声）与招只有声调不同，意思是寻找，不是叫人过来。", "照": "照（zhào，第四声）与招只有声调不同，意思是照射或拍照。", "抄": "抄（chāo）与招的声母不同：zh 换成 ch，意思是抄写。", "烧": "烧（shāo）与招的声母不同：zh 换成 sh，意思是燃烧。", "糟": "糟（zāo）与招的声母不同：zh 换成 z，意思是坏、乱。"}, "sentence_index": null, "correct_answer": "招"}, "level_3": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招了招手”是固定说法，这里的“招”表示用手势叫人，只有“招”能填入空格。"}, {"text": "挥", "is_correct": false, "explanation": "搭配：“挥”后面已有“招手”，“挥了招手”不成词，句中不能这样说。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊”是大声叫，“招手”是打手势，句中说的是手势，不是喊叫。"}, {"text": "指", "is_correct": false, "explanation": "语义：“指”是用手指点，与“招手”不同，“指了招手”说不通。"}], "explanations": {"招": "正确：“招了招手”是固定说法，这里的“招”表示用手势叫人，只有“招”能填入空格。", "挥": "搭配：“挥”后面已有“招手”，“挥了招手”不成词，句中不能这样说。", "喊": "语义：“喊”是大声叫，“招手”是打手势，句中说的是手势，不是喊叫。", "指": "语义：“指”是用手指点，与“招手”不同，“指了招手”说不通。"}, "sentence_index": 0, "correct_answer": "招"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他朝我招了招手，让我快点走开。", "explanation": "这里应该用〈摆〉。“摆手”表示让人走开，“招手”表示叫人过来，与“让我快点走开”正好相反。"}, {"text": "老师在教室里招了我的名字。", "explanation": "这里应该用〈叫〉。“招”用于招手或招引人、虫、麻烦，不能用于呼唤名字；叫名字要用“叫”。"}, {"text": "老师今天招了我们的作业本，让大家交上来。", "explanation": "这里应该用〈收〉。“招”指招来人、虫或用手叫人，不能用于收作业；收作业要说“收”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招”（zhāo，第一声）在这里指招引，使人或虫子来到。"}, {"text": "周", "is_correct": false, "explanation": "周（zhōu，第一声）只改变韵母，意思是星期或周围。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo）与招的声母不同：zh 换成 ch，意思是超过。"}, {"text": "罩", "is_correct": false, "explanation": "罩（zhào，第四声）与招只有声调不同，意思是遮盖。"}, {"text": "遭", "is_correct": false, "explanation": "遭（zāo）与招的声母不同：zh 换成 z，意思是遭遇。"}], "explanations": {"招": "正确：“招”（zhāo，第一声）在这里指招引，使人或虫子来到。", "周": "周（zhōu，第一声）只改变韵母，意思是星期或周围。", "超": "超（chāo）与招的声母不同：zh 换成 ch，意思是超过。", "罩": "罩（zhào，第四声）与招只有声调不同，意思是遮盖。", "遭": "遭（zāo）与招的声母不同：zh 换成 z，意思是遭遇。"}, "sentence_index": null, "correct_answer": "招"}, "level_3": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招来”表示引来，灯光引来小虫子，只有“招”符合句意。"}, {"text": "驱", "is_correct": false, "explanation": "语义：“驱”是驱赶，与“灯招来虫子”的引来意思相反。"}, {"text": "逃", "is_correct": false, "explanation": "配价：“逃”是不及物动词，后面不能直接带“小虫子”作宾语。"}, {"text": "吓", "is_correct": false, "explanation": "语义：“吓”是使人害怕，灯光不会把小虫子吓来，句意不通。"}], "explanations": {"招": "正确：“招来”表示引来，灯光引来小虫子，只有“招”符合句意。", "驱": "语义：“驱”是驱赶，与“灯招来虫子”的引来意思相反。", "逃": "配价：“逃”是不及物动词，后面不能直接带“小虫子”作宾语。", "吓": "语义：“吓”是使人害怕，灯光不会把小虫子吓来，句意不通。"}, "sentence_index": 6, "correct_answer": "招"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我招了一杯茶，请王老师坐下。", "explanation": "这里应该用〈倒〉。“招”不能用于倒茶；倒茶要说“倒”。"}, {"text": "他朝我招了招头，表示不同意。", "explanation": "这里应该用〈摇〉。“摇头”表示否定或不同意，“招”只用于手，不能用于头。"}, {"text": "他在远处招了一把伞，让我们快点过来。", "explanation": "这里应该用〈举〉。“招”指用手势叫人或招引，不能用于伞；举起伞要说“举”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天晚上开着灯，会招去很多蚊子。", "corrected_sentence": "夏天晚上开着灯，会招来很多蚊子。", "error_description": "错误：“招去”，应为“招来”。“来”表示向说话人或灯所在的地方靠近，蚊子是飞过来的，不能用“去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在路口招了一条车去机场。", "corrected_sentence": "我们在路口招了一辆车去机场。", "error_description": "错误：“一条车”，应为“一辆车”。车的量词是“辆”，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拿起", "is_correct": true, "explanation": "反义：“拿起”是把东西握到手中，与“放下”把东西放到别处方向相反。"}, {"text": "跑", "is_correct": false, "explanation": "无关：“跑”指快速移动，与“放下”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "无关：“看”指用眼睛观察，与“放下”不构成反义。"}, {"text": "洗", "is_correct": false, "explanation": "无关：“洗”指用水去除污垢，与“放下”的动作没有反义关系。"}], "correct_answer": "拿起", "explanations": {"拿起": "反义：“拿起”是把东西握到手中，与“放下”把东西放到别处方向相反。", "跑": "无关：“跑”指快速移动，与“放下”没有反义关系。", "看": "无关：“看”指用眼睛观察，与“放下”不构成反义。", "洗": "无关：“洗”指用水去除污垢，与“放下”的动作没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拿起", "is_correct": true, "explanation": "反义：“拿起”是把东西握到手中，与“放下”把东西放到别处方向相反。"}, {"text": "唱", "is_correct": false, "explanation": "无关：“唱”指发出歌声，与“放下”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "无关：“写”指写字，与“放下”不构成反义。"}, {"text": "睡", "is_correct": false, "explanation": "无关：“睡”指闭眼休息，与“放下”没有对立关系。"}], "correct_answer": "拿起", "explanations": {"拿起": "反义：“拿起”是把东西握到手中，与“放下”把东西放到别处方向相反。", "唱": "无关：“唱”指发出歌声，与“放下”没有反义关系。", "写": "无关：“写”指写字，与“放下”不构成反义。", "睡": "无关：“睡”指闭眼休息，与“放下”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放下是把拿着的东西放到别的地方。", "primary_collocate": null, "pronunciation": "fàng xià", "ipa": "fɑŋ˥˩ ɕiɑ˥˩", "syllable_count": 2, "sentences": [{"text": "他把书包放下，坐到了椅子上。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把杯子放下，别拿着了。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈放下菜篮，去开门。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放下筷子，说自己吃饱了。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先把东西放下，再慢慢说。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟放下手里的玩具，跑出去玩。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师放下粉笔，转身看着大家。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手机放下，认真听课。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放下了行李，坐在床边休息。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放下报纸，喝了一口茶。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放下了", "label": "体标"}, {"form": "放不下", "label": "否定可能式"}, {"form": "放得下", "label": "可能式"}], "register": "中性", "sense_fingerprint": "把手里拿着的东西放到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19183218-f415-4446-bb2a-32d0501c4052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放下", "is_correct": true, "explanation": "放下：把拿着的书包放到别处，与“坐到了椅子上”前后衔接自然。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉、抛出，书包被扔掉就不能再带着坐下，与“放下”的放置义不同。"}, {"text": "举起", "is_correct": false, "explanation": "语义：“举起”是把东西向上抬着，书包被举着就很难再“坐到椅子上”，两个动作互相冲突。"}, {"text": "放进", "is_correct": false, "explanation": "配价：“放进”后要说明放进哪里，“把书包放进”缺少处所，句子不完整。"}], "explanations": {"放下": "放下：把拿着的书包放到别处，与“坐到了椅子上”前后衔接自然。", "扔": "语义：“扔”是丢掉、抛出，书包被扔掉就不能再带着坐下，与“放下”的放置义不同。", "举起": "语义：“举起”是把东西向上抬着，书包被举着就很难再“坐到椅子上”，两个动作互相冲突。", "放进": "配价：“放进”后要说明放进哪里，“把书包放进”缺少处所，句子不完整。"}, "sentence_index": 0, "correct_answer": "放下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部老电影在城里放下了三天，没有人去看。", "explanation": "这里应该用〈放映〉。放下指把拿着的东西放到别处，电影在影院播出要说放映。"}, {"text": "他放下门，走进了屋里。", "explanation": "这里应该用〈关上〉。放下指把拿着的东西放到别处，门要说关上。"}, {"text": "这家公司下个月要放下一款新手机。", "explanation": "这里应该用〈推出〉。放下指把拿着的东西放到别处，新产品上市要说推出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放下", "is_correct": true, "explanation": "放下：把手里的粉笔放到别处，与“转身看着大家”前后衔接自然。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，老师手里拿着粉笔，不会用“咬”来描述把粉笔放下的动作。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：“叠”多用于衣服、纸张等可以折叠的东西，粉笔不能叠。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”要说挂在哪里，“老师挂粉笔”缺少处所，句子不完整。"}], "explanations": {"放下": "放下：把手里的粉笔放到别处，与“转身看着大家”前后衔接自然。", "咬": "语义：“咬”指用牙齿夹住，老师手里拿着粉笔，不会用“咬”来描述把粉笔放下的动作。", "叠": "搭配：“叠”多用于衣服、纸张等可以折叠的东西，粉笔不能叠。", "挂": "配价：“挂”要说挂在哪里，“老师挂粉笔”缺少处所，句子不完整。"}, "sentence_index": 6, "correct_answer": "放下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放下一句狠话，转身就走了。", "explanation": "这里应该用〈撂下〉。放下指把具体的东西放到别处；“狠话”不能被放下，说完话就走要说撂下一句话。"}, {"text": "门卫检查了证件，就放下了那辆车，让它进了大门。", "explanation": "这里应该用〈放行〉。放下指把拿着的东西放到别处，允许车辆通过要说放行。"}, {"text": "她一句话也没说，只是放下了眼泪。", "explanation": "这里应该用〈流下〉。“放下”的对象是能拿在手里、放到别处的具体物品，眼泪要说流下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我放下手里的那只钥匙，去开了门。", "corrected_sentence": "我放下手里的那把钥匙，去开了门。", "error_description": "量词错误：钥匙应用“把”计量，不能用“只”；应说“那把钥匙”。“放下”本身没有错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把伞放下着，进屋来吧。", "corrected_sentence": "请把伞放下，进屋来吧。", "error_description": "“放下”后面不能再加“着”；“放下”已是完成的结果，应直接说“请把伞放下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
