INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把手里拿着的东西放在某处；卸下。", "primary_collocate": null, "pronunciation": "fàng xià", "ipa": "fɑŋ˥˩ ɕiɑ˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸放下背包，擦了擦头上的汗。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们放下肩上的箱子，休息一会儿。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了家门口，我放下了手里的袋子。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶放下手里的针线，站起来迎接我们。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把重重的行李放下吧，我们到了。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放下手里的电话，走出了办公室。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明放下书包，先去洗手。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机放下乘客的行李，就开车走了。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人放下担子，坐在路边喘气。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累了就放下手里的东西，歇一歇。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放下了", "label": "体标"}, {"form": "放不下", "label": "否定可能式"}, {"form": "放得下", "label": "可能式"}], "register": "中性", "sense_fingerprint": "把手里拿着或身上背着的东西放在某处，卸下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19183218-f415-4446-bb2a-32d0501c4052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放下", "is_correct": true, "explanation": "放下：把背着或拿着的背包放到别处，与“擦了擦头上的汗”前后衔接。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是用力掷落，与“擦了擦头上的汗”的平静动作不协调。"}, {"text": "推", "is_correct": false, "explanation": "搭配：“推”多用于推车、推门等，“推背包”不是常见搭配。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”指遗失，书包丢了就不在身上，与“擦了擦头上的汗”的语境不符。"}], "explanations": {"放下": "放下：把背着或拿着的背包放到别处，与“擦了擦头上的汗”前后衔接。", "摔": "语义：“摔”是用力掷落，与“擦了擦头上的汗”的平静动作不协调。", "推": "搭配：“推”多用于推车、推门等，“推背包”不是常见搭配。", "丢": "语义：“丢”指遗失，书包丢了就不在身上，与“擦了擦头上的汗”的语境不符。"}, "sentence_index": 0, "correct_answer": "放下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她放下了眼泪，什么也没说。", "explanation": "这里应该用〈流下〉。“放下”的对象是能拿在手里、放到别处的具体物品，眼泪不能这样处理，要说流下眼泪。"}, {"text": "剧团下个月要放下一场新戏。", "explanation": "这里应该用〈上演〉。放下指把拿着的东西放到别处，新戏开演要说上演。"}, {"text": "他放下脸，冷冷地说：‘你走吧。’", "explanation": "这里应该用〈沉下〉。放下指把拿着的东西放到别处，表情变得严肃要说沉下脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放下", "is_correct": true, "explanation": "放下：把手里的东西放到别处，与“你累了，歇一歇”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是把东西放进嘴里，与“小明放下书包，先去洗手”的意思完全不符。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：“叠”多用于衣服、纸张，“叠书包”不是常见搭配。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指把物体拆开，“拆书包”不是正常说法，与“先去洗手”也不衔接。"}], "explanations": {"放下": "放下：把手里的东西放到别处，与“你累了，歇一歇”的语境相符。", "吃": "语义：“吃”是把东西放进嘴里，与“小明放下书包，先去洗手”的意思完全不符。", "叠": "搭配：“叠”多用于衣服、纸张，“叠书包”不是常见搭配。", "拆": "搭配：“拆”指把物体拆开，“拆书包”不是正常说法，与“先去洗手”也不衔接。"}, "sentence_index": 6, "correct_answer": "放下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放下一句话，头也不回地走了。", "explanation": "这里应该用〈撂下〉。撂下一句话指说完就离开，“放下”只用于把具体的东西放到别处，不能搭配“话”。"}, {"text": "这场比赛被放下了一周。", "explanation": "这里应该用〈推迟〉。放下指把拿着的东西放到别处，比赛时间往后移要说推迟。"}, {"text": "他放下胆子，走上了舞台。", "explanation": "这里应该用〈放开〉。放下指把拿着的东西放到别处，“胆子”要说放开胆子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "后备箱太小，放下不这个箱子。", "corrected_sentence": "后备箱太小，放不下这个箱子。", "error_description": "表示“没有地方放”的可能补语否定形式是“放不下”，“不”要放在“下”之前；“放下不”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这本背包放下，先歇一会儿。", "corrected_sentence": "请把这个背包放下，先歇一会儿。", "error_description": "量词错误：“本”用于书册，背包不能用“本”计量；应说“这个背包”。“放下”本身没有错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利", "is_correct": true, "explanation": "“不利”与“有利”互为反义，指对人或事没有好处。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌美，与“有利”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”的反义是吵闹，与“有利”的好处义无关。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”描述态度，与“有利”没有反义关系。"}], "correct_answer": "不利", "explanations": {"不利": "“不利”与“有利”互为反义，指对人或事没有好处。", "漂亮": "“漂亮”形容外貌美，与“有利”没有反义关系。", "安静": "“安静”的反义是吵闹，与“有利”的好处义无关。", "认真": "“认真”描述态度，与“有利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利", "is_correct": true, "explanation": "“不利”与“有利”互为反义，指对人或事没有好处。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁程度，与“有利”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“有利”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情，与“有利”没有反义关系。"}], "correct_answer": "不利", "explanations": {"不利": "“不利”与“有利”互为反义，指对人或事没有好处。", "干净": "“干净”形容清洁程度，与“有利”没有反义关系。", "聪明": "“聪明”形容人的智力，与“有利”没有反义关系。", "高兴": "“高兴”形容心情，与“有利”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有利是对人有好处。", "primary_collocate": null, "pronunciation": "yǒu lì", "ipa": "joʊ˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "早睡早起对身体很有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个天气对农民有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动对健康有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做对大家都有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好汉语对你找工作有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安静的环境对学习有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同对我们很有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃早饭对孩子有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格下降对买房的人有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水对皮肤有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利于", "label": "复合"}], "register": "中性", "sense_fingerprint": "对人或事有好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有利", "is_correct": true, "explanation": "“有利”表示对人或事有好处，与“早睡早起对身体”的语境相符。"}, {"text": "有名", "is_correct": false, "explanation": "语义：“有名”说名气大，与“对身体”的好处无关，句意不通。"}, {"text": "有趣", "is_correct": false, "explanation": "搭配：“有趣”形容事物的趣味，不能用来修饰“身体”。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌，不能说“对身体很好看”。"}], "explanations": {"有利": "“有利”表示对人或事有好处，与“早睡早起对身体”的语境相符。", "有名": "语义：“有名”说名气大，与“对身体”的好处无关，句意不通。", "有趣": "搭配：“有趣”形容事物的趣味，不能用来修饰“身体”。", "好看": "搭配：“好看”形容外貌，不能说“对身体很好看”。"}, "sentence_index": 0, "correct_answer": "有利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很有利，我坐了一下午都不累。", "explanation": "这里应该用〈舒适〉。有利表示对人或事有好处，说椅子坐着是否舒适应用“舒适”，不能用“有利”。"}, {"text": "听到这个消息，他很有利。", "explanation": "这里应该用〈高兴〉。有利用于事情对某方有好处，不用来描述人的心情。"}, {"text": "这件衣服对我很有利。", "explanation": "这里应该用〈合身〉。有利说的是好处，衣服贴身的程度应说“合身”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有利", "is_correct": true, "explanation": "“有利”表示对人有好处，与“这份合同对我们”的语境相符。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌，合同不能用来形容“好看”。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“快乐”形容人的心情，合同不能快乐，句意不通。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”形容外观排列，与“对我们很”的好处义不相容。"}], "explanations": {"有利": "“有利”表示对人有好处，与“这份合同对我们”的语境相符。", "好看": "搭配：“好看”形容外貌，合同不能用来形容“好看”。", "快乐": "语义：“快乐”形容人的心情，合同不能快乐，句意不通。", "整齐": "语义：“整齐”形容外观排列，与“对我们很”的好处义不相容。"}, "sentence_index": 6, "correct_answer": "有利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有利地跑完了全程。", "explanation": "这里应该用〈快〉。有利表示对人或事有好处，修饰跑步的速度应说“快”，不能用“有利”。"}, {"text": "这首歌很有利，我每天都听。", "explanation": "这里应该用〈好听〉。有利用于事情对某方有好处，不用来评价歌曲的好坏。"}, {"text": "他的字写得很有利，老师都看得清。", "explanation": "这里应该用〈工整〉。有利表示对人或事有好处，评价字写得是否整齐应说“工整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样做有利大家的身心健康。", "corrected_sentence": "这样做有利于大家的身心健康。", "error_description": "搭配错误：“有利”后面带宾语要用“有利于”，“有利大家”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这样做对大家很的有利。", "corrected_sentence": "这样做对大家很有利。", "error_description": "结构错误：“很”与“有利”之间不能加“的”，应说“很有利”，“很的有利”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利", "is_correct": true, "explanation": "“不利”与“有利”互为反义，指情况对事情没有帮助。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容清晰程度，与“有利”没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”描述态度，与“有利”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌美，与“有利”没有反义关系。"}], "correct_answer": "不利", "explanations": {"不利": "“不利”与“有利”互为反义，指情况对事情没有帮助。", "清楚": "“清楚”形容清晰程度，与“有利”没有反义关系。", "认真": "“认真”描述态度，与“有利”没有反义关系。", "漂亮": "“漂亮”形容外貌美，与“有利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利", "is_correct": true, "explanation": "“不利”与“有利”互为反义，指情况对事情没有帮助。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”形容物体坚固，与“有利”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“有利”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“有利”没有反义关系。"}], "correct_answer": "不利", "explanations": {"不利": "“不利”与“有利”互为反义，指情况对事情没有帮助。", "结实": "“结实”形容物体坚固，与“有利”没有反义关系。", "聪明": "“聪明”形容人的智力，与“有利”没有反义关系。", "热情": "“热情”形容待人的态度，与“有利”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有好处，有帮助的。", "primary_collocate": null, "pronunciation": "yǒu lì", "ipa": "joʊ˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "这对你的工作有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的条件对我们很有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，风向对他们有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息对公司有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书对写作有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有利的位置让他先看到了球。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找一个有利的时间。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春雨对种地有利。", "target_word": "有利", "complexity_tier": "T3", "furigana": "chūn yǔ duì zhòng dì yǒu lì", "sentence_source": "generated"}, {"text": "每天复习对考试有利。", "target_word": "有利", "complexity_tier": "T3", "furigana": "měi tiān fù xí duì kǎo shì yǒu lì", "sentence_source": "generated"}, {"text": "他的经验对这次谈判有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利于", "label": "复合"}], "register": "中性", "sense_fingerprint": "条件或情况有帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76cb92b8-fe61-4f92-af7f-526ca82588e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有利", "is_correct": true, "explanation": "“有利”表示情况对事情有帮助，与“这对你的工作”的语境相符。"}, {"text": "有名", "is_correct": false, "explanation": "语义：“有名”说名气大，与“这对你的工作”的影响无关，句意不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不能用来评价“工作”的影响。"}, {"text": "认真", "is_correct": false, "explanation": "语义：“认真”形容态度，不能作为“这”对工作影响的评价。"}], "explanations": {"有利": "“有利”表示情况对事情有帮助，与“这对你的工作”的语境相符。", "有名": "语义：“有名”说名气大，与“这对你的工作”的影响无关，句意不通。", "漂亮": "搭配：“漂亮”形容外貌，不能用来评价“工作”的影响。", "认真": "语义：“认真”形容态度，不能作为“这”对工作影响的评价。"}, "sentence_index": 0, "correct_answer": "有利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她今天的样子很有利。", "explanation": "这里应该用〈漂亮〉。有利用于事情或条件带来的好处，不用来评价人的外貌。"}, {"text": "他有利地唱完了那首歌。", "explanation": "这里应该用〈动听〉。有利表示对人或事有好处，不用来修饰唱歌的效果，评价歌声应说“动听”。"}, {"text": "这支笔很有利，写字很快。", "explanation": "这里应该用〈好用〉。有利表示对人或事有好处，评价笔的好坏应说“好用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有利", "is_correct": true, "explanation": "“有利”表示情况有帮助，与“找一个……的时间”的语境相符。"}, {"text": "有名", "is_correct": false, "explanation": "语义：“有名”说名气大，不能用来修饰“时间”。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌，时间不能用“好看”来形容。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”形容排列，与“找一个……的时间”的语义不搭。"}], "explanations": {"有利": "“有利”表示情况有帮助，与“找一个……的时间”的语境相符。", "有名": "语义：“有名”说名气大，不能用来修饰“时间”。", "好看": "搭配：“好看”形容外貌，时间不能用“好看”来形容。", "整齐": "语义：“整齐”形容排列，与“找一个……的时间”的语义不搭。"}, "sentence_index": 6, "correct_answer": "有利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场雨让他的心情很有利。", "explanation": "这里应该用〈愉快〉。有利用于事情对某方有好处，不用来描述人的心情。"}, {"text": "这张床很有利，睡得很香。", "explanation": "这里应该用〈舒服〉。有利表示对人或事有好处，床躺着好不好应说“舒服”。"}, {"text": "我的弟弟很有利，每次考试都拿第一。", "explanation": "这里应该用〈优秀〉。有利表示事情对某方有好处，不用来评价人的成绩或能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个条件有利我们的谈判。", "corrected_sentence": "这个条件有利于我们的谈判。", "error_description": "搭配错误：“有利”后面带宾语要用“有利于”，“有利我们”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项政策创业很有利。", "corrected_sentence": "这项政策对创业很有利。", "error_description": "介词缺失：“有利”引出的对象要用介词“对”，应说“对创业很有利”，省略“对”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e627ad2e-831c-4b7a-9186-7c493aca9238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
