INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "历史家是研究和写过去发生的事的人。", "primary_collocate": null, "pronunciation": "lì shǐ jiā", "ipa": "li˥˩ ʂɻ̩˨˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "他想长大以后当历史家。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位历史家写了很多书。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史家常常去图书馆找旧资料。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸的朋友是一位历史家。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史家说，那件事发生在一百年前。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个历史家研究中国的古代生活。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的历史家要先看很多材料，再写文章。", "target_word": "历史家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认识一位很有名的历史家。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位历史家今天要来我们学校讲话。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史家把旧信件里的故事写成了书。", "target_word": "历史家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "研究并写下过去发生的事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5159ab8-5210-402a-9e8c-41ff5dea1a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史家", "is_correct": true, "explanation": "历史家：研究和记录过去事情的人，符合“长大以后当”的句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能“长大以后当”它。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“当”后面要接职业或身份，“咖啡”不是职业。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不会“长大以后当”某种职业。"}], "explanations": {"历史家": "历史家：研究和记录过去事情的人，符合“长大以后当”的句意。", "石头": "语义：石头不是人，不能“长大以后当”它。", "咖啡": "搭配：“当”后面要接职业或身份，“咖啡”不是职业。", "河流": "语义：河流是自然景物，不会“长大以后当”某种职业。"}, "sentence_index": 0, "correct_answer": "历史家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位历史家每天在电视上报道今天的新闻。", "explanation": "这里应该用〈记者〉。历史家研究和写过去发生的事，报道今天的新闻是记者的工作。"}, {"text": "这位历史家预测了明年的经济形势。", "explanation": "这里应该用〈经济学家〉。历史家研究的是过去的事，预测明年的经济形势是经济学家的工作。"}, {"text": "这位历史家每天都预报明天的天气。", "explanation": "这里应该用〈天气预报员〉。历史家研究的是过去的事，不预报明天的天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史家", "is_correct": true, "explanation": "历史家：先看材料再写文章的研究者，符合句意。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作不需要看材料写文章，句中要的是研究者。"}, {"text": "木匠", "is_correct": false, "explanation": "语义：木匠做的是木工活，与先看材料再写文章的句意不符。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：“写文章”的主语多是作者或研究者，一般不说“歌手写文章”。"}], "explanations": {"历史家": "历史家：先看材料再写文章的研究者，符合句意。", "厨师": "语义：厨师的工作不需要看材料写文章，句中要的是研究者。", "木匠": "语义：木匠做的是木工活，与先看材料再写文章的句意不符。", "歌手": "搭配：“写文章”的主语多是作者或研究者，一般不说“歌手写文章”。"}, "sentence_index": 6, "correct_answer": "历史家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位历史家研究化学反应。", "explanation": "这里应该用〈化学家〉。历史家研究和写过去发生的事，不研究化学反应。"}, {"text": "这位历史家给病人治病。", "explanation": "这里应该用〈医生〉。历史家研究历史，不给病人治病。"}, {"text": "这位历史家设计了一座大桥。", "explanation": "这里应该用〈工程师〉。历史家研究历史，不负责设计大桥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多历史家们都在研究这个问题。", "corrected_sentence": "很多历史家都在研究这个问题。", "error_description": "错误：“很多历史家们”。正确：“很多历史家”。“很多”已经表示复数，名词后面不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位很有名历史家正在写一本新书。", "corrected_sentence": "那位很有名的历史家正在写一本新书。", "error_description": "错误：“很有名历史家”，漏掉了“的”。正确：“很有名的历史家”。“很有名”修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平淡", "is_correct": true, "explanation": "反义：“平淡”指缺少起伏和情趣，与“浪漫”让人觉得美好温暖的情调相对。"}, {"text": "高", "is_correct": false, "explanation": "无关：“高”指高度，与“浪漫”没有反义关系。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”指不软，与“浪漫”没有对立关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”指形状，与“浪漫”没有反义关系。"}], "correct_answer": "平淡", "explanations": {"平淡": "反义：“平淡”指缺少起伏和情趣，与“浪漫”让人觉得美好温暖的情调相对。", "高": "无关：“高”指高度，与“浪漫”没有反义关系。", "硬": "无关：“硬”指不软，与“浪漫”没有对立关系。", "圆": "无关：“圆”指形状，与“浪漫”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平淡", "is_correct": true, "explanation": "反义：“平淡”指缺少起伏和情趣，与“浪漫”让人觉得美好温暖的情调相对。"}, {"text": "大", "is_correct": false, "explanation": "无关：“大”指体积或范围，与“浪漫”没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "无关：“深”指距离表面远或程度高，与“浪漫”没有对立关系。"}, {"text": "厚", "is_correct": false, "explanation": "无关：“厚”指两个表面之间距离大，与“浪漫”没有反义关系。"}], "correct_answer": "平淡", "explanations": {"平淡": "反义：“平淡”指缺少起伏和情趣，与“浪漫”让人觉得美好温暖的情调相对。", "大": "无关：“大”指体积或范围，与“浪漫”没有反义关系。", "深": "无关：“深”指距离表面远或程度高，与“浪漫”没有对立关系。", "厚": "无关：“厚”指两个表面之间距离大，与“浪漫”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "浪漫是让人觉得美好、温暖、像故事一样。", "primary_collocate": null, "pronunciation": "làng màn", "ipa": "laŋ˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "他给妻子准备了一个很浪漫的晚餐。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的日落让这次旅行变得很浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雪中散步，觉得特别浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烛光、音乐和玫瑰，气氛真浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢浪漫的爱情故事。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在星空下向女朋友求婚，多浪漫啊！", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的灯光很柔和，环境非常浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老两口手拉着手走路，真浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪的夜晚，小城看起来很浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情人节那天，他送给她一束玫瑰，很浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪漫主义", "label": "复合"}, {"form": "浪漫史", "label": "复合"}], "register": "通用", "sense_fingerprint": "让人觉得美好温暖的、像故事一样的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19183218-f415-4446-bb2a-32d0501c4052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪漫", "is_correct": true, "explanation": "浪漫：让人觉得美好、温暖，与给妻子准备晚餐的情境相符。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”表示庄重、不轻松，与为妻子准备温馨晚餐的情境不符。"}, {"text": "寒酸", "is_correct": false, "explanation": "语义：“寒酸”指简陋、不体面，与为妻子精心准备的浪漫晚餐相反。"}, {"text": "凄凉", "is_correct": false, "explanation": "语义：“凄凉”表示悲伤冷清，与给妻子准备晚餐的温暖氛围相反。"}], "explanations": {"浪漫": "浪漫：让人觉得美好、温暖，与给妻子准备晚餐的情境相符。", "严肃": "语义：“严肃”表示庄重、不轻松，与为妻子准备温馨晚餐的情境不符。", "寒酸": "语义：“寒酸”指简陋、不体面，与为妻子精心准备的浪漫晚餐相反。", "凄凉": "语义：“凄凉”表示悲伤冷清，与给妻子准备晚餐的温暖氛围相反。"}, "sentence_index": 0, "correct_answer": "浪漫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛只剩最后一分钟，场上的气氛真浪漫。", "explanation": "这里应该用〈紧张〉。浪漫指美好温暖的情调，比赛关头的气氛要说紧张。"}, {"text": "这份说明书写得很浪漫，每一步都很清楚。", "explanation": "这里应该用〈清晰〉。浪漫用于美好温暖的情调，文字的条理要说清晰。"}, {"text": "这间厨房很浪漫，地板亮得能照出人影。", "explanation": "这里应该用〈干净〉。浪漫指美好温暖的情调，卫生状况要说干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪漫", "is_correct": true, "explanation": "浪漫：营造美好温暖的氛围，与“灯光很柔和”相呼应。"}, {"text": "刺眼", "is_correct": false, "explanation": "语义：“刺眼”指光线强到晃眼，与“灯光很柔和”相矛盾。"}, {"text": "脏乱", "is_correct": false, "explanation": "语义：“脏乱”指不干净、杂乱，与“浪漫”的美好情调完全相反。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”多形容人的态度，不说“环境热情”。"}], "explanations": {"浪漫": "浪漫：营造美好温暖的氛围，与“灯光很柔和”相呼应。", "刺眼": "语义：“刺眼”指光线强到晃眼，与“灯光很柔和”相矛盾。", "脏乱": "语义：“脏乱”指不干净、杂乱，与“浪漫”的美好情调完全相反。", "热情": "搭配：“热情”多形容人的态度，不说“环境热情”。"}, "sentence_index": 6, "correct_answer": "浪漫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他讲的笑话很浪漫，逗得大家直笑。", "explanation": "这里应该用〈幽默〉。浪漫指美好温暖、带有恋爱情调，逗人发笑的笑话要说幽默。"}, {"text": "这份申请表填写起来很浪漫，要填十几页。", "explanation": "这里应该用〈繁琐〉。浪漫指美好温暖的情调，手续多要说繁琐。"}, {"text": "这次会议的气氛很浪漫，大家都在认真讨论。", "explanation": "这里应该用〈严肃〉。浪漫用于美好温暖的情调，会议场合的庄重气氛要说严肃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他浪漫的为妻子布置了房间。", "corrected_sentence": "他浪漫地为妻子布置了房间。", "error_description": "“浪漫”修饰动词“布置”，作状语要用“地”，不能用“的”；应说“浪漫地为妻子布置了房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把房间布置很浪漫。", "corrected_sentence": "他把房间布置得很浪漫。", "error_description": "“浪漫”作“布置”的结果补语，动词和补语之间要用“得”，不能省略；应说“布置得很浪漫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "反义：“现实”指不带想象色彩、贴近实际，与“浪漫”富有诗意、充满幻想相对。"}, {"text": "薄", "is_correct": false, "explanation": "无关：“薄”指厚度小，与“浪漫”没有反义关系。"}, {"text": "软", "is_correct": false, "explanation": "无关：“软”指容易变形，与“浪漫”没有对立关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”指形状，与“浪漫”没有反义关系。"}], "correct_answer": "现实", "explanations": {"现实": "反义：“现实”指不带想象色彩、贴近实际，与“浪漫”富有诗意、充满幻想相对。", "薄": "无关：“薄”指厚度小，与“浪漫”没有反义关系。", "软": "无关：“软”指容易变形，与“浪漫”没有对立关系。", "圆": "无关：“圆”指形状，与“浪漫”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
