INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "富有诗意，充满幻想和美好情趣。", "primary_collocate": null, "pronunciation": "làng màn", "ipa": "laŋ˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "这位诗人的想法非常浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个浪漫的人，常常写诗给朋友。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画很浪漫，充满了幻想。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用浪漫的语言描写山水。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的歌词很浪漫，像一首诗。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻时他很浪漫，梦想环游世界。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部小说有浪漫的色彩，也有幻想。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他浪漫地说，想在月亮上盖一座房子。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她天真又浪漫，常常对着云朵编故事。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个浪漫的画家，喜欢在月光下作画。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪漫主义", "label": "复合"}, {"form": "浪漫史", "label": "复合"}], "register": "通用", "sense_fingerprint": "富有诗意、充满幻想的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19183218-f415-4446-bb2a-32d0501c4052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪漫", "is_correct": true, "explanation": "浪漫：富有诗意、充满幻想，与“诗人的想法”相符。"}, {"text": "粗俗", "is_correct": false, "explanation": "语义：“粗俗”指庸俗粗鲁，与诗人富有诗意的想法正好相反。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：“呆板”指死板、缺少变化，与充满幻想的想法不符。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”指单调乏味、缺少想象，与“诗人的想法”形成矛盾。"}], "explanations": {"浪漫": "浪漫：富有诗意、充满幻想，与“诗人的想法”相符。", "粗俗": "语义：“粗俗”指庸俗粗鲁，与诗人富有诗意的想法正好相反。", "呆板": "语义：“呆板”指死板、缺少变化，与充满幻想的想法不符。", "枯燥": "语义：“枯燥”指单调乏味、缺少想象，与“诗人的想法”形成矛盾。"}, "sentence_index": 0, "correct_answer": "浪漫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车站里人来人往，场面很浪漫。", "explanation": "这里应该用〈繁忙〉。浪漫用于诗意或情调，车站的人流要说繁忙。"}, {"text": "这份实验数据很浪漫，每个数字都经过核对。", "explanation": "这里应该用〈精确〉。浪漫形容富有诗意或幻想，描述数据要说精确。"}, {"text": "这把工具很浪漫，平时常用来拧螺丝。", "explanation": "这里应该用〈实用〉。浪漫用于诗意或情调，描述工具的功能要说实用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪漫", "is_correct": true, "explanation": "浪漫：富有诗意和想象的色彩，与“也有幻想”相呼应。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”多形容味道或言辞，不用来修饰“色彩”。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”表示缺乏感情，与“也有幻想”的美好想象相冲突。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”多形容质地、表面，不说“粗糙的色彩”。"}], "explanations": {"浪漫": "浪漫：富有诗意和想象的色彩，与“也有幻想”相呼应。", "辛辣": "搭配：“辛辣”多形容味道或言辞，不用来修饰“色彩”。", "冷漠": "语义：“冷漠”表示缺乏感情，与“也有幻想”的美好想象相冲突。", "粗糙": "搭配：“粗糙”多形容质地、表面，不说“粗糙的色彩”。"}, "sentence_index": 6, "correct_answer": "浪漫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子很浪漫，冷得直打哆嗦。", "explanation": "这里应该用〈寒冷〉。浪漫用于诗意或情调，天气冷要说寒冷。"}, {"text": "这份调查报告很浪漫，每一项结论都有依据。", "explanation": "这里应该用〈客观〉。浪漫用于诗意或幻想，描述报告的结论要说客观。"}, {"text": "这台机器很浪漫，运行速度非常快。", "explanation": "这里应该用〈高效〉。浪漫形容富有诗意的情调，描述机器的运行速度要说高效。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的画比他的很浪漫，充满了幻想。", "corrected_sentence": "她的画比他的浪漫，充满了幻想。", "error_description": "比较句错误：“比”字句中形容词前不能再用“很”；应说“比他的浪漫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜色降临，小镇慢慢变得浪漫得起来。", "corrected_sentence": "夜色降临，小镇慢慢变得浪漫起来。", "error_description": "重复的“得”：“变得”已带“得”，后面不能再加“得”；应说“变得浪漫起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94291, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生", "is_correct": true, "explanation": "生与“熟”相对，指食物没有煮熟，与“这个菜不熟”对应"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有脏污，与“熟”没有反义关系"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白，与“熟”没有反义关系"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足，与“熟”没有反义关系"}], "correct_answer": "生", "explanations": {"生": "生与“熟”相对，指食物没有煮熟，与“这个菜不熟”对应", "干净": "干净指没有脏污，与“熟”没有反义关系", "清楚": "清楚指明白，与“熟”没有反义关系", "明亮": "明亮形容光线充足，与“熟”没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94291, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陌生", "is_correct": true, "explanation": "陌生指对地方或人不了解，与“很熟”的“很了解”义相对"}, {"text": "嘈杂", "is_correct": false, "explanation": "嘈杂形容声音乱，与“熟”没有反义关系"}, {"text": "高兴", "is_correct": false, "explanation": "高兴指心情愉快，与“熟”没有反义关系"}, {"text": "便宜", "is_correct": false, "explanation": "便宜指价格低，与“熟”没有反义关系"}], "correct_answer": "陌生", "explanations": {"陌生": "陌生指对地方或人不了解，与“很熟”的“很了解”义相对", "嘈杂": "嘈杂形容声音乱，与“熟”没有反义关系", "高兴": "高兴指心情愉快，与“熟”没有反义关系", "便宜": "便宜指价格低，与“熟”没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94291, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "熟是吃的东西做好了，可以吃；也说很了解，不陌生。", "primary_collocate": null, "pronunciation": "shú", "ipa": "ʂu³⁵", "syllable_count": 1, "sentences": [{"text": "米饭还没熟，再等十分钟。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西红柿一炒就熟了。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对电脑很熟，常帮同学修理。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜不熟，吃了会不舒服。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在一个楼里，彼此很熟。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤熟了，快关火吧。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们刚认识，还不太熟。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对这份工作很熟，做得又快又好。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆切小一点，很快就熟。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方我很熟，我带你去。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟了", "label": "体标"}, {"form": "熟透", "label": "复合"}, {"form": "煮熟", "label": "复合"}], "register": "中性", "sense_fingerprint": "食物做好可吃；了解、不陌生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fdbd29-1997-4230-a16c-4778c9f154ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94291, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "熟", "is_correct": true, "explanation": "正确答案，shú（第二声），指食物做好可以吃，或对人事很了解"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shú（第二声）声调不同，意思是书"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shú（第二声）声调不同，意思是树木"}, {"text": "数", "is_correct": false, "explanation": "shù（第四声）与 shú（第二声）声调不同，意思是数字"}, {"text": "属", "is_correct": false, "explanation": "shǔ（第三声）与 shú（第二声）声调不同，意思是属于"}], "explanations": {"熟": "正确答案，shú（第二声），指食物做好可以吃，或对人事很了解", "书": "shū（第一声）与 shú（第二声）声调不同，意思是书", "树": "shù（第四声）与 shú（第二声）声调不同，意思是树木", "数": "shù（第四声）与 shú（第二声）声调不同，意思是数字", "属": "shǔ（第三声）与 shú（第二声）声调不同，意思是属于"}, "sentence_index": null, "correct_answer": "熟"}, "level_3": {"options": [{"text": "干净", "is_correct": false, "explanation": "搭配：“干净”说洁净，不能用来说米饭的烹煮状态"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”指光线明亮，不用来说米饭"}, {"text": "熟", "is_correct": true, "explanation": "熟指食物煮到可以吃的程度，与“再等十分钟”相符"}, {"text": "饱", "is_correct": false, "explanation": "语义：“饱”指吃足了，米饭还没做好时不能说“饱”"}], "explanations": {"干净": "搭配：“干净”说洁净，不能用来说米饭的烹煮状态", "亮": "搭配：“亮”指光线明亮，不用来说米饭", "熟": "熟指食物煮到可以吃的程度，与“再等十分钟”相符", "饱": "语义：“饱”指吃足了，米饭还没做好时不能说“饱”"}, "sentence_index": 0, "correct_answer": "熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人我很熟，但我想不起来他叫什么。", "explanation": "这里应该用〈面熟〉。熟指彼此相当了解，只见过、觉得眼熟要用“面熟”"}, {"text": "他年纪不大，但已经很熟了，说话很稳重。", "explanation": "这里应该用〈成熟〉。熟指食物做好或对人事很了解，形容人懂事稳重要用“成熟”"}, {"text": "这条鱼很熟，还带着血丝，别吃。", "explanation": "这里应该用〈生〉。熟指煮到可吃，与“还带着血丝”相矛盾，没煮透要用“生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94291, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "熟", "is_correct": true, "explanation": "正确答案，shú（第二声），指食物做好可以吃，或对人事很了解"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shú（第二声）声调不同，意思是叔叔"}, {"text": "暑", "is_correct": false, "explanation": "shǔ（第三声）与 shú（第二声）声调不同，意思是暑热"}, {"text": "竖", "is_correct": false, "explanation": "shù（第四声）与 shú（第二声）声调不同，意思是竖立"}, {"text": "鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shú（第二声）声调不同，意思是老鼠"}], "explanations": {"熟": "正确答案，shú（第二声），指食物做好可以吃，或对人事很了解", "叔": "shū（第一声）与 shú（第二声）声调不同，意思是叔叔", "暑": "shǔ（第三声）与 shú（第二声）声调不同，意思是暑热", "竖": "shù（第四声）与 shú（第二声）声调不同，意思是竖立", "鼠": "shǔ（第三声）与 shú（第二声）声调不同，意思是老鼠"}, "sentence_index": null, "correct_answer": "熟"}, "level_3": {"options": [{"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面人多声大，不能形容两人的交情"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”说温度，不能用来说人与人的关系"}, {"text": "熟", "is_correct": true, "explanation": "熟指彼此了解、不陌生，与“我们刚认识，还不太”相符"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来说两人之间的熟悉程度"}], "explanations": {"热闹": "语义：“热闹”形容场面人多声大，不能形容两人的交情", "烫": "搭配：“烫”说温度，不能用来说人与人的关系", "熟": "熟指彼此了解、不陌生，与“我们刚认识，还不太”相符", "甜": "搭配：“甜”说味道，不能用来说两人之间的熟悉程度"}, "sentence_index": 6, "correct_answer": "熟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块肉很熟，客人都说还不能吃。", "explanation": "这里应该用〈没熟〉。熟指煮到可吃，与“还不能吃”相矛盾，表示没煮好要用“没熟”"}, {"text": "吃了一大碗，我已经很熟了。", "explanation": "这里应该用〈饱〉。熟指食物煮好或对人事了解，不指吃饱，吃足了要用“饱”。"}, {"text": "这段舞他跳得很熟，可是一步也不会跳。", "explanation": "这里应该用〈生疏〉。熟指熟练、了解，与“一步也不会跳”相矛盾，应说“生疏”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汤已经熟了了，可以喝了。", "corrected_sentence": "汤已经熟了，可以喝了。", "error_description": "错误形式：“熟了了”；正确形式：“熟了”。句中的“了”只用一个，多加一个“了”是错误", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对这条路熟很，常常走。", "corrected_sentence": "我对这条路很熟，常常走。", "error_description": "错误形式：“熟很”；正确形式：“很熟”。程度副词“很”要放在形容词前面，不能放在后面", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
