INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94292, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "食物煮到可吃的程度；对人或事物很了解。", "primary_collocate": null, "pronunciation": "shú", "ipa": "ʂu³⁵", "syllable_count": 1, "sentences": [{"text": "肉煮了一个小时，已经熟了。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个鸡蛋还没熟，再煮一会儿。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块牛排还没熟，再煎一会儿。", "target_word": "熟", "complexity_tier": "T3", "furigana": "zhè kuài niúpái hái méi shú, zài jiān yīhuìr.", "sentence_source": "generated"}, {"text": "我对这个城市不太熟。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和老师很熟，常常一起吃饭。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路我很熟，不会走错。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饺子熟了，大家快来吃吧。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这些生字还不熟，读得很慢。", "target_word": "熟", "complexity_tier": "T3", "furigana": "tā duì zhèxiē shēngzì hái bù shú, dú de hěn màn.", "sentence_source": "generated"}, {"text": "红薯烤了半个小时才熟。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚搬来，对这里的人都不熟。", "target_word": "熟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟了", "label": "体标"}, {"form": "熟透", "label": "复合"}, {"form": "煮熟", "label": "复合"}], "register": "中性", "sense_fingerprint": "食物煮好；对人或地方很了解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fdbd29-1997-4230-a16c-4778c9f154ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94292, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "熟", "is_correct": true, "explanation": "正确答案，shú（第二声），指食物煮到可以吃，或对人和事物很了解"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shú（第二声）声调不同，意思是书"}, {"text": "暑", "is_correct": false, "explanation": "shǔ（第三声）与 shú（第二声）声调不同，意思是暑热"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shú（第二声）声调不同，意思是树木"}, {"text": "数", "is_correct": false, "explanation": "shù（第四声）与 shú（第二声）声调不同，意思是数字"}], "explanations": {"熟": "正确答案，shú（第二声），指食物煮到可以吃，或对人和事物很了解", "书": "shū（第一声）与 shú（第二声）声调不同，意思是书", "暑": "shǔ（第三声）与 shú（第二声）声调不同，意思是暑热", "树": "shù（第四声）与 shú（第二声）声调不同，意思是树木", "数": "shù（第四声）与 shú（第二声）声调不同，意思是数字"}, "sentence_index": null, "correct_answer": "熟"}, "level_3": {"options": [{"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”形容道理明白，不能用来说肉的状态"}, {"text": "忙", "is_correct": false, "explanation": "搭配：“忙”形容人的状态，不能用来说肉"}, {"text": "熟", "is_correct": true, "explanation": "熟指食物煮到可以吃的程度，与“煮了一个小时”相符"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指不熟悉，与“煮了一个小时”的食物状态矛盾"}], "explanations": {"清楚": "搭配：“清楚”形容道理明白，不能用来说肉的状态", "忙": "搭配：“忙”形容人的状态，不能用来说肉", "熟": "熟指食物煮到可以吃的程度，与“煮了一个小时”相符", "陌生": "语义：“陌生”指不熟悉，与“煮了一个小时”的食物状态矛盾"}, "sentence_index": 0, "correct_answer": "熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人对我很熟，但我连他的名字都不知道。", "explanation": "这里应该用〈面熟〉。熟指彼此相当了解，与“连他的名字都不知道”相矛盾；只见过、觉得眼熟要用“面熟”"}, {"text": "这块排骨很熟，咬一口还是生的。", "explanation": "这里应该用〈没熟〉。熟指煮到可吃，与“咬一口还是生的”相矛盾，没煮透要用“没熟”。"}, {"text": "这个孩子已经很熟了，做事很稳重。", "explanation": "这里应该用〈成熟〉。熟指食物煮好或对人事很了解，形容人懂事稳重要用“成熟”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94292, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "熟", "is_correct": true, "explanation": "正确答案，shú（第二声），指食物煮到可以吃，或对人和事物很了解"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shú（第二声）声调不同，意思是叔叔"}, {"text": "属", "is_correct": false, "explanation": "shǔ（第三声）与 shú（第二声）声调不同，意思是属于"}, {"text": "竖", "is_correct": false, "explanation": "shù（第四声）与 shú（第二声）声调不同，意思是竖立"}, {"text": "鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shú（第二声）声调不同，意思是老鼠"}], "explanations": {"熟": "正确答案，shú（第二声），指食物煮到可以吃，或对人和事物很了解", "叔": "shū（第一声）与 shú（第二声）声调不同，意思是叔叔", "属": "shǔ（第三声）与 shú（第二声）声调不同，意思是属于", "竖": "shù（第四声）与 shú（第二声）声调不同，意思是竖立", "鼠": "shǔ（第三声）与 shú（第二声）声调不同，意思是老鼠"}, "sentence_index": null, "correct_answer": "熟"}, "level_3": {"options": [{"text": "满", "is_correct": false, "explanation": "搭配：“满”说装满或充满，不用来说饺子做好了"}, {"text": "累", "is_correct": false, "explanation": "语义：“累”只用于人或动物，不能用来说饺子"}, {"text": "熟", "is_correct": true, "explanation": "熟指食物做到可以吃，与“大家快来吃吧”相符"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线或颜色，不能用来说饺子"}], "explanations": {"满": "搭配：“满”说装满或充满，不用来说饺子做好了", "累": "语义：“累”只用于人或动物，不能用来说饺子", "熟": "熟指食物做到可以吃，与“大家快来吃吧”相符", "亮": "搭配：“亮”形容光线或颜色，不能用来说饺子"}, "sentence_index": 6, "correct_answer": "熟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盘菜很熟，客人吃了一口就说还没做好。", "explanation": "这里应该用〈没熟〉。熟指煮到可吃，与“还没做好”相矛盾，没煮透要用“没熟”。"}, {"text": "这首歌我很熟，可是一句也唱不出来。", "explanation": "这里应该用〈陌生〉。熟指了解、熟悉，与“一句也唱不出来”相矛盾，不了解要用“陌生”。"}, {"text": "我对这里很熟，但是一条路都不认识。", "explanation": "这里应该用〈陌生〉。熟指对情况了解，与“一条路都不认识”相矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鸡蛋煮很熟。", "corrected_sentence": "鸡蛋煮得很熟。", "error_description": "错误形式：“煮很熟”；正确形式：“煮得很熟”。“熟”作补语时要用“得”连接，不能省略", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面没还熟呢，再等等。", "corrected_sentence": "面还没熟呢，再等等。", "error_description": "错误形式：“没还熟”；正确形式：“还没熟”。“还没”是固定搭配，不能说成“没还”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
