INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种大型猛兽，雄性颈部有长鬃毛，生活在非洲和印度。", "primary_collocate": null, "pronunciation": "shī zi", "ipa": "ʂɻ̩⁵⁵ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "非洲草原上有很多狮子。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雄性狮子的脖子上有长鬃毛。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说印度也有野生的狮子。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去非洲旅行，拍到了狮子的照片。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狮子是生活在草原上的大型猛兽。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狮子一天要睡很长时间。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一群狮子在草地上追着一只斑马。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在印度的森林里，狮子很少见。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老狮子老了，跑不快，抓不到吃的。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里，几只小狮子正在玩。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "头", "label": "量词"}, {"form": "狮子座", "label": "复合"}, {"form": "獅子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生活在非洲和印度的大型猛兽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 鬃 (Zipf 2.43)']::text[], '91fdbd29-1997-4230-a16c-4778c9f154ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94296, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "狮子", "is_correct": true, "explanation": "正确答案。狮子是一种生活在草原上的大型猛兽。"}, {"text": "石子", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，石子指小石头，不是猛兽。"}, {"text": "柿子", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，柿子是一种水果。"}, {"text": "十字", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，第二个音节 zì 也变了声调，十字指交叉的形状。"}], "explanations": {"狮子": "正确答案。狮子是一种生活在草原上的大型猛兽。", "石子": "shí（第二声）与 shī（第一声）声调不同，石子指小石头，不是猛兽。", "柿子": "shì（第四声）与 shī（第一声）声调不同，柿子是一种水果。", "十字": "shí（第二声）与 shī（第一声）声调不同，第二个音节 zì 也变了声调，十字指交叉的形状。"}, "sentence_index": null, "correct_answer": "狮子"}, "level_3": {"options": [{"text": "狮子", "is_correct": true, "explanation": "正确。狮子是非洲草原上的大型猛兽，与“非洲草原上”的语境相合。"}, {"text": "企鹅", "is_correct": false, "explanation": "语义：企鹅生活在寒冷的南极一带，与非洲草原不符。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：草原上不会下雪，“很多雪花”与语境不符。"}, {"text": "海浪", "is_correct": false, "explanation": "搭配：“海浪”一般出现在海边，与草原不搭配。"}], "explanations": {"狮子": "正确。狮子是非洲草原上的大型猛兽，与“非洲草原上”的语境相合。", "企鹅": "语义：企鹅生活在寒冷的南极一带，与非洲草原不符。", "雪花": "语义：草原上不会下雪，“很多雪花”与语境不符。", "海浪": "搭配：“海浪”一般出现在海边，与草原不搭配。"}, "sentence_index": 0, "correct_answer": "狮子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去非洲旅行，拍到了一根狮子。", "explanation": "这里应该用〈只〉。“根”用于细长的东西，不用于狮子。"}, {"text": "他去非洲旅行，拍到了一块狮子。", "explanation": "这里应该用〈只〉。“块”用于成块的东西，不用于狮子。"}, {"text": "他去非洲旅行，拍到了一扇狮子。", "explanation": "这里应该用〈只〉。“扇”用于门窗等，不用于狮子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "狮子", "is_correct": true, "explanation": "正确。狮子是草原上的猛兽，会群体追捕斑马，与句意相合。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不会在草地上一群追捕斑马，句意不通。"}, {"text": "海豚", "is_correct": false, "explanation": "语义：海豚生活在水里，不会出现在草地上追斑马。"}, {"text": "小蚂蚁", "is_correct": false, "explanation": "体貌：蚂蚁个子很小，追不上也不会追捕一只斑马，与句意矛盾。"}], "explanations": {"狮子": "正确。狮子是草原上的猛兽，会群体追捕斑马，与句意相合。", "小鸟": "语义：小鸟不会在草地上一群追捕斑马，句意不通。", "海豚": "语义：海豚生活在水里，不会出现在草地上追斑马。", "小蚂蚁": "体貌：蚂蚁个子很小，追不上也不会追捕一只斑马，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "狮子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视里，一辆小狮子正在玩。", "explanation": "这里应该用〈只〉。“辆”用于车，不能用于动物狮子。"}, {"text": "我在森林里看见一棵狮子。", "explanation": "这里应该用〈只〉。“棵”用于树木等植物，不能用于动物狮子。"}, {"text": "春节时，人们在街上看见一间狮子。", "explanation": "这里应该用〈只〉。“间”用于房屋，不能用于动物狮子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草原上有三本狮子。", "corrected_sentence": "草原上有三只狮子。", "error_description": "错误形式：“三本狮子”。正确形式：“三只狮子”。“本”用于书籍，狮子是动物，量词应用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "非洲草原上有三条狮子。", "corrected_sentence": "非洲草原上有三只狮子。", "error_description": "错误形式：“三条狮子”。正确形式：“三只狮子”。“条”多用于狗、蛇等长条形的动物，狮子应用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
