INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94297, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产值是一个地方做出来的东西一共值多少钱。", "primary_collocate": null, "pronunciation": "chǎn zhí", "ipa": "ʈʂʰan˨˩˦ ʈʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这个镇的年产值是两千万元。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村种茶，一年产值有几百万。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们市的产值在全省排第三。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问：这个地方一年的产值是多少？", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个岛很小，产值不算高。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的产值比城市低很多。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全县的产值一年比一年高。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在算这个村一年的产值。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的花很多，产值也不低。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地方的产值高，人们的生活就好。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "產值", "label": "繁体"}, {"form": "总产值", "label": "复合"}, {"form": "工业产值", "label": "复合"}], "register": "书面", "sense_fingerprint": "产值：一个地方做出来的东西一共值多少钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f50a9-5433-433b-b644-a8f9691ff3f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产值", "is_correct": true, "explanation": "正确。产值指一个地方生产的东西的总价值，可以用钱数表示，与“这个镇的年”和“两千万元”相合。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口按人数计算，不能用元来表示。"}, {"text": "产量", "is_correct": false, "explanation": "语义：产量按数量计算，不用元表示，与“两千万元”不合。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：学费属于学生，不属于一个镇的年度数额。"}], "explanations": {"产值": "正确。产值指一个地方生产的东西的总价值，可以用钱数表示，与“这个镇的年”和“两千万元”相合。", "人口": "语义：人口按人数计算，不能用元来表示。", "产量": "语义：产量按数量计算，不用元表示，与“两千万元”不合。", "学费": "搭配：学费属于学生，不属于一个镇的年度数额。"}, "sentence_index": 0, "correct_answer": "产值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师问：你每个月的产值是多少？", "explanation": "这里应该用〈工资〉。产值指一个地方生产的东西的总价值，个人每月的钱款要说工资。"}, {"text": "老师问：这个村一年的产值是多少吨？", "explanation": "这里应该用〈产量〉。产值是钱数，按吨计算的要说产量。"}, {"text": "我去年的产值是五万元。", "explanation": "这里应该用〈收入〉。产值指一个地方生产的东西的总价值，个人的钱款要说收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产值", "is_correct": true, "explanation": "正确。产值可以逐年升高，与“全县的”和“一年比一年高”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色没有高低之分，不能说全县的颜色一年比一年高。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的温度，不能用来描述一个县逐年升高。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：脾气是性格特点，不能用于描述一个县。"}], "explanations": {"产值": "正确。产值可以逐年升高，与“全县的”和“一年比一年高”相合。", "颜色": "搭配：颜色没有高低之分，不能说全县的颜色一年比一年高。", "体温": "语义：体温指身体的温度，不能用来描述一个县逐年升高。", "脾气": "搭配：脾气是性格特点，不能用于描述一个县。"}, "sentence_index": 6, "correct_answer": "产值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店今年的产值增加了不少。", "explanation": "这里应该用〈营业额〉。产值指一个地方生产的东西的总价值，商店卖货的收入要说营业额。"}, {"text": "学校的产值很充足，老师就放心。", "explanation": "这里应该用〈经费〉。产值指一个地方生产东西的总价值，学校的钱款要说经费。"}, {"text": "这个菜的产值便宜，大家都买。", "explanation": "这里应该用〈价格〉。产值是一个地方一定时期生产的总价值，不说单个商品便宜或贵，单价要说价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年全镇的产值达到了两千万个。", "corrected_sentence": "今年全镇的产值达到了两千万元。", "error_description": "错误：产值是钱数，单位应是“元”，不能说“两千万个”。量词或单位要和产值相配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们村的产值是五万斤。", "corrected_sentence": "他们村的产值是五万元。", "error_description": "错误：产值是钱数，不能用“斤”计量，应说“五万元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
