INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以绘画为职业或擅长绘画的人。", "primary_collocate": null, "pronunciation": "huà jiā", "ipa": "xua⁵¹ tɕia⁵⁵", "syllable_count": 2, "sentences": [{"text": "他是一位有名的画家，画卖得很好。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠卖画生活，是个真正的画家。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家的画在世界上很有名。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多画家在这里开过画展。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是画家，但画得比画家还好。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家的作品在美术馆里放着，很多人去看。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位画家，工作就是画画和教学生。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个画家画马画得特别好，画里的马像活的。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位画家的画一张卖了十万块。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是画家，他的画室在城东。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "女画家", "label": "复合词"}, {"form": "画家村", "label": "复合词"}, {"form": "畫家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以绘画为职业或绘画水平很高的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bfe4bad-92c1-4f44-b603-5e8c3d54b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "画家", "is_correct": true, "explanation": "画家：以绘画为职业或擅长绘画的人。"}, {"text": "画架", "is_correct": false, "explanation": "huàjià（第四声）与 huàjiā（第一声）第二个音节声调不同，意思是画画用的支架。"}, {"text": "花架", "is_correct": false, "explanation": "huājià 与 huàjiā 第一个音节声调不同（第一声与第四声），第二个音节声调也不同，意思是供花草攀爬的架子。"}, {"text": "下家", "is_correct": false, "explanation": "xiàjiā 与 huàjiā 声母不同（x 与 h），声调相同，意思是下一个买主或接手的人。"}], "explanations": {"画家": "画家：以绘画为职业或擅长绘画的人。", "画架": "huàjià（第四声）与 huàjiā（第一声）第二个音节声调不同，意思是画画用的支架。", "花架": "huājià 与 huàjiā 第一个音节声调不同（第一声与第四声），第二个音节声调也不同，意思是供花草攀爬的架子。", "下家": "xiàjiā 与 huàjiā 声母不同（x 与 h），声调相同，意思是下一个买主或接手的人。"}, "sentence_index": null, "correct_answer": "画家"}, "level_3": {"options": [{"text": "画家", "is_correct": true, "explanation": "画家：以绘画为职业的人，与“画卖得很好”一致。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手以唱歌为业，卖的不是画。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师卖的是菜，不是画。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生还在学习，与“有名”和“画卖得很好”的描写不合。"}], "explanations": {"画家": "画家：以绘画为职业的人，与“画卖得很好”一致。", "歌手": "语义：歌手以唱歌为业，卖的不是画。", "厨师": "语义：厨师卖的是菜，不是画。", "学生": "语义：学生还在学习，与“有名”和“画卖得很好”的描写不合。"}, "sentence_index": 0, "correct_answer": "画家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都去画家跑步。", "explanation": "这里应该用〈操场〉。画家指人，不是跑步的地方，跑步要去〈操场〉。"}, {"text": "这里有一个很大的画家，每年都有很多人来参观。", "explanation": "这里应该用〈画廊〉。“画家”指人，展出作品的地方要用“画廊”。"}, {"text": "他擅长画家。", "explanation": "这里应该用〈美术〉。“画家”指人，不能作为擅长的技能，“擅长”后要用〈美术〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "画家", "is_correct": true, "explanation": "画家：以绘画为职业的人，与“工作就是画画”一致。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家以写作为业，不是画画，与“工作就是画画和教学生”不符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生的工作是看病治疗，与“画画”不符。"}, {"text": "乘客", "is_correct": false, "explanation": "配价：“乘客”是搭乘交通工具的人，不能作为“工作就是画画和教学生”的身份。"}], "explanations": {"画家": "画家：以绘画为职业的人，与“工作就是画画”一致。", "作家": "语义：作家以写作为业，不是画画，与“工作就是画画和教学生”不符。", "医生": "语义：医生的工作是看病治疗，与“画画”不符。", "乘客": "配价：“乘客”是搭乘交通工具的人，不能作为“工作就是画画和教学生”的身份。"}, "sentence_index": 6, "correct_answer": "画家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了很多画家。", "explanation": "这里应该用〈颜料〉。“画家”指人，买的是画材，应说〈颜料〉。"}, {"text": "他把一个画家放在桌上。", "explanation": "这里应该用〈花瓶〉。画家指人，不能像东西一样放在桌上，放在桌上的应是〈花瓶〉。"}, {"text": "展厅里挂满了画家。", "explanation": "这里应该用〈画〉。“画家”指人，挂在墙上的是作品，要用“画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时当过一只画家，后来教书。", "corrected_sentence": "他年轻时当过一位画家，后来教书。", "error_description": "量词“只”多用于动物，不用于数人。指人的画家应用量词“位”（或“个”），说“一位画家”，不能说“一只画家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她当了五年画家们，后来改教书。", "corrected_sentence": "她当了五年画家，后来改教书。", "error_description": "“们”表示复数，指一个人时不能用“画家们”，应说“画家”，即“当了五年画家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
