INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94301, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "真个是真的，一点也不假。", "primary_collocate": null, "pronunciation": "zhēn gè", "ipa": "ʈʂən˥ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这孩子真个聪明，一学就会。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的春天真个美极了。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他真个生气了，一句话也不说。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说她要走，大家真个难过。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天真个热得很。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说不去，后来真个没来。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人真个高兴，笑了一整天。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗面真个好吃，我再来一碗。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她真个累了，坐下就睡着了。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩真个好，从来不吵架。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "旧白话", "sense_fingerprint": "真的、实在，强调程度属实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19183218-f415-4446-bb2a-32d0501c4052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真个", "is_correct": true, "explanation": "“真个”是副词，表示确实、真的，修饰形容词“聪明”，强调程度。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不聪明”与后文“一学就会”的意思相反，句意不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“一学就会”说的稳定能力不符。"}, {"text": "拼命", "is_correct": false, "explanation": "搭配：“拼命”只修饰用力的动作，不能修饰“聪明”这样的性质。"}], "explanations": {"真个": "“真个”是副词，表示确实、真的，修饰形容词“聪明”，强调程度。", "不": "语义：“不聪明”与后文“一学就会”的意思相反，句意不通。", "偶尔": "语义：“偶尔”表示不经常，与“一学就会”说的稳定能力不符。", "拼命": "搭配：“拼命”只修饰用力的动作，不能修饰“聪明”这样的性质。"}, "sentence_index": 0, "correct_answer": "真个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生气真个了，一句话也不说。", "explanation": "〈真个〉是副词，须放在谓语之前，不能放在句末。"}, {"text": "听说她要走，大家难过真个。", "explanation": "〈真个〉是副词，须放在谓语之前，不能放在句末。"}, {"text": "山里的春天美真个极了。", "explanation": "〈真个〉是副词，须放在所修饰的形容词之前，“美真个极了”语序不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真个", "is_correct": true, "explanation": "“真个”是副词，表示确实，修饰形容词“高兴”，强调情绪属实。"}, {"text": "毫不", "is_correct": false, "explanation": "语义：“毫不高兴”与后文“笑了一整天”相矛盾，句意不通。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“笑了一整天”的意思冲突。"}, {"text": "使劲", "is_correct": false, "explanation": "搭配：“使劲”修饰用力的动作，不能修饰“高兴”这样的心理状态。"}], "explanations": {"真个": "“真个”是副词，表示确实，修饰形容词“高兴”，强调情绪属实。", "毫不": "语义：“毫不高兴”与后文“笑了一整天”相矛盾，句意不通。", "从不": "语义：“从不”表示从来没有，与“笑了一整天”的意思冲突。", "使劲": "搭配：“使劲”修饰用力的动作，不能修饰“高兴”这样的心理状态。"}, "sentence_index": 6, "correct_answer": "真个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩好真个，从来不吵架。", "explanation": "〈真个〉是副词，须放在谓语之前，不能放在句末。"}, {"text": "他们俩从来不吵架，好真个。", "explanation": "〈真个〉是副词，须放在所修饰的形容词之前，“好真个”语序不对。"}, {"text": "真个他们俩好，从来不吵架。", "explanation": "〈真个〉是副词，须在主语之后、谓语之前，不能放在主语前面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈真个很累了，我们别吵她。", "corrected_sentence": "妈妈真个累了，我们别吵她。", "error_description": "“真个”已表示程度，不能再加“很”；应说“真个累了”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的菜真个的好吃，大家都爱来。", "corrected_sentence": "这家店的菜真个好吃，大家都爱来。", "error_description": "“真个”是副词，后面直接接形容词，中间不能加“的”，应说“真个好吃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e24931e4-de2f-48f7-b960-e5aab1406c47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
