INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94313, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "胡是乱来，不好好做。", "primary_collocate": null, "pronunciation": "hú", "ipa": "xu˧˥", "syllable_count": 1, "sentences": [{"text": "考试时我不会，就胡写了几句。", "target_word": "胡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没学过画，只是胡画了几笔。", "target_word": "胡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别胡猜了，我们去问老师吧。", "target_word": "胡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他饿坏了，在路上胡吃了一些东西。", "target_word": "胡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不要胡买东西，钱不多了。", "target_word": "胡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题我是胡填的，不知道对不对。", "target_word": "胡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在纸上胡画了一大堆线。", "target_word": "胡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没看清楚就胡按，机器会坏的。", "target_word": "胡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不懂规矩，到处胡跑。", "target_word": "胡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事你别胡想了。", "target_word": "胡", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "胡：不认真、没道理地乱做某事（副词，放在动词前）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f50a9-5433-433b-b644-a8f9691ff3f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94313, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胡", "is_correct": true, "explanation": "胡（第二声）是要找的词，副词，表示不认真、乱做某事。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ（第三声）与 hú（第二声）声调不同，意思是老虎。"}, {"text": "户", "is_correct": false, "explanation": "hù（第四声）与 hú 声调不同，意思是门、住户。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hú 声调不同，意思是呼喊、呼吸。"}, {"text": "福", "is_correct": false, "explanation": "fú 与 hú 声母不同（f 与 h），意思是幸福。"}, {"text": "扶", "is_correct": false, "explanation": "fú 与 hú 声母不同（f 与 h），意思是搀扶。"}, {"text": "忽", "is_correct": false, "explanation": "hū（第一声）与 hú 声调不同，意思是忽然。"}], "explanations": {"胡": "胡（第二声）是要找的词，副词，表示不认真、乱做某事。", "虎": "hǔ（第三声）与 hú（第二声）声调不同，意思是老虎。", "户": "hù（第四声）与 hú 声调不同，意思是门、住户。", "呼": "hū（第一声）与 hú 声调不同，意思是呼喊、呼吸。", "福": "fú 与 hú 声母不同（f 与 h），意思是幸福。", "扶": "fú 与 hú 声母不同（f 与 h），意思是搀扶。", "忽": "hū（第一声）与 hú 声调不同，意思是忽然。"}, "sentence_index": null, "correct_answer": "胡"}, "level_3": {"options": [{"text": "胡", "is_correct": true, "explanation": "“胡”是副词，放在动词前表示乱做，与“我不会，就……写了几句”的语境相符。"}, {"text": "桌子", "is_correct": false, "explanation": "词性：名词“桌子”不能放在动词“写”前作状语，句子不通。"}, {"text": "彻底", "is_correct": false, "explanation": "搭配：“彻底”一般修饰改变、解决一类动作，不能说“彻底写了几句”。"}, {"text": "月亮", "is_correct": false, "explanation": "词性：名词“月亮”不能修饰动词“写”，句子不通。"}], "explanations": {"胡": "“胡”是副词，放在动词前表示乱做，与“我不会，就……写了几句”的语境相符。", "桌子": "词性：名词“桌子”不能放在动词“写”前作状语，句子不通。", "彻底": "搭配：“彻底”一般修饰改变、解决一类动作，不能说“彻底写了几句”。", "月亮": "词性：名词“月亮”不能修饰动词“写”，句子不通。"}, "sentence_index": 0, "correct_answer": "胡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们住在北京的一条胡同里。", "explanation": "这里的“胡”属于“胡同”一词，指小巷，与副词“胡”表示乱做、不认真的意思无关。"}, {"text": "他的胡子又白又长。", "explanation": "这里的“胡”属于“胡子”一词，指胡须，与表示乱做、不认真的副词“胡”无关。"}, {"text": "她胡向客人道歉，态度非常诚恳。", "explanation": "这里应该用〈认真〉。“胡”表示不认真、乱做，与“态度非常诚恳”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94313, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "胡", "is_correct": true, "explanation": "胡（第二声）是要找的词，副词，表示不认真、乱做某事。"}, {"text": "互", "is_correct": false, "explanation": "hù（第四声）与 hú 声调不同，意思是相互。"}, {"text": "乎", "is_correct": false, "explanation": "hū（第一声）与 hú 声调不同，意思是似乎、几乎。"}, {"text": "符", "is_correct": false, "explanation": "fú 与 hú 声母不同（f 与 h），意思是符号、符合。"}, {"text": "服", "is_correct": false, "explanation": "fú 与 hú 声母不同（f 与 h），意思是衣服、服从。"}, {"text": "护", "is_correct": false, "explanation": "hù（第四声）与 hú 声调不同，意思是保护。"}], "explanations": {"胡": "胡（第二声）是要找的词，副词，表示不认真、乱做某事。", "互": "hù（第四声）与 hú 声调不同，意思是相互。", "乎": "hū（第一声）与 hú 声调不同，意思是似乎、几乎。", "符": "fú 与 hú 声母不同（f 与 h），意思是符号、符合。", "服": "fú 与 hú 声母不同（f 与 h），意思是衣服、服从。", "护": "hù（第四声）与 hú 声调不同，意思是保护。"}, "sentence_index": null, "correct_answer": "胡"}, "level_3": {"options": [{"text": "胡", "is_correct": true, "explanation": "“胡”是副词，放在动词前表示乱做，符合“孩子在纸上……画了一大堆线”的语境。"}, {"text": "房子", "is_correct": false, "explanation": "词性：名词“房子”不能放在动词“画”前作状语，句子不通。"}, {"text": "书包", "is_correct": false, "explanation": "词性：名词“书包”不能修饰动词“画”，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "词性：名词“窗户”不能修饰动词“画”，句子不通。"}], "explanations": {"胡": "“胡”是副词，放在动词前表示乱做，符合“孩子在纸上……画了一大堆线”的语境。", "房子": "词性：名词“房子”不能放在动词“画”前作状语，句子不通。", "书包": "词性：名词“书包”不能修饰动词“画”，句子不通。", "窗户": "词性：名词“窗户”不能修饰动词“画”，句子不通。"}, "sentence_index": 6, "correct_answer": "胡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要买一些胡萝卜。", "explanation": "这里的“胡”属于“胡萝卜”一词，指一种蔬菜，与副词“胡”无关。"}, {"text": "胡老师今天生病了，没来上课。", "explanation": "这里的“胡”是姓氏，指人名，与副词“胡”表示乱做、不认真的意思无关，不能用来修饰动词。"}, {"text": "古时候有一支胡人的商队经过这座城。", "explanation": "这里的“胡”属于“胡人”一词，指古代北方的民族，与副词“胡”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他胡地答了几道题，结果全都错了。", "corrected_sentence": "他胡答了几道题，结果全都错了。", "error_description": "副词“胡”后面不加“地”，应说“胡答了几道题”。错误形式“胡地答”多加了“地”，不符合副词“胡”的用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吃胡了一大碗面，肚子疼了一晚上。", "corrected_sentence": "他胡吃了一大碗面，肚子疼了一晚上。", "error_description": "副词“胡”应放在动词前，说“胡吃了一大碗面”。错误形式“吃胡了”把“胡”放到动词之后当补语，不符合汉语语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
