INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "虎是一种很凶的大猫，身上有黑色的条纹。", "primary_collocate": null, "pronunciation": "hǔ", "ipa": "xu˨˩˦", "syllable_count": 1, "sentences": [{"text": "这只虎又大又凶。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "虎的身上有黑色的条纹。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在电视上看过虎。", "target_word": "虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只虎正躺着睡觉。", "target_word": "虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在笼子外看虎。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "虎会游泳，也会爬树。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "森林里有两只虎。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "饲养员每天给虎喂肉。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那只虎突然吼了一声，吓得他不敢动。", "target_word": "虎", "complexity_tier": "T3", "furigana": "nà zhī hǔ tūrán hǒu le yì shēng, xià de tā bù gǎn dòng", "sentence_source": "generated"}, {"text": "这只小虎刚出生一个月。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只虎", "label": "量词"}, {"form": "一头虎", "label": "量词"}], "register": "中性", "sense_fingerprint": "虎：很凶、身上有黑色条纹的大猫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f50a9-5433-433b-b644-a8f9691ff3f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94319, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虎", "is_correct": true, "explanation": "hǔ（第三声）是要找的词，意思是身上有黑色条纹、很凶的大猫。"}, {"text": "户", "is_correct": false, "explanation": "hù（第四声）与 hǔ 声调不同，意思是门、住户。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hǔ 声调不同，意思是呼喊。"}, {"text": "忽", "is_correct": false, "explanation": "hū（第一声）与 hǔ 声调不同，意思是忽然。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 hǔ 声母不同（f 与 h），意思是政府。"}, {"text": "腐", "is_correct": false, "explanation": "fǔ 与 hǔ 声母不同（f 与 h），意思是腐烂。"}], "explanations": {"虎": "hǔ（第三声）是要找的词，意思是身上有黑色条纹、很凶的大猫。", "户": "hù（第四声）与 hǔ 声调不同，意思是门、住户。", "呼": "hū（第一声）与 hǔ 声调不同，意思是呼喊。", "忽": "hū（第一声）与 hǔ 声调不同，意思是忽然。", "府": "fǔ（第三声）与 hǔ 声母不同（f 与 h），意思是政府。", "腐": "fǔ 与 hǔ 声母不同（f 与 h），意思是腐烂。"}, "sentence_index": null, "correct_answer": "虎"}, "level_3": {"options": [{"text": "虎", "is_correct": true, "explanation": "“虎”可以“又大又凶”，与“这只”搭配，符合句意。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋子可以大，但不会凶，与“又大又凶”的描述矛盾。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗可以大，但不会凶，与句意矛盾。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“凶”一般用来形容人或动物，不能用来形容“手”。"}], "explanations": {"虎": "“虎”可以“又大又凶”，与“这只”搭配，符合句意。", "鞋": "语义：鞋子可以大，但不会凶，与“又大又凶”的描述矛盾。", "碗": "语义：碗可以大，但不会凶，与句意矛盾。", "手": "搭配：“凶”一般用来形容人或动物，不能用来形容“手”。"}, "sentence_index": 0, "correct_answer": "虎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身材高大，虎背熊腰，力气很大。", "explanation": "这里的“虎”属于“虎背熊腰”一词，形容人身材强壮，与指猛兽的“虎”不是同一个意思。"}, {"text": "他用老虎钳把螺丝拧紧了。", "explanation": "这里的“虎”属于“老虎钳”一词，指一种工具，与指猛兽的“虎”不是同一个意思。"}, {"text": "他是我们队里的一员虎将，每场比赛都很拼。", "explanation": "这里的“虎”属于“虎将”一词，指勇猛的将领，与指猛兽的“虎”不是同一个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94319, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "虎", "is_correct": true, "explanation": "hǔ（第三声）是要找的词，意思是身上有黑色条纹、很凶的大猫。"}, {"text": "护", "is_correct": false, "explanation": "hù（第四声）与 hǔ 声调不同，意思是保护。"}, {"text": "乎", "is_correct": false, "explanation": "hū（第一声）与 hǔ 声调不同，意思是似乎。"}, {"text": "辅", "is_correct": false, "explanation": "fǔ 与 hǔ 声母不同（f 与 h），意思是辅助。"}, {"text": "斧", "is_correct": false, "explanation": "fǔ（第三声）与 hǔ 声母不同（f 与 h），意思是斧头。"}, {"text": "湖", "is_correct": false, "explanation": "hú（第二声）与 hǔ 声调不同，意思是湖泊。"}], "explanations": {"虎": "hǔ（第三声）是要找的词，意思是身上有黑色条纹、很凶的大猫。", "护": "hù（第四声）与 hǔ 声调不同，意思是保护。", "乎": "hū（第一声）与 hǔ 声调不同，意思是似乎。", "辅": "fǔ 与 hǔ 声母不同（f 与 h），意思是辅助。", "斧": "fǔ（第三声）与 hǔ 声母不同（f 与 h），意思是斧头。", "湖": "hú（第二声）与 hǔ 声调不同，意思是湖泊。"}, "sentence_index": null, "correct_answer": "虎"}, "level_3": {"options": [{"text": "虎", "is_correct": true, "explanation": "“虎”是名词，与“两只”搭配，指森林里的猛兽，符合语境。"}, {"text": "袜子", "is_correct": false, "explanation": "语义：森林里不会有“两只袜子”，与语境矛盾。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子不会出现在森林里，与语境矛盾。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：“两只耳朵”指身体部位，放在“森林里有”之后不合常理。"}], "explanations": {"虎": "“虎”是名词，与“两只”搭配，指森林里的猛兽，符合语境。", "袜子": "语义：森林里不会有“两只袜子”，与语境矛盾。", "杯子": "语义：杯子不会出现在森林里，与语境矛盾。", "耳朵": "搭配：“两只耳朵”指身体部位，放在“森林里有”之后不合常理。"}, "sentence_index": 6, "correct_answer": "虎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了查明真相，他决定深入虎穴。", "explanation": "这里的“虎”属于“虎穴”一词，比喻危险的地方，与指猛兽的“虎”不是同一个意思。"}, {"text": "他笑起来露出两颗可爱的虎牙。", "explanation": "这里的“虎”属于“虎牙”一词，指尖尖的牙齿，与指猛兽的“虎”不是同一个意思。"}, {"text": "他的手掌很大，虎口也很宽。", "explanation": "这里的“虎”属于“虎口”一词，指手上拇指与食指之间的部位，与指猛兽的“虎”不是同一个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条虎正在树下休息。", "corrected_sentence": "这只虎正在树下休息。", "error_description": "老虎的量词应用“只”或“头”，不能用“条”。错误形式“这条虎”应改为“这只虎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两只虎们在林子里玩耍。", "corrected_sentence": "两只虎在林子里玩耍。", "error_description": "“们”只用于指人的复数，不能与“两只”这类数量词一起用在动物名词后，应说“两只虎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
