INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种大型猛兽，毛黄色有黑色条纹，俗称老虎。", "primary_collocate": null, "pronunciation": "hǔ", "ipa": "xu˨˩˦", "syllable_count": 1, "sentences": [{"text": "动物园里有一只虎。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山里住着一只虎，它很凶。", "target_word": "虎", "complexity_tier": "T3", "furigana": "shān lǐ zhù zhe yì zhī hǔ, tā hěn xiōng", "sentence_source": "generated"}, {"text": "这只虎的身上有黑色的条纹。", "target_word": "虎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虎吃肉，不吃草。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那头虎在笼子里走来走去。", "target_word": "虎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在山上看见了一只虎。", "target_word": "虎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友很怕那只虎。", "target_word": "虎", "complexity_tier": "T3", "furigana": "xiǎo péngyou hěn pà nà zhī hǔ", "sentence_source": "generated"}, {"text": "森林里的虎一天能吃很多肉。", "target_word": "虎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员给虎送去了一块肉。", "target_word": "虎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虎在水边慢慢地喝水。", "target_word": "虎", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只虎", "label": "量词"}, {"form": "一头虎", "label": "量词"}], "register": "中性", "sense_fingerprint": "虎：黄色毛、黑色条纹的大型猛兽，即老虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f50a9-5433-433b-b644-a8f9691ff3f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94320, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虎", "is_correct": true, "explanation": "hǔ（第三声）是要找的词，意思是一种大型猛兽，即老虎。"}, {"text": "胡", "is_correct": false, "explanation": "hú（第二声）与 hǔ（第三声）声调不同，意思是乱做、胡须。"}, {"text": "户", "is_correct": false, "explanation": "hù（第四声）与 hǔ 声调不同，意思是门、住户。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hǔ 声调不同，意思是呼喊。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 hǔ 声母不同（f 与 h），意思是政府。"}, {"text": "腐", "is_correct": false, "explanation": "fǔ 与 hǔ 声母不同（f 与 h），意思是腐烂。"}, {"text": "忽", "is_correct": false, "explanation": "hū（第一声）与 hǔ 声调不同，意思是忽然。"}], "explanations": {"虎": "hǔ（第三声）是要找的词，意思是一种大型猛兽，即老虎。", "胡": "hú（第二声）与 hǔ（第三声）声调不同，意思是乱做、胡须。", "户": "hù（第四声）与 hǔ 声调不同，意思是门、住户。", "呼": "hū（第一声）与 hǔ 声调不同，意思是呼喊。", "府": "fǔ（第三声）与 hǔ 声母不同（f 与 h），意思是政府。", "腐": "fǔ 与 hǔ 声母不同（f 与 h），意思是腐烂。", "忽": "hū（第一声）与 hǔ 声调不同，意思是忽然。"}, "sentence_index": null, "correct_answer": "虎"}, "level_3": {"options": [{"text": "虎", "is_correct": true, "explanation": "“虎”是名词，与量词“一只”搭配，指动物园里的动物，符合语境。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：动物园里不会有一只杯子，与“动物园里”的语境不符。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗是餐具，不会出现在动物园，与语境矛盾。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“一只手”多指身体部位，放在“动物园里有”之后不合常理。"}], "explanations": {"虎": "“虎”是名词，与量词“一只”搭配，指动物园里的动物，符合语境。", "杯子": "语义：动物园里不会有一只杯子，与“动物园里”的语境不符。", "碗": "语义：碗是餐具，不会出现在动物园，与语境矛盾。", "手": "搭配：“一只手”多指身体部位，放在“动物园里有”之后不合常理。"}, "sentence_index": 0, "correct_answer": "虎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小男孩虎头虎脑的，很可爱。", "explanation": "这里的“虎”属于“虎头虎脑”一词，形容孩子憨厚壮实，与指猛兽的“虎”不是同一个意思。"}, {"text": "他的右手虎口被划破了一道口子。", "explanation": "这里的“虎”属于“虎口”一词，指手拇指与食指之间的部位，与指猛兽的“虎”不是同一个意思。"}, {"text": "他办事虎虎有生气，大家都很佩服。", "explanation": "这里的“虎”属于“虎虎有生气”一词，形容精神饱满，与指猛兽的“虎”不是同一个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94320, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "虎", "is_correct": true, "explanation": "hǔ（第三声）是要找的词，意思是老虎。"}, {"text": "湖", "is_correct": false, "explanation": "hú（第二声）与 hǔ 声调不同，意思是湖泊。"}, {"text": "护", "is_correct": false, "explanation": "hù（第四声）与 hǔ 声调不同，意思是保护。"}, {"text": "乎", "is_correct": false, "explanation": "hū（第一声）与 hǔ 声调不同，意思是似乎。"}, {"text": "斧", "is_correct": false, "explanation": "fǔ（第三声）与 hǔ 声母不同（f 与 h），意思是斧头。"}, {"text": "辅", "is_correct": false, "explanation": "fǔ 与 hǔ 声母不同（f 与 h），意思是辅助。"}], "explanations": {"虎": "hǔ（第三声）是要找的词，意思是老虎。", "湖": "hú（第二声）与 hǔ 声调不同，意思是湖泊。", "护": "hù（第四声）与 hǔ 声调不同，意思是保护。", "乎": "hū（第一声）与 hǔ 声调不同，意思是似乎。", "斧": "fǔ（第三声）与 hǔ 声母不同（f 与 h），意思是斧头。", "辅": "fǔ 与 hǔ 声母不同（f 与 h），意思是辅助。"}, "sentence_index": null, "correct_answer": "虎"}, "level_3": {"options": [{"text": "虎", "is_correct": true, "explanation": "“虎”是名词，与“那只”搭配，可以是让小朋友害怕的动物，符合语境。"}, {"text": "袜子", "is_correct": false, "explanation": "语义：袜子不会让小朋友感到害怕，与“很怕”的语境矛盾。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋子不是会让小朋友害怕的对象，句意不通。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：“耳朵”是身体部位，“很怕那只耳朵”搭配不当。"}], "explanations": {"虎": "“虎”是名词，与“那只”搭配，可以是让小朋友害怕的动物，符合语境。", "袜子": "语义：袜子不会让小朋友感到害怕，与“很怕”的语境矛盾。", "鞋": "语义：鞋子不是会让小朋友害怕的对象，句意不通。", "耳朵": "搭配：“耳朵”是身体部位，“很怕那只耳朵”搭配不当。"}, "sentence_index": 6, "correct_answer": "虎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他虎视眈眈地盯着那块蛋糕，想偷偷拿走。", "explanation": "这里的“虎”属于“虎视眈眈”一词，形容贪婪地盯着，与指猛兽的“虎”不是同一个意思。"}, {"text": "我们周末去虎门参观了博物馆。", "explanation": "这里的“虎”属于地名“虎门”，指广东的一个地方，与指猛兽的“虎”不是同一个意思。"}, {"text": "他虎背熊腰，一个人能扛起一整袋大米。", "explanation": "这里的“虎”属于“虎背熊腰”一词，形容身材魁梧强壮，与指猛兽的“虎”不是同一个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条虎在树林里慢慢地走。", "corrected_sentence": "那只虎在树林里慢慢地走。", "error_description": "老虎的量词应用“只”或“头”，不能用“条”。“条”用于蛇、鱼等细长的东西，错误形式“那条虎”应改为“那只虎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两只虎们在水边慢慢地喝水。", "corrected_sentence": "两只虎在水边慢慢地喝水。", "error_description": "“们”只用于指人的复数，不能加在动物名词“虎”后面，所以“虎们”不成立，应去掉“们”，说“两只虎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
