INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94321, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谈论是几个人在一起说某件事。", "primary_collocate": null, "pronunciation": "tán lùn", "ipa": "tʰan˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "同学们在教室里谈论明天的比赛。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们坐在一起谈论新电影。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围着桌子谈论周末的计划。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时，他们谈论着旅行的事。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长一起谈论孩子的学习。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们常在楼下谈论小区的新规定。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几个人正在谈论去哪儿过年。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们在咖啡馆谈论过这件事。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学们谈论起刚才的考试。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家人坐在一起谈论搬家的问题。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈论了", "label": "体标"}, {"form": "谈论着", "label": "体标"}, {"form": "谈论过", "label": "体标"}, {"form": "談論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "几个人聚在一起说某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de77f8f-f932-4d69-8d97-208873924bdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94321, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谈论", "is_correct": true, "explanation": "“谈论”指几个人在一起说某件事，与“同学们”“在教室里”“明天的比赛”的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能说“修理明天的比赛”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或物品，不能说“打扫明天的比赛”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱明天的比赛”。"}], "explanations": {"谈论": "“谈论”指几个人在一起说某件事，与“同学们”“在教室里”“明天的比赛”的语境相符。", "修理": "搭配：“修理”的对象是器物，不能说“修理明天的比赛”。", "打扫": "搭配：“打扫”的对象是场地或物品，不能说“打扫明天的比赛”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱明天的比赛”。"}, "sentence_index": 0, "correct_answer": "谈论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人在房间里谈论了很久。", "explanation": "这里应该用〈念叨〉。〈谈论〉要几个人一起说某件事，只有一个人说时应用〈念叨〉。"}, {"text": "我们谈论了一下午，结果谁都没有开口。", "explanation": "这里应该用〈沉默〉。〈谈论〉要几个人一起交换意见，谁都没开口就不能说〈谈论〉。"}, {"text": "爷爷给我们谈论了他小时候的故事。", "explanation": "这里应该用〈讲〉。〈谈论〉是大家互相交流，爷爷单方面讲故事应该用〈讲〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94321, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈论", "is_correct": true, "explanation": "“谈论”表示几个人一起说话，与“我们几个人”“正在”的语境相符。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能说“翻译去哪儿过年”。"}, {"text": "颁发", "is_correct": false, "explanation": "语义：“颁发”指授予奖状、证书，与“去哪儿过年”的打算不符。"}, {"text": "欢送", "is_correct": false, "explanation": "配价：“欢送”的宾语须是离开的人，不能说“欢送去哪儿过年”。"}], "explanations": {"谈论": "“谈论”表示几个人一起说话，与“我们几个人”“正在”的语境相符。", "翻译": "搭配：“翻译”的对象是语言或文字，不能说“翻译去哪儿过年”。", "颁发": "语义：“颁发”指授予奖状、证书，与“去哪儿过年”的打算不符。", "欢送": "配价：“欢送”的宾语须是离开的人，不能说“欢送去哪儿过年”。"}, "sentence_index": 6, "correct_answer": "谈论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校一声不响地谈论了全体家长。", "explanation": "这里应该用〈关注〉。〈谈论〉要说话交流，“一声不响”与之矛盾；只是关注家长，应说〈关注〉。"}, {"text": "我的猫跟我谈论了三个小时。", "explanation": "这里应该用〈玩〉。〈谈论〉的主语须是能说话的人，猫不能与人谈论，陪猫应说〈玩〉。"}, {"text": "他对着墙谈论了很久。", "explanation": "这里应该用〈自言自语〉。〈谈论〉要和别人交换看法，对着墙说话应说〈自言自语〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在食堂里谈论了着假期的安排。", "corrected_sentence": "他们在食堂里谈论着假期的安排。", "error_description": "“谈论”的体标错误：“了”与“着”不能同时出现，应说“谈论着”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个朋友在公园里谈论地过去的旅行。", "corrected_sentence": "几个朋友在公园里谈论过去的旅行。", "error_description": "“谈论”后多加了“地”：“谈论”是动词，后面不能加“地”，应说“谈论过去的旅行”，去掉“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
