INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到某地去接人；欢迎某事到来。", "primary_collocate": null, "pronunciation": "yíng jiē", "ipa": "iŋ˧˥ tɕje˥˥", "syllable_count": 2, "sentences": [{"text": "我去机场迎接爷爷。", "target_word": "迎接", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸开车去车站迎接客人。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师到门口迎接新同学。", "target_word": "迎接", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司派人去迎接外国朋友。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要迎接新的挑战。", "target_word": "迎接", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈在家做好饭，迎接下班回来的爸爸。", "target_word": "迎接", "complexity_tier": "T3", "furigana": "māma zài jiā zuò hǎo fàn, yíngjiē xiàbān huílái de bàba", "sentence_source": "generated"}, {"text": "同学们在校门口迎接过很多客人。", "target_word": "迎接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长亲自去机场迎接他们。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家勇敢地迎接生活的变化。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她站在车站迎接着远方的朋友。", "target_word": "迎接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎接了", "label": "体标（了）"}, {"form": "迎接过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "去某地接人，或欢迎事情到来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fdbd29-1997-4230-a16c-4778c9f154ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迎接", "is_correct": true, "explanation": "正确。“迎接”表示去某地接人，与“去机场”“爷爷”的语境相合。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指去看景点、展览等，不用于去机场看人。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物，不说搬运爷爷。"}, {"text": "检修", "is_correct": false, "explanation": "语义：“检修”是检查修理机器设备，不能用于人。"}], "explanations": {"迎接": "正确。“迎接”表示去某地接人，与“去机场”“爷爷”的语境相合。", "参观": "语义：“参观”指去看景点、展览等，不用于去机场看人。", "搬运": "搭配：“搬运”的对象是货物，不说搬运爷爷。", "检修": "语义：“检修”是检查修理机器设备，不能用于人。"}, "sentence_index": 0, "correct_answer": "迎接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去车站迎接远行的朋友。", "explanation": "这里应该用〈送行〉。迎接指去接来的人，远行的人要离开，应说送行。"}, {"text": "他迎接了一杯刚端来的热牛奶。", "explanation": "这里应该用〈接过〉。迎接只用于接人或事到来，不能用于接取物品。"}, {"text": "她总是迎接领导的心意。", "explanation": "这里是“迎合、讨好”的意思，“迎接”不表示迎合，只用于接人或事到来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎接", "is_correct": true, "explanation": "正确。“迎接”表示到校门口接客人，与“在校门口”“很多客人”的语境相合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器械、物品等，不说修理客人。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”多用于动物或幼儿，不用于客人。"}, {"text": "派遣", "is_correct": false, "explanation": "语义：“派遣”是派人去办事，客人不会被派遣，句意不通。"}], "explanations": {"迎接": "正确。“迎接”表示到校门口接客人，与“在校门口”“很多客人”的语境相合。", "修理": "搭配：“修理”的对象是器械、物品等，不说修理客人。", "喂养": "搭配：“喂养”多用于动物或幼儿，不用于客人。", "派遣": "语义：“派遣”是派人去办事，客人不会被派遣，句意不通。"}, "sentence_index": 6, "correct_answer": "迎接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人们在码头迎接出征的士兵。", "explanation": "这里应该用〈欢送〉。迎接指欢迎到来，出征的士兵要离开，应说欢送。"}, {"text": "我在街上迎接了一位老朋友。", "explanation": "这里是偶然碰到的意思，“迎接”不表示碰见。"}, {"text": "他迎接了飞来的石头。", "explanation": "这里是伸手接住东西的意思，“迎接”只用于接人或事到来，不表示接住物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在机场迎接远方的客人过。", "corrected_sentence": "我们在机场迎接远方的客人。", "error_description": "错误形式：“迎接远方的客人过”。正确形式：“迎接远方的客人”。“过”不能放在宾语之后，这句不需要体标，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师曾经在教室门口迎接着转学的同学。", "corrected_sentence": "老师曾经在教室门口迎接过转学的同学。", "error_description": "错误形式：“迎接着转学的同学”。正确形式：“迎接过转学的同学”。“着”表示持续进行，与“曾经”所指的经历不合，应用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
