INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "间或是偶尔会这样，不是常常这样。", "primary_collocate": null, "pronunciation": "jiàn huò", "ipa": "tɕjɛn⁵¹ xuo⁵¹", "syllable_count": 2, "sentences": [{"text": "他平时很安静，间或讲个笑话。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空很蓝，间或飘过几朵白云。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里很静，间或传来几声咳嗽。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在家看书，间或出去走走。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上人不多，间或有一辆车开过。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她间或给我打个电话，说说最近的事。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在树下，间或看看手里的报纸。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得不大，间或夹着几声雷。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不爱喝酒，间或在朋友家喝一点。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议很长，他间或看一下手机。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "偶尔、不常发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fdbd29-1997-4230-a16c-4778c9f154ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与前半句“平时很安静”矛盾"}, {"text": "间或", "is_correct": true, "explanation": "间或表示偶尔才讲一次，与“平时很安静”的语境相符"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示每次都如此，与“平时很安静”矛盾"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，不用于说明平时的习惯"}], "explanations": {"一直": "语义：“一直”表示持续不断，与前半句“平时很安静”矛盾", "间或": "间或表示偶尔才讲一次，与“平时很安静”的语境相符", "总是": "语义：“总是”表示每次都如此，与“平时很安静”矛盾", "已经": "体貌：“已经”表示动作已经完成，不用于说明平时的习惯"}, "sentence_index": 0, "correct_answer": "间或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都间或晨跑。", "explanation": "这里应该用〈经常〉。间或表示偶尔、不常发生，与“每天都”的规律性相矛盾"}, {"text": "这一周他间或每天都准时下班，从未迟到。", "explanation": "这里应该用〈总是〉。间或表示偶尔，与“每天都”和“从未迟到”的每次如此相矛盾"}, {"text": "他从早到晚间或工作。", "explanation": "这里应该用〈一直〉。间或表示偶尔，与“从早到晚”的持续不断相冲突"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急切催促，与“坐在树下”的悠闲不合"}, {"text": "间或", "is_correct": true, "explanation": "间或表示偶尔看一下报纸，与“坐在树下”的悠闲相符"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”表示突然发生，与“坐在树下”的安适情境不合"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去的经历，不能描述眼下的动作"}], "explanations": {"赶紧": "语义：“赶紧”表示急切催促，与“坐在树下”的悠闲不合", "间或": "间或表示偶尔看一下报纸，与“坐在树下”的悠闲相符", "猛然": "语义：“猛然”表示突然发生，与“坐在树下”的安适情境不合", "曾经": "体貌：“曾经”指过去的经历，不能描述眼下的动作"}, "sentence_index": 6, "correct_answer": "间或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个周末都间或回老家看父母。", "explanation": "这里应该用〈时常〉。间或表示偶尔，与“每个周末都”的规律性相矛盾"}, {"text": "每逢节日，他都间或包饺子。", "explanation": "这里应该用〈常常〉。间或表示偶尔，与“每逢节日都”的规律性相矛盾"}, {"text": "他一天到晚间或玩手机。", "explanation": "这里应该用〈老是〉。间或表示偶尔，与“一天到晚”的持续不断相矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲间或了来这里看看。", "corrected_sentence": "我父亲间或来这里看看。", "error_description": "错误形式：“间或了来”；正确形式：“间或来”。间或是表示偶尔的副词，后面不能加“了”，直接接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他间或的去超市买东西。", "corrected_sentence": "他间或去超市买东西。", "error_description": "错误形式：“间或的去”；正确形式：“间或去”。间或是副词，后面不能加“的”，直接接动词", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '862a3733-920d-44f8-adf2-e2385ca91e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
