INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94341, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中期是一段时间里，中间的那一段。", "primary_collocate": null, "pronunciation": "zhōng qī", "ipa": "tʂʊŋ˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这个故事的中期最有意思。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学期开始、中期和结束，我们都有考试。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中期，他们一直在跑。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了中期，作业变得多了。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前期很容易，中期有点难，后期更难。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的中期有一个大变化。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学习中期有点累。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作做到中期，大家一起吃饭。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他前期很慢，中期开始快了。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中期的时候，老师会检查我们的作业。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中期考试", "label": "复合"}, {"form": "中期报告", "label": "复合"}], "register": "中性", "sense_fingerprint": "一段时间里中间的那一段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1cc6afb-d9ef-4bf0-9c1b-33171e53fc3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94341, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中期", "is_correct": true, "explanation": "中期 zhōngqī 指一段时间中间的那一段，是正确答案。"}, {"text": "周期", "is_correct": false, "explanation": "周期 zhōuqī 与中期 zhōngqī 第一个音节韵母不同（ou 与 ong），意思是周而复始的时间段。"}, {"text": "中气", "is_correct": false, "explanation": "中气 zhōngqì 与中期 zhōngqī 第二个音节声调不同（第四声与第一声），意思是体内的力量或声音的底气。"}, {"text": "中西", "is_correct": false, "explanation": "中西 zhōngxī 与中期 zhōngqī 第二个音节声母不同（x 与 q），意思是中国与西方。"}], "explanations": {"中期": "中期 zhōngqī 指一段时间中间的那一段，是正确答案。", "周期": "周期 zhōuqī 与中期 zhōngqī 第一个音节韵母不同（ou 与 ong），意思是周而复始的时间段。", "中气": "中气 zhōngqì 与中期 zhōngqī 第二个音节声调不同（第四声与第一声），意思是体内的力量或声音的底气。", "中西": "中西 zhōngxī 与中期 zhōngqī 第二个音节声母不同（x 与 q），意思是中国与西方。"}, "sentence_index": null, "correct_answer": "中期"}, "level_3": {"options": [{"text": "中期", "is_correct": true, "explanation": "“故事的中期”指故事的中间部分，与“最有意思”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：故事没有价格，不能说“故事的价格”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”只用于人或动物，不能用来说故事的体重。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：故事没有眼睛，不能说“故事的眼睛”。"}], "explanations": {"中期": "“故事的中期”指故事的中间部分，与“最有意思”相符。", "价格": "语义：故事没有价格，不能说“故事的价格”。", "体重": "语义：“体重”只用于人或动物，不能用来说故事的体重。", "眼睛": "搭配：故事没有眼睛，不能说“故事的眼睛”。"}, "sentence_index": 0, "correct_answer": "中期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的中期有一个坑。", "explanation": "这里应该用〈中间〉。中期指时间段中的中间阶段，不能指道路上的位置。"}, {"text": "他是我们班的中期，很努力。", "explanation": "这里应该用〈同学〉。中期表示时间阶段，不能用来指人。"}, {"text": "他的中期比我高一点。", "explanation": "这里应该用〈身高〉。中期不能用来说人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94341, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "中期", "is_correct": true, "explanation": "中期 zhōngqī 指一段时间中间的那一段，是正确答案。"}, {"text": "工期", "is_correct": false, "explanation": "工期 gōngqī 与中期 zhōngqī 第一个音节声母不同（g 与 zh），意思是工程的施工期限。"}, {"text": "中秋", "is_correct": false, "explanation": "中秋 zhōngqiū 与中期 zhōngqī 第二个音节韵母多了一个 u，意思是中秋节。"}, {"text": "中企", "is_correct": false, "explanation": "中企 zhōngqǐ 与中期 zhōngqī 第二个音节声调不同（第三声与第一声），是“中国企业”的简称。"}], "explanations": {"中期": "中期 zhōngqī 指一段时间中间的那一段，是正确答案。", "工期": "工期 gōngqī 与中期 zhōngqī 第一个音节声母不同（g 与 zh），意思是工程的施工期限。", "中秋": "中秋 zhōngqiū 与中期 zhōngqī 第二个音节韵母多了一个 u，意思是中秋节。", "中企": "中企 zhōngqǐ 与中期 zhōngqī 第二个音节声调不同（第三声与第一声），是“中国企业”的简称。"}, "sentence_index": null, "correct_answer": "中期"}, "level_3": {"options": [{"text": "中期", "is_correct": true, "explanation": "“学习中期”指学习过程的中间阶段，与“有点累”相符。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“学习”的对象不能是一个时刻，“学习中午”不成立。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“学习”不能以“座位”为对象，句子语境不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“学习”不接“眼镜”这类物件。"}], "explanations": {"中期": "“学习中期”指学习过程的中间阶段，与“有点累”相符。", "中午": "语义：“学习”的对象不能是一个时刻，“学习中午”不成立。", "座位": "语义：“学习”不能以“座位”为对象，句子语境不通。", "眼镜": "搭配：“学习”不接“眼镜”这类物件。"}, "sentence_index": 6, "correct_answer": "中期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的中期很甜。", "explanation": "这里应该用〈中间〉。中期指时间段，不能指蛋糕的中间部分。"}, {"text": "我每天中期都去跑步。", "explanation": "这里应该用〈傍晚〉。中期指较长时期的中段，不能指一天里的某个时刻。"}, {"text": "这是一个中期的苹果。", "explanation": "这里应该用〈中等〉。中期是时间概念，不能用来形容苹果的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在中期的开了一次会。", "corrected_sentence": "我们在中期开了一次会。", "error_description": "“在中期”是状语，后面直接接动词，不能加“的”，应说“在中期开了一次会”。写成“在中期的开”，多出了“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在中期的检查了我们的作业。", "corrected_sentence": "老师在中期检查了我们的作业。", "error_description": "“中期”后面多加了“的”，“中期的检查”变成了名词性短语，后面不能直接接“了”作谓语。应说“老师在中期检查了我们的作业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
