INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94342, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个时期的中间阶段。", "primary_collocate": null, "pronunciation": "zhōng qī", "ipa": "tʂʊŋ˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这个项目的中期检查在下个月。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中期，我们队落后了。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学习中期遇到了不少困难。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司中期的计划已经做好了。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧的中期很精彩。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划分前期、中期和后期。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了中期，学生的水平提高了很多。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作进入中期，大家都很忙。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在中期报告里写了新的想法。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的中期目标是开三家店。", "target_word": "中期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中期考试", "label": "复合"}, {"form": "中期报告", "label": "复合"}], "register": "中性", "sense_fingerprint": "某个时期的中间阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1cc6afb-d9ef-4bf0-9c1b-33171e53fc3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94342, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中期", "is_correct": true, "explanation": "中期 zhōngqī 指某个时期的中间阶段，是正确答案。"}, {"text": "周期", "is_correct": false, "explanation": "周期 zhōuqī 与中期 zhōngqī 第一个音节韵母不同（ou 与 ong），意思是周而复始的时间段。"}, {"text": "中气", "is_correct": false, "explanation": "中气 zhōngqì 与中期 zhōngqī 第二个音节声调不同（第四声与第一声），意思是体内的力量或声音的底气。"}, {"text": "中西", "is_correct": false, "explanation": "中西 zhōngxī 与中期 zhōngqī 第二个音节声母不同（x 与 q），意思是中国与西方。"}], "explanations": {"中期": "中期 zhōngqī 指某个时期的中间阶段，是正确答案。", "周期": "周期 zhōuqī 与中期 zhōngqī 第一个音节韵母不同（ou 与 ong），意思是周而复始的时间段。", "中气": "中气 zhōngqì 与中期 zhōngqī 第二个音节声调不同（第四声与第一声），意思是体内的力量或声音的底气。", "中西": "中西 zhōngxī 与中期 zhōngqī 第二个音节声母不同（x 与 q），意思是中国与西方。"}, "sentence_index": null, "correct_answer": "中期"}, "level_3": {"options": [{"text": "中期", "is_correct": true, "explanation": "中期检查指项目进行到中间阶段时的检查，与句中“下个月”不冲突。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去，与句中的“下个月”时间冲突。"}, {"text": "当天", "is_correct": false, "explanation": "语义：“当天”指同一天，与句中的“下个月”时间冲突。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛检查”指检查视力，项目不能做眼睛检查。"}], "explanations": {"中期": "中期检查指项目进行到中间阶段时的检查，与句中“下个月”不冲突。", "昨天": "语义：“昨天”指过去，与句中的“下个月”时间冲突。", "当天": "语义：“当天”指同一天，与句中的“下个月”时间冲突。", "眼睛": "搭配：“眼睛检查”指检查视力，项目不能做眼睛检查。"}, "sentence_index": 0, "correct_answer": "中期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的中期有一座桥。", "explanation": "这里应该用〈中间〉。中期指时间段中的中间阶段，不能指河流上的位置。"}, {"text": "我每天中期都喝一杯咖啡。", "explanation": "这里应该用〈中午〉。中期指较长时期的中段，不能指一天里的某个时刻。"}, {"text": "这是一个中期的苹果。", "explanation": "这里应该用〈中等〉。中期是时间概念，不能用来形容苹果的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94342, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "中期", "is_correct": true, "explanation": "中期 zhōngqī 指某个时期的中间阶段，是正确答案。"}, {"text": "工期", "is_correct": false, "explanation": "工期 gōngqī 与中期 zhōngqī 第一个音节声母不同（g 与 zh），意思是工程的施工期限。"}, {"text": "中秋", "is_correct": false, "explanation": "中秋 zhōngqiū 与中期 zhōngqī 第二个音节韵母多了一个 u，意思是中秋节。"}, {"text": "中企", "is_correct": false, "explanation": "中企 zhōngqǐ 与中期 zhōngqī 第二个音节声调不同（第三声与第一声），是“中国企业”的简称。"}], "explanations": {"中期": "中期 zhōngqī 指某个时期的中间阶段，是正确答案。", "工期": "工期 gōngqī 与中期 zhōngqī 第一个音节声母不同（g 与 zh），意思是工程的施工期限。", "中秋": "中秋 zhōngqiū 与中期 zhōngqī 第二个音节韵母多了一个 u，意思是中秋节。", "中企": "中企 zhōngqǐ 与中期 zhōngqī 第二个音节声调不同（第三声与第一声），是“中国企业”的简称。"}, "sentence_index": null, "correct_answer": "中期"}, "level_3": {"options": [{"text": "中期", "is_correct": true, "explanation": "“到了中期”指进入某个时期的中间阶段，与后面的进步情况相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“到了”不能用于一本书，“课本”不是可以到达的时间或阶段。"}, {"text": "词典", "is_correct": false, "explanation": "语义：“词典”不是时间或阶段，不能说“到了词典”。"}, {"text": "手指", "is_correct": false, "explanation": "搭配：“到了”后面不接身体部位，“到了手指”不成立。"}], "explanations": {"中期": "“到了中期”指进入某个时期的中间阶段，与后面的进步情况相符。", "课本": "语义：“到了”不能用于一本书，“课本”不是可以到达的时间或阶段。", "词典": "语义：“词典”不是时间或阶段，不能说“到了词典”。", "手指": "搭配：“到了”后面不接身体部位，“到了手指”不成立。"}, "sentence_index": 6, "correct_answer": "中期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个中期的孩子，很聪明。", "explanation": "这里应该用〈年幼〉。中期只表示时间阶段，不能用来形容孩子的年龄。"}, {"text": "她是我们班的中期，学习很努力。", "explanation": "这里应该用〈同学〉。中期表示时间阶段，不能用来指人。"}, {"text": "他的中期很高，篮球打得很好。", "explanation": "这里应该用〈身高〉。中期不能用来说人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "进入中期的以后，工作量明显增加了。", "corrected_sentence": "进入中期以后，工作量明显增加了。", "error_description": "“以后”前不能加“的”，“中期”后直接接“以后”，应说“进入中期以后”。写成“中期的以后”，多出了“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在项目中期的调整了方案。", "corrected_sentence": "我们在项目中期调整了方案。", "error_description": "“中期”后面多加了“的”，“中期的调整”变成了名词性短语，后面不能直接接“了”作谓语。应说“在项目中期调整了方案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
