INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94343, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "偶尔是很少，只有一两次。", "primary_collocate": null, "pronunciation": "ǒu ěr", "ipa": "oʊ˨˩˦ ɚ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家店我一年偶尔才去一两次。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很忙，偶尔打来一个电话。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了这么多年，我偶尔才收到他一封信。", "target_word": "偶尔", "complexity_tier": "T3", "furigana": "guò le zhè me duō nián, wǒ ǒu ěr cái shōu dào tā yì fēng xìn", "sentence_source": "generated"}, {"text": "爷爷不喝酒，只在过年时偶尔喝一点。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个月里，他偶尔迟到一两次。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不常生病，偶尔感冒一次。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路很安静，偶尔才有一辆车。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不爱说话，偶尔说一两句。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里很安静，偶尔才有人经过。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不抽烟，只有难过时偶尔抽一支。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "偶爾", "label": "繁体"}, {"form": "偶而", "label": "异形词"}], "register": "中性", "sense_fingerprint": "偶尔：很少发生，只有一两次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f50a9-5433-433b-b644-a8f9691ff3f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": true, "explanation": "正确：“偶尔才”表示很少发生，与“一年”和“一两次”搭配，符合句意。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示每次都如此，与“一年才去一两次”的少见意思矛盾。"}, {"text": "天天", "is_correct": false, "explanation": "语义：“天天”表示每天，与“一年才去一两次”的数量明显冲突。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词搭配，不能直接用在“才去”这样的肯定结构前。"}], "explanations": {"偶尔": "正确：“偶尔才”表示很少发生，与“一年”和“一两次”搭配，符合句意。", "总是": "语义：“总是”表示每次都如此，与“一年才去一两次”的少见意思矛盾。", "天天": "语义：“天天”表示每天，与“一年才去一两次”的数量明显冲突。", "根本": "搭配：“根本”通常与否定词搭配，不能直接用在“才去”这样的肯定结构前。"}, "sentence_index": 0, "correct_answer": "偶尔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷每天都偶尔喝酒，一天喝三次。", "explanation": "这里应该用〈经常〉。偶尔表示很少的一两次，与“每天都”和“一天喝三次”矛盾；每天都喝应说“经常”。"}, {"text": "爷爷偶尔每天散步，一天都不落下。", "explanation": "这里应该用〈一直〉。偶尔表示很少的一两次，与“每天散步，一天都不落下”矛盾；持续不断应说“一直”。"}, {"text": "爷爷偶尔不喝酒，每天都在家喝两杯。", "explanation": "这里应该用〈天天〉。偶尔表示很少的一两次，与“每天都在家喝两杯”矛盾；每天都喝应说“天天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": true, "explanation": "正确：“偶尔才有”表示很少出现，与“很安静”的环境搭配，符合句意。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“偶尔才有一辆车”的少见情况矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与句中描述的普遍稀少的情况不协调。"}, {"text": "一味", "is_correct": false, "explanation": "搭配：“一味”表示持续地做某事，不能修饰“才有一辆车”这样的存现结构。"}], "explanations": {"偶尔": "正确：“偶尔才有”表示很少出现，与“很安静”的环境搭配，符合句意。", "一直": "语义：“一直”表示持续不断，与“偶尔才有一辆车”的少见情况矛盾。", "立刻": "语义：“立刻”表示马上，与句中描述的普遍稀少的情况不协调。", "一味": "搭配：“一味”表示持续地做某事，不能修饰“才有一辆车”这样的存现结构。"}, "sentence_index": 6, "correct_answer": "偶尔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天偶尔抽烟，一天抽五支。", "explanation": "这里应该用〈经常〉。偶尔表示很少的一两次，与“每天”和“一天抽五支”矛盾；每天都抽应说“经常”。"}, {"text": "我偶尔早起，每天都在六点醒来。", "explanation": "这里应该用〈总是〉。偶尔表示很少的一两次，与“每天都在六点醒来”矛盾；习惯性早起应说“总是”。"}, {"text": "我偶尔不抽烟，每次都抽两包。", "explanation": "这里应该用〈常常〉。偶尔表示很少的一两次，与“每次都抽两包”矛盾；经常抽烟应说“常常”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一年很偶尔才回来一次。", "corrected_sentence": "他一年偶尔才回来一次。", "error_description": "“偶尔”是副词，前面不能加“很”修饰，应说“一年偶尔才回来一次”。错误形式“很偶尔才”多加了“很”，不符合副词“偶尔”的用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小区里很安静，偶尔了才有人散步。", "corrected_sentence": "小区里很安静，偶尔才有人散步。", "error_description": "“偶尔”是副词，后面不能直接接“了”；“偶尔才”表示少见的习惯性情况，不带完成标记，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
