INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94344, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94344, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "有时候，不经常。", "primary_collocate": null, "pronunciation": "ǒu ěr", "ipa": "oʊ˨˩˦ ɚ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我平时喝茶，偶尔也喝咖啡。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很少迟到，偶尔会晚几分钟。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家平时在家吃，偶尔去外面吃。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平时工作忙，周末偶尔去公园跑步。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很忙，偶尔才给妈妈打电话。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里夏天很热，偶尔下一场雨。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不爱看电视，偶尔看看新闻。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王住得远，偶尔来我家坐坐。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我平时坐地铁，偶尔也骑车上班。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李很认真，偶尔也会写错字。", "target_word": "偶尔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "偶爾", "label": "繁体"}, {"form": "偶而", "label": "异形词"}], "register": "中性", "sense_fingerprint": "偶尔：有时候做某事，但不经常", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f50a9-5433-433b-b644-a8f9691ff3f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": true, "explanation": "正确：“偶尔”表示不经常，与“也”连用，说明喝咖啡是少有的情况，符合句意。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示每次都如此，与“偶尔”的少见义冲突，也与“平时喝茶”的对比不通。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”说马上，句子讲的是习惯性地喝咖啡，无法接受。"}, {"text": "全都", "is_correct": false, "explanation": "搭配：“全都”要求复数的对象，句中只有“我”一个主语，不能这样修饰。"}], "explanations": {"偶尔": "正确：“偶尔”表示不经常，与“也”连用，说明喝咖啡是少有的情况，符合句意。", "总是": "语义：“总是”表示每次都如此，与“偶尔”的少见义冲突，也与“平时喝茶”的对比不通。", "立刻": "语义：“立刻”说马上，句子讲的是习惯性地喝咖啡，无法接受。", "全都": "搭配：“全都”要求复数的对象，句中只有“我”一个主语，不能这样修饰。"}, "sentence_index": 0, "correct_answer": "偶尔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天偶尔跑步，一周跑七次。", "explanation": "这里应该用〈经常〉。偶尔表示不经常、有时候，不能用于每天重复的动作；“每天跑步”应说“经常跑步”。"}, {"text": "他偶尔坚持跑步，从不间断。", "explanation": "这里应该用〈一直〉。偶尔表示有时候、不经常，与“从不间断”矛盾；要说持续不断，应用“一直”。"}, {"text": "小王偶尔从来不迟到，我们都很佩服。", "explanation": "这里应该用〈一直〉。偶尔表示有时候、不经常，与“从来不迟到”的全称否定矛盾；要说一贯如此，应用“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": true, "explanation": "正确：“偶尔”表示有时候，与“看看新闻”搭配，说明他很少看电视却偶尔看新闻，符合句意。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词搭配，不能直接修饰肯定的“看看”。"}, {"text": "总算", "is_correct": false, "explanation": "语义：“总算”表示终于，与“不爱看电视”这种习惯说法不协调。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即，句中讲的是习惯，与“马上看新闻”的语境不合。"}], "explanations": {"偶尔": "正确：“偶尔”表示有时候，与“看看新闻”搭配，说明他很少看电视却偶尔看新闻，符合句意。", "根本": "搭配：“根本”通常与否定词搭配，不能直接修饰肯定的“看看”。", "总算": "语义：“总算”表示终于，与“不爱看电视”这种习惯说法不协调。", "马上": "语义：“马上”表示立即，句中讲的是习惯，与“马上看新闻”的语境不合。"}, "sentence_index": 6, "correct_answer": "偶尔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小李每天都偶尔写错字，错误很多。", "explanation": "这里应该用〈经常〉。偶尔表示不经常，与“每天都”和“错误很多”矛盾；每天都出错应说“经常”。"}, {"text": "小李写字很快，偶尔一分钟写一百个字，每次都这样。", "explanation": "这里应该用〈经常〉。偶尔表示不经常，与“每次都这样”矛盾；要说每次都如此，应用“经常”。"}, {"text": "小李每次写字都偶尔写错，一次都不对。", "explanation": "这里应该用〈总是〉。偶尔表示有时候，与“每次都”和“一次都不对”的全部否定矛盾；要说每次都出错，应用“总是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他平时不爱运动，偶尔的去打打羽毛球。", "corrected_sentence": "他平时不爱运动，偶尔去打打羽毛球。", "error_description": "副词“偶尔”后面不加“的”，应直接说“偶尔去打打羽毛球”。错误形式“偶尔的去”多加了“的”，不符合副词的用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家住在郊区，很偶尔才有一班公交车。", "corrected_sentence": "我们家住在郊区，偶尔才有一班公交车。", "error_description": "“偶尔”是副词，前面不能加“很”修饰，应直接说“偶尔才有”，正确为“偶尔才有一班公交车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eceaa4b7-2400-41cb-ab93-853f5d4fec0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94345, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "“高兴”与“伤心”在心情的意义上构成反义，指心里愉快。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“伤心”没有反义关系，二者不描述同一种心情。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”指质地不光滑，与“伤心”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”指空间小，与“伤心”没有反义关系。"}], "correct_answer": "高兴", "explanations": {"高兴": "“高兴”与“伤心”在心情的意义上构成反义，指心里愉快。", "清楚": "“清楚”与“伤心”没有反义关系，二者不描述同一种心情。", "粗糙": "“粗糙”指质地不光滑，与“伤心”没有反义关系。", "狭窄": "“狭窄”指空间小，与“伤心”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94345, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "“高兴”与“伤心”在心情的意义上构成反义，指心里愉快。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与“伤心”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁，与“伤心”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "“宽阔”形容空间大，与“伤心”没有反义关系。"}], "correct_answer": "高兴", "explanations": {"高兴": "“高兴”与“伤心”在心情的意义上构成反义，指心里愉快。", "明亮": "“明亮”形容光线或颜色，与“伤心”没有反义关系。", "干净": "“干净”形容清洁，与“伤心”没有反义关系。", "宽阔": "“宽阔”形容空间大，与“伤心”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94345, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "伤心是心里难过，想哭。", "primary_collocate": null, "pronunciation": "shāng xīn", "ipa": "ʂaŋ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "听到这个坏消息，她很伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不见了，孩子伤心地哭了。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为什么这么伤心？", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友要搬走了，我真伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别伤心，明天会更好。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着旧照片，伤心极了。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好，他一个人伤心了半天。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看到我伤心的样子，也哭了。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的生日蛋糕掉在地上，我非常伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟丢了玩具，伤心得不想吃饭。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "伤心事", "label": "复合"}, {"form": "傷心", "label": "繁体"}], "register": "口语", "sense_fingerprint": "心里难过，想哭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de77f8f-f932-4d69-8d97-208873924bdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤心", "is_correct": true, "explanation": "“伤心”表示心里难过，与“听到这个坏消息”的语境相符。"}, {"text": "满意", "is_correct": false, "explanation": "语义：“满意”表示称心，与“坏消息”的语境相冲突。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不用来形容人听到消息时的状态。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：“粗鲁”指言行粗野，与听到坏消息后的情绪无关。"}], "explanations": {"伤心": "“伤心”表示心里难过，与“听到这个坏消息”的语境相符。", "满意": "语义：“满意”表示称心，与“坏消息”的语境相冲突。", "热闹": "搭配：“热闹”形容场面或气氛，不用来形容人听到消息时的状态。", "粗鲁": "语义：“粗鲁”指言行粗野，与听到坏消息后的情绪无关。"}, "sentence_index": 0, "correct_answer": "伤心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃坏了肚子，觉得很伤心。", "explanation": "这里应该用〈难受〉。〈伤心〉表示心里悲痛，身体不舒服要用〈难受〉。"}, {"text": "他考了满分，伤心极了。", "explanation": "这里应该用〈高兴〉。〈伤心〉表示悲痛，考了满分应该高兴。"}, {"text": "他拿到了冠军，他伤心得跳了起来。", "explanation": "这里应该用〈兴奋〉。〈伤心〉表示悲痛，拿到冠军的人跳起来应是兴奋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤心", "is_correct": true, "explanation": "“伤心”表示心里难过，与“考试没考好”的语境相符。"}, {"text": "得意", "is_correct": false, "explanation": "语义：“得意”表示称心自满，与“考试没考好”的语境相反。"}, {"text": "骄傲", "is_correct": false, "explanation": "语义：“骄傲”表示自满，与“考试没考好”的语境不符。"}, {"text": "调皮", "is_correct": false, "explanation": "搭配：“调皮”多形容孩子的顽皮行为，不与“一个人……半天”的悲伤情绪搭配。"}], "explanations": {"伤心": "“伤心”表示心里难过，与“考试没考好”的语境相符。", "得意": "语义：“得意”表示称心自满，与“考试没考好”的语境相反。", "骄傲": "语义：“骄傲”表示自满，与“考试没考好”的语境不符。", "调皮": "搭配：“调皮”多形容孩子的顽皮行为，不与“一个人……半天”的悲伤情绪搭配。"}, "sentence_index": 6, "correct_answer": "伤心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看到蛇，伤心得跑开了。", "explanation": "这里应该用〈害怕〉。〈伤心〉表示悲痛，遇到蛇的反应应是害怕。"}, {"text": "他看到大家都来了，伤心得拍手叫好。", "explanation": "这里应该用〈高兴〉。〈伤心〉表示悲痛，拍手叫好应是高兴。"}, {"text": "我说错了话，伤心得哈哈大笑。", "explanation": "这里应该用〈尴尬〉。〈伤心〉表示悲痛，哈哈大笑与悲痛矛盾；说错话后的反应应是〈尴尬〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息让我很伤心地。", "corrected_sentence": "这个消息让我很伤心。", "error_description": "“伤心”后多加了“地”：“伤心”在此作谓语，不能带“地”，应说“很伤心”，去掉“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹听到消息，伤心很哭了一场。", "corrected_sentence": "妹妹听到消息，伤心得哭了一场。", "error_description": "“伤心”后接动作时应用“得”引出程度或结果，不能用“很”：“很”只修饰形容词，不能放在动词“哭”前。应说“伤心得哭了一场”，把“很”改为“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "“高兴”与“伤心”在心情的意义上构成反义，指心里愉快。"}, {"text": "平整", "is_correct": false, "explanation": "“平整”形容表面没有起伏，与“伤心”没有反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”形容声音大而清楚，与“伤心”没有反义关系。"}, {"text": "湿润", "is_correct": false, "explanation": "“湿润”形容有水分，与“伤心”没有反义关系。"}], "correct_answer": "高兴", "explanations": {"高兴": "“高兴”与“伤心”在心情的意义上构成反义，指心里愉快。", "平整": "“平整”形容表面没有起伏，与“伤心”没有反义关系。", "响亮": "“响亮”形容声音大而清楚，与“伤心”没有反义关系。", "湿润": "“湿润”形容有水分，与“伤心”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "“高兴”与“伤心”在心情的意义上构成反义，指心里愉快。"}, {"text": "锋利", "is_correct": false, "explanation": "“锋利”形容刀刃等尖利，与“伤心”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地软，与“伤心”没有反义关系。"}, {"text": "整洁", "is_correct": false, "explanation": "“整洁”形容干净有条理，与“伤心”没有反义关系。"}], "correct_answer": "高兴", "explanations": {"高兴": "“高兴”与“伤心”在心情的意义上构成反义，指心里愉快。", "锋利": "“锋利”形容刀刃等尖利，与“伤心”没有反义关系。", "柔软": "“柔软”形容质地软，与“伤心”没有反义关系。", "整洁": "“整洁”形容干净有条理，与“伤心”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里悲痛难过。", "primary_collocate": null, "pronunciation": "shāng xīn", "ipa": "ʂaŋ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "奶奶去世后，全家人都很伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说起那件往事，仍然伤心不已。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友离开了，他伤心了很久。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到家乡被大水淹了，大家都很伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一提到儿子，就伤心起来。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个让人伤心的消息。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伤心地离开了这座城市。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去工作的那天，爸爸特别伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让她再想起伤心的事了。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说老师生病了，同学们都很伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "伤心事", "label": "复合"}, {"form": "傷心", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到不幸或损失而心里悲痛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de77f8f-f932-4d69-8d97-208873924bdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤心", "is_correct": true, "explanation": "“伤心”表示遇到不幸而心里悲痛，与“奶奶去世后”的语境相符。"}, {"text": "满意", "is_correct": false, "explanation": "语义：“满意”表示称心，与“奶奶去世”的悲痛语境冲突。"}, {"text": "得意", "is_correct": false, "explanation": "语义：“得意”表示自豪或称心，与“奶奶去世”不相容。"}, {"text": "调皮", "is_correct": false, "explanation": "搭配：“调皮”形容顽皮的行为，不用来形容全家人在丧事后的状态。"}], "explanations": {"伤心": "“伤心”表示遇到不幸而心里悲痛，与“奶奶去世后”的语境相符。", "满意": "语义：“满意”表示称心，与“奶奶去世”的悲痛语境冲突。", "得意": "语义：“得意”表示自豪或称心，与“奶奶去世”不相容。", "调皮": "搭配：“调皮”形容顽皮的行为，不用来形容全家人在丧事后的状态。"}, "sentence_index": 0, "correct_answer": "伤心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶病好了，全家人都很伤心。", "explanation": "这里应该用〈高兴〉。〈伤心〉表示悲痛，病好了应该高兴。"}, {"text": "同学还了我钱，我很伤心地道了谢。", "explanation": "这里应该用〈高兴〉。〈伤心〉表示悲痛，同学还钱后道谢应是高兴。"}, {"text": "听到雷声，他很伤心地跳起来欢呼。", "explanation": "这里应该用〈兴奋〉。〈伤心〉表示悲痛，跳起来欢呼应是兴奋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤心", "is_correct": true, "explanation": "“伤心”表示心里悲痛，与“他离开这座城市”的悲伤语境相符。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指物质丰足，不能用来形容离开的方式。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不描述人离开时的样子。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”形容缺少水分，不能描述人离开时的样子。"}], "explanations": {"伤心": "“伤心”表示心里悲痛，与“他离开这座城市”的悲伤语境相符。", "富裕": "语义：“富裕”指物质丰足，不能用来形容离开的方式。", "热闹": "搭配：“热闹”形容场面或气氛，不描述人离开时的样子。", "干燥": "语义：“干燥”形容缺少水分，不能描述人离开时的样子。"}, "sentence_index": 6, "correct_answer": "伤心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们跑完了操场，同学们都很伤心。", "explanation": "这里应该用〈累〉。〈伤心〉是心里难过，不形容身体疲劳。"}, {"text": "老师走进教室，同学们伤心地愣住了。", "explanation": "这里应该用〈惊讶〉。〈伤心〉表示悲痛，愣住的样子应是惊讶。"}, {"text": "同学们都得了奖，我却伤心得蹦蹦跳跳。", "explanation": "这里应该用〈高兴〉。〈伤心〉表示悲痛，蹦蹦跳跳应是高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人说起往事，伤心的哭了。", "corrected_sentence": "老人说起往事，伤心地哭了。", "error_description": "“伤心”修饰动词“哭”时应用“地”，不能用“的”：应说“伤心地哭了”，把“的”改为“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他伤心很哭了一整天。", "corrected_sentence": "他伤心得哭了一整天。", "error_description": "“伤心”引出动作的程度或结果时应用“得”，不能用“很”：“很”只修饰形容词，不能放在动词“哭”前。应说“伤心得哭了一整天”，把“很”改为“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
