INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "尿是身体里排出来的黄黄的水。", "primary_collocate": null, "pronunciation": "niào", "ipa": "njɑʊ̯⁵¹", "syllable_count": 1, "sentences": [{"text": "小狗在树下撒了一泡尿。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝的尿弄湿了衣服。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝水太少，尿会变得很黄。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尿是黄黄的，有一点味道。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生请他留一点尿去检查。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的尿里有血，要马上去医院。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天出汗多，尿就少了。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士拿着装尿的小杯子走进来。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上第一次的尿最适合检查。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把尿撒在了床上。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尿液", "label": "复合"}, {"form": "尿布", "label": "复合"}, {"form": "泡", "label": "量词"}], "register": "口语", "sense_fingerprint": "身体排出来的黄色的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bfe4bad-92c1-4f44-b603-5e8c3d54b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94377, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尿", "is_correct": true, "explanation": "尿（niào）：身体里排出来的黄色液体。"}, {"text": "鸟", "is_correct": false, "explanation": "鸟（niǎo）与 niào 声调不同（第三声与第四声），意思是鸟类。"}, {"text": "料", "is_correct": false, "explanation": "料（liào）与 niào 声母不同（l 与 n），意思是材料。"}, {"text": "叫", "is_correct": false, "explanation": "叫（jiào）与 niào 声母不同（j 与 n），意思是喊、叫唤。"}, {"text": "庙", "is_correct": false, "explanation": "庙（miào）与 niào 声母不同（m 与 n），意思是供奉神佛的地方。"}], "explanations": {"尿": "尿（niào）：身体里排出来的黄色液体。", "鸟": "鸟（niǎo）与 niào 声调不同（第三声与第四声），意思是鸟类。", "料": "料（liào）与 niào 声母不同（l 与 n），意思是材料。", "叫": "叫（jiào）与 niào 声母不同（j 与 n），意思是喊、叫唤。", "庙": "庙（miào）与 niào 声母不同（m 与 n），意思是供奉神佛的地方。"}, "sentence_index": null, "correct_answer": "尿"}, "level_3": {"options": [{"text": "尿", "is_correct": true, "explanation": "正确：“一泡”可用来计量尿，与“撒”搭配，指动物排出的黄色液体。"}, {"text": "奶", "is_correct": false, "explanation": "搭配：“泡”多用来计量尿、痰等排泄物，说“一泡奶”不自然，应说“一杯奶”。"}, {"text": "汗", "is_correct": false, "explanation": "语义：汗不是小狗排出的废物，不会被“撒”在树下，也不能用“一泡”计量。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水来自天空，不是动物身体排出的东西，不能说“撒了一泡”。"}], "explanations": {"尿": "正确：“一泡”可用来计量尿，与“撒”搭配，指动物排出的黄色液体。", "奶": "搭配：“泡”多用来计量尿、痰等排泄物，说“一泡奶”不自然，应说“一杯奶”。", "汗": "语义：汗不是小狗排出的废物，不会被“撒”在树下，也不能用“一泡”计量。", "雨水": "语义：雨水来自天空，不是动物身体排出的东西，不能说“撒了一泡”。"}, "sentence_index": 0, "correct_answer": "尿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天喝很多尿。", "explanation": "这里应该用〈水〉。尿是身体排出的废物，不能当饮品喝。"}, {"text": "工人用一桶尿刷墙。", "explanation": "这里应该用〈油漆〉。油漆是用来刷墙的，尿是身体排出的黄色液体，不能用来刷墙。"}, {"text": "孩子咳嗽，妈妈给他买了一瓶尿。", "explanation": "这里应该用〈糖浆〉。糖浆是买来治咳嗽的，尿不能当药买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94377, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尿", "is_correct": true, "explanation": "尿（niào）：身体里排出来的黄色液体。"}, {"text": "笑", "is_correct": false, "explanation": "笑（xiào）与 niào 声母不同（x 与 n），意思是高兴时发出的声音或表情。"}, {"text": "念", "is_correct": false, "explanation": "念（niàn）与 niào 韵母不同（-ian 与 -iao），意思是出声地读。"}, {"text": "酿", "is_correct": false, "explanation": "酿（niàng）与 niào 韵母不同（-iang 与 -iao），意思是利用发酵制造酒类。"}, {"text": "调", "is_correct": false, "explanation": "调（diào）与 niào 声母不同（d 与 n），意思是调整。"}], "explanations": {"尿": "尿（niào）：身体里排出来的黄色液体。", "笑": "笑（xiào）与 niào 声母不同（x 与 n），意思是高兴时发出的声音或表情。", "念": "念（niàn）与 niào 韵母不同（-ian 与 -iao），意思是出声地读。", "酿": "酿（niàng）与 niào 韵母不同（-iang 与 -iao），意思是利用发酵制造酒类。", "调": "调（diào）与 niào 声母不同（d 与 n），意思是调整。"}, "sentence_index": null, "correct_answer": "尿"}, "level_3": {"options": [{"text": "尿", "is_correct": true, "explanation": "正确：出汗多时排尿就少，“尿”指尿量，与“夏天出汗多”形成因果关系。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业与出汗无关，不会因为天热而变少。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机的数量与出汗无关，“就少了”在这里没有依据。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“少了”说数量，不能和“房间”搭配，房间只能说变小或变大。"}], "explanations": {"尿": "正确：出汗多时排尿就少，“尿”指尿量，与“夏天出汗多”形成因果关系。", "作业": "语义：作业与出汗无关，不会因为天热而变少。", "手机": "语义：手机的数量与出汗无关，“就少了”在这里没有依据。", "房间": "搭配：“少了”说数量，不能和“房间”搭配，房间只能说变小或变大。"}, "sentence_index": 6, "correct_answer": "尿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子把杯子里的尿喝光了。", "explanation": "这里应该用〈牛奶〉。尿是身体排出的废物，不能被喝掉。"}, {"text": "孩子认识了很多尿。", "explanation": "这里应该用〈字〉。认识的是字，尿是身体排出的液体，不能认识。"}, {"text": "孩子把尿当成了玩具。", "explanation": "这里应该用〈玩具〉。玩具是给孩子玩的，尿是身体排出的黄色液体，不能当玩具玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地板上有一大只尿。", "corrected_sentence": "地板上有一大摊尿。", "error_description": "量词错误：地上的一片尿要用〈摊〉计量，不能用〈只〉。应把“一大只尿”改为“一大摊尿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床单上有一大条尿。", "corrected_sentence": "床单上有一大泡尿。", "error_description": "量词错误：尿是液体，计量时应用〈泡〉，不能用〈条〉。应把“一大条尿”改为“一大泡尿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
