INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94378, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和动物从体内排出的液体废物。", "primary_collocate": null, "pronunciation": "niào", "ipa": "njɑʊ̯⁵¹", "syllable_count": 1, "sentences": [{"text": "医生说，尿的颜色能告诉我们身体好不好。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肾不好的人，尿里会有很多泡。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的尿有很重的味道。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的尿要送到医院的检验室。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体里多余的水会变成尿排出来。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动后喝水少，尿的量会变少。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尿里有糖，可能是生病了。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里尿多，老人睡不好觉。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前有人用牛的尿当肥料。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士请病人把尿装进小杯子里。", "target_word": "尿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尿液", "label": "复合"}, {"form": "尿布", "label": "复合"}, {"form": "泡", "label": "量词"}], "register": "口语", "sense_fingerprint": "人和动物排出的液体废物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bfe4bad-92c1-4f44-b603-5e8c3d54b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
